diffs.replacement:
{
  "name": "AuditPOS - Gestión de Material P.O.P.",
  "description": "Una plataforma avanzada para auditores de trade marketing para recopilar y analizar materiales de comunicación en el punto de venta (P.O.P.), utilizando IA para el análisis de visibilidad y cumplimiento.",
  "requestFramePermissions": [
    "camera",
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum MaterialType {
  POSTER = 'Afiche / Poster',
  WOBBLER = 'Wobbler',
  SHELF_TALKER = 'Cenefa / Shelf Talker',
  DISPLAY = 'Exhibidor / Floor Display',
  NECK_HANGER = 'Colgante de Cuello',
  OTHER = 'Otro'
}

export enum Condition {
  PERFECT = 'Perfecto Estado',
  DAMAGED = 'Dañado / Sucio',
  OUTDATED = 'Desactualizado',
  MISSING = 'Faltante'
}

export interface MaterialItem {
  id: string;
  type: MaterialType;
  condition: Condition;
  photoUrl?: string;
  photoBase64?: string;
  observations: string;
  quantity: number;
  aiAnalysis?: string;
}

export interface POSAudit {
  id: string;
  timestamp: number;
  storeName: string;
  address: string;
  auditorName: string;
  items: MaterialItem[];
  location?: {
    lat: number;
    lng: number;
  };
}

export interface DashboardStats {
  totalAudits: number;
  totalMaterials: number;
  complianceRate: number;
  pendingActions: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { MaterialItem, POSAudit } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeMaterialImage = async (base64Image: string, materialType: string): Promise<string> => {
  try {
    const ai = getAI();
    const prompt = `Analiza esta fotografía de un material de comunicación en punto de venta (P.O.P.) de tipo ${materialType}. 
    Evalúa lo siguiente:
    1. ¿Es claramente visible para el consumidor?
    2. ¿Está en buen estado físico (no arrugado, no roto)?
    3. ¿Se identifica claramente la marca?
    4. ¿Hay otros materiales de la competencia obstruyéndolo?
    Responde de forma concisa en español (máximo 300 caracteres).`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image.split(',')[1] || base64Image } },
          { text: prompt }
        ]
      }
    });

    return response.text || "No se pudo realizar el análisis automático.";
  } catch (error) {
    console.error("Error analyzing image with Gemini:", error);
    return "Error en el análisis de IA.";
  }
};

export const generateAuditSummary = async (audit: POSAudit): Promise<string> => {
  try {
    const ai = getAI();
    const itemsSummary = audit.items.map(i => `- ${i.type}: ${i.condition} (${i.quantity} uds)`).join('\n');
    const prompt = `Genera un resumen ejecutivo profesional para una auditoría de Trade Marketing.
    Tienda: ${audit.storeName}
    Ubicación: ${audit.address}
    Auditor: ${audit.auditorName}
    Materiales encontrados:
    ${itemsSummary}

    Proporciona 3 puntos clave (insights) y una recomendación general. Usa un tono ejecutivo y directo.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt
    });

    return response.text || "Resumen no disponible.";
  } catch (error) {
    console.error("Error generating summary:", error);
    return "Error generando el resumen ejecutivo.";
  }
};

import React from 'react';
import { LayoutDashboard, ClipboardCheck, History, Menu, X } from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: 'dashboard' | 'new-audit' | 'history';
  onTabChange: (tab: 'dashboard' | 'new-audit' | 'history') => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange }) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = React.useState(false);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'new-audit', label: 'Nueva Auditoría', icon: ClipboardCheck },
    { id: 'history', label: 'Historial', icon: History },
  ];

  return (
    <div className="min-h-screen flex flex-col md:flex-row">
      {/* Mobile Header */}
      <header className="md:hidden bg-white border-b px-4 py-3 flex justify-between items-center sticky top-0 z-50">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
            <ClipboardCheck size={20} />
          </div>
          <span className="font-bold text-lg tracking-tight">AuditPOS</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </header>

      {/* Sidebar */}
      <aside className={`
        fixed inset-0 z-40 bg-slate-900 text-white w-64 transform transition-transform duration-300 md:relative md:translate-x-0
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6">
          <div className="flex items-center gap-3 mb-10 hidden md:flex">
            <div className="w-10 h-10 bg-blue-500 rounded-xl flex items-center justify-center">
              <ClipboardCheck size={24} />
            </div>
            <span className="font-bold text-xl tracking-tight">AuditPOS</span>
          </div>

          <nav className="space-y-1">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  onTabChange(item.id as any);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${
                  activeTab === item.id 
                    ? 'bg-blue-600 text-white' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <item.icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            ))}
          </nav>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 bg-slate-50 overflow-y-auto">
        <div className="max-w-6xl mx-auto p-4 md:p-8">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { TrendingUp, Package, AlertCircle, CheckCircle } from 'lucide-react';
import { POSAudit, DashboardStats } from '../types';

interface DashboardProps {
  audits: POSAudit[];
}

const Dashboard: React.FC<DashboardProps> = ({ audits }) => {
  const stats: DashboardStats = {
    totalAudits: audits.length,
    totalMaterials: audits.reduce((acc, curr) => acc + curr.items.reduce((a, c) => a + c.quantity, 0), 0),
    complianceRate: audits.length > 0 
      ? Math.round((audits.reduce((acc, curr) => {
          const perfect = curr.items.filter(i => i.condition === 'Perfecto Estado').length;
          return acc + (perfect / Math.max(1, curr.items.length));
        }, 0) / audits.length) * 100)
      : 0,
    pendingActions: audits.reduce((acc, curr) => 
      acc + curr.items.filter(i => i.condition === 'Faltante' || i.condition === 'Dañado / Sucio').length, 0
    ),
  };

  const conditionData = [
    { name: 'Perfecto', value: audits.reduce((acc, a) => acc + a.items.filter(i => i.condition === 'Perfecto Estado').length, 0), color: '#10b981' },
    { name: 'Dañado', value: audits.reduce((acc, a) => acc + a.items.filter(i => i.condition === 'Dañado / Sucio').length, 0), color: '#f59e0b' },
    { name: 'Faltante', value: audits.reduce((acc, a) => acc + a.items.filter(i => i.condition === 'Faltante').length, 0), color: '#ef4444' },
    { name: 'Antiguo', value: audits.reduce((acc, a) => acc + a.items.filter(i => i.condition === 'Desactualizado').length, 0), color: '#6366f1' },
  ].filter(d => d.value > 0);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-bold text-slate-900">Vista General</h1>
        <p className="text-slate-500 mt-1">Resumen del cumplimiento de materiales en punto de venta.</p>
      </header>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Auditorías Totales', value: stats.totalAudits, icon: TrendingUp, color: 'blue' },
          { label: 'Materiales Auditados', value: stats.totalMaterials, icon: Package, color: 'indigo' },
          { label: 'Cumplimiento', value: `${stats.complianceRate}%`, icon: CheckCircle, color: 'emerald' },
          { label: 'Alertas / Acciones', value: stats.pendingActions, icon: AlertCircle, color: 'rose' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
            <div className={`w-12 h-12 rounded-xl bg-${stat.color}-50 flex items-center justify-center text-${stat.color}-600 mb-4`}>
              <stat.icon size={24} />
            </div>
            <div className="text-2xl font-bold text-slate-900">{stat.value}</div>
            <div className="text-sm text-slate-500">{stat.label}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Chart 1: Condition Distribution */}
        <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold mb-6">Estado de los Materiales</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={conditionData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {conditionData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="grid grid-cols-2 gap-2 mt-4">
            {conditionData.map((d, i) => (
              <div key={i} className="flex items-center gap-2 text-xs text-slate-600">
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: d.color }}></div>
                <span>{d.name}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Recent Activity List */}
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-semibold">Auditorías Recientes</h3>
            <button className="text-sm text-blue-600 font-medium hover:underline">Ver todas</button>
          </div>
          <div className="space-y-4">
            {audits.length === 0 ? (
              <div className="text-center py-12 text-slate-400">No hay auditorías registradas aún.</div>
            ) : (
              audits.slice(0, 5).map((audit) => (
                <div key={audit.id} className="flex items-center justify-between p-4 rounded-xl border border-slate-50 bg-slate-50/50 hover:bg-slate-50 transition-colors">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center font-bold">
                      {audit.storeName.charAt(0)}
                    </div>
                    <div>
                      <div className="font-semibold text-slate-900">{audit.storeName}</div>
                      <div className="text-xs text-slate-500">{new Date(audit.timestamp).toLocaleDateString()} • {audit.items.length} materiales</div>
                    </div>
                  </div>
                  <div className="hidden sm:block text-right">
                    <div className="text-sm text-slate-600">{audit.auditorName}</div>
                    <div className="text-xs text-slate-400">{audit.address}</div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit } from '../types';
import { analyzeMaterialImage } from '../services/geminiService';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave }) => {
  const [storeName, setStoreName] = useState('');
  const [address, setAddress] = useState('');
  const [auditorName, setAuditorName] = useState('');
  const [items, setItems] = useState<MaterialItem[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [analyzingItemIds, setAnalyzingItemIds] = useState<Set<string>>(new Set());

  const handleAddItem = () => {
    const newItem: MaterialItem = {
      id: crypto.randomUUID(),
      type: MaterialType.POSTER,
      condition: Condition.PERFECT,
      observations: '',
      quantity: 1,
    };
    setItems([...items, newItem]);
  };

  const handleRemoveItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleItemChange = (id: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handlePhotoUpload = async (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      handleItemChange(id, 'photoBase64', base64String);

      // Auto-analyze with AI
      const item = items.find(i => i.id === id);
      if (item) {
        setAnalyzingItemIds(prev => new Set(prev).add(id));
        const analysis = await analyzeMaterialImage(base64String, item.type);
        handleItemChange(id, 'aiAnalysis', analysis);
        setAnalyzingItemIds(prev => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName || !auditorName || items.length === 0) {
      alert('Por favor complete los campos obligatorios y agregue al menos un material.');
      return;
    }

    setIsSubmitting(true);

    // Simulate location retrieval
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeName,
          address,
          auditorName,
          items,
          location: {
            lat: pos.coords.latitude,
            lng: pos.coords.longitude
          }
        };
        onSave(audit);
        setIsSubmitting(false);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeName,
          address,
          auditorName,
          items,
        };
        onSave(audit);
        setIsSubmitting(false);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-slate-900">Nueva Auditoría</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Store Info */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 space-y-4">
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <MapPin size={20} className="text-blue-500" />
            Información del Punto de Venta
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Nombre de la Tienda *</label>
              <input
                type="text"
                required
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                value={storeName}
                onChange={e => setStoreName(e.target.value)}
                placeholder="Ej: Supermercado El Trébol"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Dirección / Referencia</label>
              <input
                type="text"
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                value={address}
                onChange={e => setAddress(e.target.value)}
                placeholder="Av. Principal 123"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Nombre del Auditor *</label>
              <input
                type="text"
                required
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                value={auditorName}
                onChange={e => setAuditorName(e.target.value)}
                placeholder="Su nombre"
              />
            </div>
          </div>
        </section>

        {/* Materials List */}
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-semibold flex items-center gap-2">
              <Package size={20} className="text-blue-500" />
              Materiales Registrados ({items.length})
            </h2>
            <button
              type="button"
              onClick={handleAddItem}
              className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors font-medium text-sm"
            >
              <Plus size={18} />
              Agregar Material
            </button>
          </div>

          {items.map((item, index) => (
            <div key={item.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 animate-in fade-in zoom-in duration-300">
              <div className="flex justify-between items-start mb-4">
                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-1 rounded-md">ITEM #{index + 1}</span>
                <button
                  type="button"
                  onClick={() => handleRemoveItem(item.id)}
                  className="text-slate-400 hover:text-rose-500 transition-colors"
                >
                  <Trash2 size={18} />
                </button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                {/* Photo Section */}
                <div className="lg:col-span-3 space-y-2">
                  <div className="relative aspect-square rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden group">
                    {item.photoBase64 ? (
                      <>
                        <img src={item.photoBase64} alt="Preview" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <label className="cursor-pointer text-white flex flex-col items-center gap-1">
                            <Camera size={24} />
                            <span className="text-xs font-medium">Cambiar</span>
                            <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handlePhotoUpload(item.id, e.target.files[0])} />
                          </label>
                        </div>
                      </>
                    ) : (
                      <label className="cursor-pointer w-full h-full flex flex-col items-center justify-center text-slate-400 hover:text-blue-500 transition-colors">
                        <Camera size={32} />
                        <span className="text-xs font-medium mt-2">Tomar Foto</span>
                        <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handlePhotoUpload(item.id, e.target.files[0])} />
                      </label>
                    )}
                  </div>
                </div>

                {/* Info Section */}
                <div className="lg:col-span-9 space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Tipo de Material</label>
                      <select
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                        value={item.type}
                        onChange={e => handleItemChange(item.id, 'type', e.target.value)}
                      >
                        {Object.values(MaterialType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Estado</label>
                      <select
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                        value={item.condition}
                        onChange={e => handleItemChange(item.id, 'condition', e.target.value)}
                      >
                        {Object.values(Condition).map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
                    <div className="sm:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Cantidad</label>
                      <input
                        type="number"
                        min="1"
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                        value={item.quantity}
                        onChange={e => handleItemChange(item.id, 'quantity', parseInt(e.target.value))}
                      />
                    </div>
                    <div className="sm:col-span-3">
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Observaciones</label>
                      <input
                        type="text"
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                        value={item.observations}
                        onChange={e => handleItemChange(item.id, 'observations', e.target.value)}
                        placeholder="Detalles adicionales..."
                      />
                    </div>
                  </div>

                  {/* AI Analysis Result */}
                  {(analyzingItemIds.has(item.id) || item.aiAnalysis) && (
                    <div className="mt-4 p-4 rounded-xl bg-slate-50 border border-slate-100 flex gap-3">
                      <div className="mt-1">
                        {analyzingItemIds.has(item.id) ? (
                          <Loader2 className="animate-spin text-blue-500" size={18} />
                        ) : (
                          <Sparkles className="text-blue-500" size={18} />
                        )}
                      </div>
                      <div>
                        <div className="text-xs font-bold text-slate-700 flex items-center gap-2">
                          ANÁLISIS DE INTELIGENCIA ARTIFICIAL
                          {analyzingItemIds.has(item.id) && <span className="font-normal text-blue-500">(Analizando...)</span>}
                        </div>
                        <p className="text-sm text-slate-600 mt-1">
                          {analyzingItemIds.has(item.id) ? "Nuestra IA está evaluando la calidad y visibilidad del material..." : item.aiAnalysis}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}

          {items.length === 0 && (
            <div className="text-center py-12 bg-white rounded-2xl border-2 border-dashed border-slate-200">
              <div className="mx-auto w-12 h-12 bg-slate-50 text-slate-400 rounded-full flex items-center justify-center mb-4">
                <ImageIcon size={24} />
              </div>
              <p className="text-slate-500">Comience agregando los materiales que ha encontrado en la tienda.</p>
            </div>
          )}
        </section>

        {/* Action Buttons */}
        <div className="sticky bottom-4 z-10 flex gap-4 pt-4">
          <button
            type="submit"
            disabled={isSubmitting || items.length === 0}
            className="flex-1 bg-blue-600 text-white px-6 py-4 rounded-xl font-bold shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />}
            Finalizar Auditoría
          </button>
        </div>
      </form>
    </div>
  );
};

