import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { TrendingUp, Package, AlertCircle, CheckCircle, Ban } from 'lucide-react';
import { POSAudit, DashboardStats, StoreStatus } from '../types';

interface DashboardProps {
  audits: POSAudit[];
}

const Dashboard: React.FC<DashboardProps> = ({ audits }) => {
  const stats: DashboardStats = {
    totalAudits: audits.length,
    totalMaterials: audits.reduce((acc, curr) => acc + (curr.items?.reduce((a, c) => a + c.quantity, 0) || 0), 0),
    complianceRate: audits.length > 0 
      ? Math.round((audits.reduce((acc, curr) => {
          const items = curr.items || [];
          const perfect = items.filter(i => i.condition === 'Perfecto Estado').length;
          return acc + (perfect / Math.max(1, items.length));
        }, 0) / audits.length) * 100)
      : 0,
    pendingActions: audits.reduce((acc, curr) => 
      acc + (curr.items?.filter(i => i.condition === 'Faltante' || i.condition === 'Dañado / Sucio').length || 0), 0
    ),
    totalOOS: audits.reduce((acc, curr) => acc + (curr.oosItems?.length || 0), 0),
  };

  const conditionData = [
    { name: 'Perfecto', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Perfecto Estado').length || 0), 0), color: '#10b981' },
    { name: 'Dañado', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Dañado / Sucio').length || 0), 0), color: '#f59e0b' },
    { name: 'Faltante', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Faltante').length || 0), 0), color: '#ef4444' },
    { name: 'Antiguo', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Desactualizado').length || 0), 0), color: '#6366f1' },
  ].filter(d => d.value > 0);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-bold text-slate-900">Vista General</h1>
        <p className="text-slate-500 mt-1">Resumen del cumplimiento de materiales en punto de venta.</p>
      </header>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
        {[
          { label: 'Auditorías', value: stats.totalAudits, icon: TrendingUp, color: 'blue' },
          { label: 'Materiales', value: stats.totalMaterials, icon: Package, color: 'indigo' },
          { label: 'Cumplimiento', value: `${stats.complianceRate}%`, icon: CheckCircle, color: 'emerald' },
          { label: 'Quiebres SKUs', value: stats.totalOOS, icon: Ban, color: 'rose' },
          { label: 'Alertas POP', value: stats.pendingActions, icon: AlertCircle, color: 'amber' },
        ].map((stat, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
            <div className={`w-12 h-12 rounded-xl bg-${stat.color}-50 flex items-center justify-center text-${stat.color}-600 mb-4`}>
              <stat.icon size={24} />
            </div>
            <div className="text-2xl font-bold text-slate-900">{stat.value}</div>
            <div className="text-sm text-slate-500">{stat.label}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Chart 1: Condition Distribution */}
        <div className="lg:col-span-1 bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-semibold mb-6">Estado de los Materiales</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={conditionData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {conditionData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="grid grid-cols-2 gap-2 mt-4">
            {conditionData.map((d, i) => (
              <div key={i} className="flex items-center gap-2 text-xs text-slate-600">
