import React, { useState } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem } from '../types';
import { analyzeMaterialImage } from '../services/geminiService';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave }) => {
  const [storeName, setStoreName] = useState('');
  const [address, setAddress] = useState('');
  const [auditorName, setAuditorName] = useState('');
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [items, setItems] = useState<MaterialItem[]>([]);
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [analyzingItemIds, setAnalyzingItemIds] = useState<Set<string>>(new Set());

  const handleAddItem = () => {
    const newItem: MaterialItem = {
      id: crypto.randomUUID(),
      type: MaterialType.POSTER,
      condition: Condition.PERFECT,
      observations: '',
      quantity: 1,
    };
    setItems([...items, newItem]);
  };

  const handleAddOOSItem = () => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      skuName: '',
      comment: '',
    };
    setOosItems([...oosItems, newOos]);
  };

  const handleRemoveItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleRemoveOOSItem = (id: string) => {
    setOosItems(oosItems.filter(item => item.id !== id));
  };

  const handleItemChange = (id: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleOOSChange = (id: string, field: keyof OOSItem, value: string) => {
    setOosItems(oosItems.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handlePhotoUpload = async (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      handleItemChange(id, 'photoBase64', base64String);

      const item = items.find(i => i.id === id);
      if (item) {
        setAnalyzingItemIds(prev => new Set(prev).add(id));
        const analysis = await analyzeMaterialImage(base64String, item.type);
        handleItemChange(id, 'aiAnalysis', analysis);
        setAnalyzingItemIds(prev => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName || !auditorName) {
      alert('Por favor complete los campos obligatorios.');
      return;
    }

    setIsSubmitting(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeName,
          address,
          auditorName,
          storeStatus,
          items,
          oosItems,
          location: {
            lat: pos.coords.latitude,
            lng: pos.coords.longitude
          }
        };
        onSave(audit);
        setIsSubmitting(false);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeName,
          address,
          auditorName,
          storeStatus,
          items,
          oosItems,
        };
        onSave(audit);
        setIsSubmitting(false);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-slate-900">Nueva Auditoría</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Store Status Selection */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-semibold flex items-center gap-2 mb-4">
            <Store size={20} className="text-blue-500" />
            Estado de la Tienda
          </h2>
          <div className="flex gap-4">
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.OPEN)}
              className={`flex-1 flex items-center justify-center gap-3 p-4 rounded-xl border-2 transition-all ${
                storeStatus === StoreStatus.OPEN 
                ? 'bg-green-50 border-green-500 text-green-700 shadow-sm' 
                : 'bg-white border-slate-100 text-slate-400 grayscale'
              }`}
            >
              <CheckCircle2 size={24} />
              <span className="font-bold uppercase tracking-tight">Tienda Abierta</span>
            </button>
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.CLOSED)}
              className={`flex-1 flex items-center justify-center gap-3 p-4 rounded-xl border-2 transition-all ${
                storeStatus === StoreStatus.CLOSED 
                ? 'bg-red-50 border-red-500 text-red-700 shadow-sm' 
                : 'bg-white border-slate-100 text-slate-400 grayscale'
