              type="button"
              onClick={handleAddOOSItem}
              className="flex items-center gap-2 px-4 py-2 bg-rose-50 text-rose-600 rounded-lg hover:bg-rose-100 transition-colors font-medium text-sm"
            >
              <Plus size={18} />
              Registrar Quiebre
            </button>
          </div>

          <div className="space-y-3">
            {oosItems.map((oos, idx) => (
              <div key={oos.id} className="bg-white p-4 rounded-xl border border-slate-100 shadow-sm flex flex-col md:flex-row gap-4 items-start md:items-center">
                <div className="flex-1 w-full">
                  <input
                    type="text"
                    required
                    placeholder="Nombre del SKU (ej: Coca Cola 2L)"
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-rose-500 outline-none text-sm"
                    value={oos.skuName}
                    onChange={e => handleOOSChange(oos.id, 'skuName', e.target.value)}
                  />
                </div>
                <div className="flex-[1.5] w-full">
                  <input
                    type="text"
                    placeholder="Comentario / Motivo"
                    className="w-full px-3 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-rose-500 outline-none text-sm"
                    value={oos.comment}
                    onChange={e => handleOOSChange(oos.id, 'comment', e.target.value)}
                  />
                </div>
                <button
                  type="button"
                  onClick={() => handleRemoveOOSItem(oos.id)}
                  className="p-2 text-slate-300 hover:text-rose-500 transition-colors self-end md:self-center"
                >
                  <Trash2 size={18} />
                </button>
              </div>
            ))}
            {oosItems.length === 0 && (
              <div className="p-8 text-center bg-slate-50/50 rounded-xl border border-dashed border-slate-200 text-slate-400 text-sm">
                No hay quiebres registrados.
              </div>
            )}
          </div>
        </section>

        {/* Materials List */}
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-semibold flex items-center gap-2">
              <Package size={20} className="text-blue-500" />
              Material POP ({items.length})
            </h2>
            <button
              type="button"
              onClick={handleAddItem}
              className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors font-medium text-sm"
            >
              <Plus size={18} />
              Agregar Material
            </button>
          </div>

          {items.map((item, index) => (
            <div key={item.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 animate-in fade-in zoom-in duration-300">
              <div className="flex justify-between items-start mb-4">
                <span className="bg-blue-100 text-blue-700 text-xs font-bold px-2 py-1 rounded-md tracking-widest">MATERIAL P.O.P. #{index + 1}</span>
                <button
                  type="button"
                  onClick={() => handleRemoveItem(item.id)}
                  className="text-slate-400 hover:text-rose-500 transition-colors"
                >
                  <Trash2 size={18} />
                </button>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                <div className="lg:col-span-3 space-y-2">
                  <div className="relative aspect-square rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden group">
                    {item.photoBase64 ? (
                      <>
                        <img src={item.photoBase64} alt="Preview" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <label className="cursor-pointer text-white flex flex-col items-center gap-1">
                            <Camera size={24} />
                            <span className="text-xs font-medium">Cambiar</span>
                            <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handlePhotoUpload(item.id, e.target.files[0])} />
                          </label>
                        </div>
                      </>
                    ) : (
                      <label className="cursor-pointer w-full h-full flex flex-col items-center justify-center text-slate-400 hover:text-blue-500 transition-colors">
                        <Camera size={32} />
                        <span className="text-xs font-medium mt-2">Tomar Foto</span>
                        <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handlePhotoUpload(item.id, e.target.files[0])} />
                      </label>
                    )}
                  </div>
                </div>

                <div className="lg:col-span-9 space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Tipo de Material</label>
                      <select
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50"
                        value={item.type}
                        onChange={e => handleItemChange(item.id, 'type', e.target.value)}
                      >
                        {Object.values(MaterialType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Estado Físico</label>
                      <select
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50"
                        value={item.condition}
                        onChange={e => handleItemChange(item.id, 'condition', e.target.value)}
                      >
                        {Object.values(Condition).map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
                    <div className="sm:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Cantidad</label>
                      <input
                        type="number"
                        min="1"
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50"
                        value={item.quantity}
                        onChange={e => handleItemChange(item.id, 'quantity', parseInt(e.target.value))}
                      />
                    </div>
                    <div className="sm:col-span-3">
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Notas del Auditor</label>
                      <input
                        type="text"
                        className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50"
                        value={item.observations}
                        onChange={e => handleItemChange(item.id, 'observations', e.target.value)}
                        placeholder="Ej: Ubicado en entrada principal"
                      />
                    </div>
                  </div>

                  {(analyzingItemIds.has(item.id) || item.aiAnalysis) && (
                    <div className="mt-4 p-4 rounded-xl bg-blue-50/50 border border-blue-100 flex gap-3">
                      <div className="mt-1">
                        {analyzingItemIds.has(item.id) ? (
                          <Loader2 className="animate-spin text-blue-500" size={18} />
                        ) : (
                          <Sparkles className="text-blue-500" size={18} />
                        )}
                      </div>
                      <div>
                        <div className="text-[10px] font-black text-blue-700 tracking-tighter flex items-center gap-2 uppercase">
                          Gemini Vision Insights
                        </div>
                        <p className="text-sm text-slate-600 mt-1 italic">
                          {analyzingItemIds.has(item.id) ? "Nuestra IA está analizando la imagen..." : item.aiAnalysis}
                        </p>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}

          {items.length === 0 && (
            <div className="text-center py-12 bg-white rounded-2xl border-2 border-dashed border-slate-200">
              <div className="mx-auto w-12 h-12 bg-slate-50 text-slate-400 rounded-full flex items-center justify-center mb-4">
                <ImageIcon size={24} />
              </div>
              <p className="text-slate-500 text-sm">No hay materiales registrados. Haz clic en "Agregar Material" para comenzar.</p>
            </div>
          )}
        </section>

        {/* Action Buttons */}
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-6xl z-50 flex gap-4">
          <button
            type="submit"
            disabled={isSubmitting}
            className="flex-1 bg-slate-900 text-white px-6 py-4 rounded-2xl font-bold shadow-2xl hover:bg-black transition-all flex items-center justify-center gap-3 disabled:opacity-50"
          >
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />}
            Finalizar y Guardar Reporte
          </button>
        </div>
      </form>
    </div>
  );
};

