import React, { useState } from 'react';
import { ChevronRight, Calendar, User, MapPin, Search, FileText, X, Image as ImageIcon, Store, Ban } from 'lucide-react';
import { POSAudit, StoreStatus } from '../types';
import { generateAuditSummary } from '../services/geminiService';

interface HistoryViewProps {
  audits: POSAudit[];
}

const HistoryView: React.FC<HistoryViewProps> = ({ audits }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedAudit, setSelectedAudit] = useState<POSAudit | null>(null);
  const [isGeneratingSummary, setIsGeneratingSummary] = useState(false);
  const [aiSummary, setAiSummary] = useState<string | null>(null);

  const filteredAudits = audits
    .filter(a => 
      a.storeName.toLowerCase().includes(searchTerm.toLowerCase()) || 
      a.auditorName.toLowerCase().includes(searchTerm.toLowerCase())
    )
    .sort((a, b) => b.timestamp - a.timestamp);

  const handleOpenDetail = async (audit: POSAudit) => {
    setSelectedAudit(audit);
    setAiSummary(null);
    setIsGeneratingSummary(true);
    const summary = await generateAuditSummary(audit);
    setAiSummary(summary);
    setIsGeneratingSummary(false);
  };

  return (
    <div className="space-y-6">
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Historial de Auditorías</h1>
          <p className="text-slate-500">Consulta de registros y quiebres detectados.</p>
        </div>
        <div className="relative w-full sm:w-64">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            type="text"
            placeholder="Tienda o auditor..."
            className="w-full pl-10 pr-4 py-2 rounded-lg border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500 transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>
      </header>

      <div className="grid gap-4">
        {filteredAudits.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-2xl border border-slate-100">
            <p className="text-slate-400">Sin registros que coincidan.</p>
          </div>
        ) : (
          filteredAudits.map(audit => (
            <div
              key={audit.id}
              onClick={() => handleOpenDetail(audit)}
              className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 hover:border-blue-200 cursor-pointer transition-all flex items-center justify-between group"
            >
              <div className="flex gap-4 items-center">
                <div className="w-12 h-12 bg-slate-50 rounded-xl flex items-center justify-center text-blue-600 font-bold text-lg group-hover:bg-blue-50 relative">
                  {audit.storeName.charAt(0)}
                  <div className={`absolute -bottom-1 -right-1 w-3 h-3 rounded-full border-2 border-white ${audit.storeStatus === StoreStatus.OPEN ? 'bg-green-500' : 'bg-red-500'}`}></div>
                </div>
                <div>
                  <h3 className="font-bold text-slate-900">{audit.storeName}</h3>
                  <div className="flex flex-wrap gap-x-4 gap-y-1 mt-1">
                    <span className="flex items-center gap-1 text-xs text-slate-500">
                      <Calendar size={12} />
                      {new Date(audit.timestamp).toLocaleDateString()}
                    </span>
                    <span className="flex items-center gap-1 text-xs text-slate-500">
                      <User size={12} />
                      {audit.auditorName}
                    </span>
                    <span className={`flex items-center gap-1 text-[10px] font-bold uppercase ${audit.storeStatus === StoreStatus.OPEN ? 'text-green-600' : 'text-red-600'}`}>
                      <Store size={10} />
                      {audit.storeStatus}
                    </span>
                  </div>
                </div>
              </div>
              <ChevronRight className="text-slate-300 group-hover:text-blue-500 group-hover:translate-x-1 transition-all" />
            </div>
          ))
        )}
      </div>

      {selectedAudit && (
        <div className="fixed inset-0 z-[60] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-3xl overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200 flex flex-col">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50">
              <div className="flex items-center gap-4">
                <div className={`p-2 rounded-lg ${selectedAudit.storeStatus === StoreStatus.OPEN ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                  <Store size={20} />
                </div>
                <div>
                  <h2 className="text-xl font-bold text-slate-900">{selectedAudit.storeName}</h2>
                  <p className="text-sm text-slate-500">{selectedAudit.storeStatus} • {new Date(selectedAudit.timestamp).toLocaleString()}</p>
                </div>
              </div>
              <button onClick={() => setSelectedAudit(null)} className="p-2 hover:bg-white rounded-full transition-colors">
                <X size={24} />
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-8">
              {/* AI Insight Section */}
              <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-xl relative overflow-hidden">
                <div className="relative z-10">
                  <h3 className="flex items-center gap-2 font-bold mb-3 text-blue-400">
                    <Sparkles size={18} />
                    Audit Summary (Gemini AI)
                  </h3>
                  {isGeneratingSummary ? (
                    <div className="flex items-center gap-3 text-slate-400 py-2">
                      <Loader2 className="animate-spin" size={18} />
                      <span className="text-sm">Generando resumen ejecutivo...</span>
                    </div>
                  ) : (
                    <p className="text-sm text-slate-200 leading-relaxed whitespace-pre-wrap font-medium">{aiSummary}</p>
                  )}
                </div>
                <div className="absolute top-0 right-0 -mt-10 -mr-10 w-40 h-40 bg-blue-500/10 rounded-full blur-3xl"></div>
              </div>

              {/* OOS Section */}
              <div className="space-y-4">
                <h3 className="font-bold text-lg text-slate-900 flex items-center gap-2">
                  <Ban size={20} className="text-rose-500" />
                  Quiebres de Stock Detectados ({selectedAudit.oosItems?.length || 0})
                </h3>
                <div className="grid gap-2">
                  {selectedAudit.oosItems && selectedAudit.oosItems.length > 0 ? (
                    selectedAudit.oosItems.map((sku) => (
                      <div key={sku.id} className="p-4 bg-rose-50/30 rounded-xl border border-rose-100 flex justify-between items-center">
                        <div>
                          <div className="font-bold text-slate-900">{sku.skuName}</div>
                          <div className="text-xs text-slate-500 italic mt-0.5">{sku.comment || 'Sin comentarios'}</div>
                        </div>
                        <div className="px-3 py-1 bg-rose-100 text-rose-700 text-[10px] font-black uppercase rounded-full">OOS</div>
                      </div>
                    ))
                  ) : (
                    <div className="p-4 text-center text-slate-400 text-sm bg-slate-50 rounded-xl">No se reportaron quiebres.</div>
                  )}
                </div>
              </div>

              {/* POP Items Detail Grid */}
              <div className="space-y-4">
                <h3 className="font-bold text-lg text-slate-900 flex items-center gap-2">
                  <Package size={20} className="text-blue-500" />
                  Material P.O.P. Auditado ({selectedAudit.items?.length || 0})
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {selectedAudit.items?.map((item) => (
                    <div key={item.id} className="border border-slate-100 rounded-2xl overflow-hidden flex bg-slate-50/50">
                      <div className="w-32 h-32 bg-slate-200 shrink-0">
                        {item.photoBase64 ? (
                          <img src={item.photoBase64} alt="POP" className="w-full h-full object-cover" />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-slate-400"><ImageIcon /></div>
                        )}
                      </div>
                      <div className="p-4 flex-1">
                        <div className="font-bold text-slate-900 text-sm">{item.type}</div>
                        <div className={`text-[10px] font-black uppercase tracking-widest mt-1 ${
                          item.condition === 'Perfecto Estado' ? 'text-emerald-500' : 'text-rose-500'
                        }`}>
                          {item.condition}
                        </div>
                        <div className="text-[10px] text-slate-500 mt-2 font-bold uppercase tracking-tight">CANTIDAD: {item.quantity}</div>
                        {item.observations && <div className="text-xs italic text-slate-400 mt-1 line-clamp-1">"{item.observations}"</div>}
                        {item.aiAnalysis && (
                          <div className="mt-2 text-[10px] text-blue-600 bg-blue-50 p-2 rounded-lg border border-blue-100 line-clamp-2">
                            {item.aiAnalysis}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-6 border-t bg-white flex justify-end gap-3">
              <button
                onClick={() => setSelectedAudit(null)}
                className="px-8 py-3 bg-slate-900 text-white font-bold rounded-xl hover:bg-slate-800 transition-all shadow-lg"
              >
                Cerrar Detalle
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryView;

