              <div className="bg-slate-900 text-white p-6 rounded-2xl shadow-xl relative overflow-hidden">
                <div className="relative z-10">
                  <h3 className="flex items-center gap-2 font-bold mb-3 text-blue-400">
                    <Sparkles size={18} />
