                  Quiebres de Stock Detectados ({selectedAudit.oosItems?.length || 0})
                </h3>
                <div className="grid gap-2">
                  {selectedAudit.oosItems && selectedAudit.oosItems.length > 0 ? (
                    selectedAudit.oosItems.map((sku) => (
