import React, { useState } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, MessageSquare } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS } from '../types';
import { analyzeMaterialImage } from '../services/geminiService';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave }) => {
  const [storeName, setStoreName] = useState('');
  const [address, setAddress] = useState('');
  const [auditorName, setAuditorName] = useState('');
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [items, setItems] = useState<MaterialItem[]>([]);
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [analyzingItemIds, setAnalyzingItemIds] = useState<Set<string>>(new Set());

  const handleAddItem = () => {
    const newItem: MaterialItem = {
      id: crypto.randomUUID(),
      type: MaterialType.POSTER,
      condition: Condition.PERFECT,
      observations: '',
      quantity: 1,
    };
    setItems([...items, newItem]);
  };

  const handleAddOOSItem = () => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: SKUCategory.CIGARRILLOS,
      skuName: SKU_LISTS[SKUCategory.CIGARRILLOS][0],
      meetsMinStock: true,
    };
    setOosItems([...oosItems, newOos]);
  };

  const handleRemoveItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleRemoveOOSItem = (id: string) => {
    setOosItems(oosItems.filter(item => item.id !== id));
  };

  const handleItemChange = (id: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        // Reset SKU when category changes
        if (field === 'category') {
          updated.skuName = SKU_LISTS[value as SKUCategory][0];
        }
        // Reset reason when meets stock
        if (field === 'meetsMinStock' && value === true) {
          updated.reason = undefined;
          updated.otherComment = undefined;
        }
        return updated;
      }
      return item;
    }));
  };

  const handlePhotoUpload = async (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      handleItemChange(id, 'photoBase64', base64String);

      const item = items.find(i => i.id === id);
      if (item) {
        setAnalyzingItemIds(prev => new Set(prev).add(id));
        const analysis = await analyzeMaterialImage(base64String, item.type);
        handleItemChange(id, 'aiAnalysis', analysis);
        setAnalyzingItemIds(prev => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName || !auditorName) {
      alert('Por favor complete los campos obligatorios.');
      return;
    }

    // Validation for OOS
    const invalidOos = oosItems.some(o => !o.meetsMinStock && !o.reason);
    if (invalidOos) {
      alert('Debe indicar un motivo para los SKUs que no cumplen el stock mínimo.');
      return;
    }

    setIsSubmitting(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeName,
          address,
          auditorName,
          storeStatus,
          items,
          oosItems,
          location: {
            lat: pos.coords.latitude,
            lng: pos.coords.longitude
          }
        };
        onSave(audit);
        setIsSubmitting(false);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeName,
          address,
          auditorName,
          storeStatus,
          items,
          oosItems,
        };
        onSave(audit);
        setIsSubmitting(false);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-slate-900">Nueva Auditoría</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Store Status Selection */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-semibold flex items-center gap-2 mb-4">
            <Store size={20} className="text-blue-500" />
            Estado de la Tienda
          </h2>
          <div className="flex gap-4">
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.OPEN)}
              className={`flex-1 flex items-center justify-center gap-3 p-4 rounded-xl border-2 transition-all ${
                storeStatus === StoreStatus.OPEN 
                ? 'bg-green-50 border-green-500 text-green-700 shadow-sm' 
                : 'bg-white border-slate-100 text-slate-400 grayscale'
              }`}
            >
              <CheckCircle2 size={24} />
              <span className="font-bold uppercase tracking-tight">Tienda Abierta</span>
            </button>
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.CLOSED)}
              className={`flex-1 flex items-center justify-center gap-3 p-4 rounded-xl border-2 transition-all ${
                storeStatus === StoreStatus.CLOSED 
                ? 'bg-red-50 border-red-500 text-red-700 shadow-sm' 
                : 'bg-white border-slate-100 text-slate-400 grayscale'
              }`}
            >
              <XCircle size={24} />
              <span className="font-bold uppercase tracking-tight">Tienda Cerrada</span>
            </button>
          </div>
        </section>

        {/* Store Info */}
        <section className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 space-y-4">
          <h2 className="text-lg font-semibold flex items-center gap-2">
            <MapPin size={20} className="text-blue-500" />
            Información General
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-slate-700 mb-1">Nombre del Auditor *</label>
              <input
                type="text"
                required
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                value={auditorName}
                onChange={e => setAuditorName(e.target.value)}
                placeholder="Nombre completo"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Punto de Venta *</label>
              <input
                type="text"
                required
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                value={storeName}
                onChange={e => setStoreName(e.target.value)}
                placeholder="Nombre de la tienda"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Dirección / Canal</label>
              <input
                type="text"
                className="w-full px-4 py-2 rounded-lg border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none"
                value={address}
                onChange={e => setAddress(e.target.value)}
                placeholder="Calle o referencia"
              />
            </div>
          </div>
        </section>

        {/* DETALLE DE QUIEBRE DETALLADO */}
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-semibold flex items-center gap-2">
              <Ban size={20} className="text-rose-600" />
              Recolección de Quiebres
            </h2>
            <button
              type="button"
              onClick={handleAddOOSItem}
              className="flex items-center gap-2 px-4 py-2 bg-rose-50 text-rose-700 rounded-lg hover:bg-rose-100 transition-colors font-bold text-sm shadow-sm"
            >
              <Plus size={18} />
              Registrar Quiebre de Stock
            </button>
          </div>

          <div className="space-y-4">
            {oosItems.map((oos, idx) => (
              <div key={oos.id} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4 relative animate-in fade-in slide-in-from-top-2">
                <button
                  type="button"
                  onClick={() => handleRemoveOOSItem(oos.id)}
                  className="absolute top-4 right-4 p-2 text-slate-300 hover:text-rose-500 transition-colors"
                >
                  <Trash2 size={20} />
                </button>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Category & SKU Selection */}
                  <div className="space-y-4">
                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Categoría</label>
                      <div className="flex gap-2">
                        {Object.values(SKUCategory).map((cat) => (
                          <button
                            key={cat}
                            type="button"
                            onClick={() => handleOOSChange(oos.id, 'category', cat)}
                            className={`flex-1 px-3 py-2 rounded-lg text-xs font-bold transition-all border ${
                              oos.category === cat 
                                ? 'bg-slate-900 text-white border-slate-900 shadow-md' 
                                : 'bg-slate-50 text-slate-500 border-slate-100 hover:bg-slate-100'
                            }`}
                          >
                            {cat}
                          </button>
                        ))}
                      </div>
                    </div>

                    <div>
                      <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Seleccionar SKU</label>
                      <select
                        className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-rose-500 outline-none bg-slate-50/50 appearance-none font-medium"
                        value={oos.skuName}
                        onChange={e => handleOOSChange(oos.id, 'skuName', e.target.value)}
                      >
                        {SKU_LISTS[oos.category].map(sku => <option key={sku} value={sku}>{sku}</option>)}
                      </select>
                    </div>
                  </div>

                  {/* Stock Flow Selection */}
                  <div className="space-y-4 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
                    <div>
                      <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-3">¿CUMPLE STOCK MÍNIMO?</label>
                      <div className="flex gap-2">
                        <button
                          type="button"
                          onClick={() => handleOOSChange(oos.id, 'meetsMinStock', true)}
                          className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all border ${
