import React, { useState } from 'react';
import { Upload, Plus, Trash2, User as UserIcon, Store, FileJson, Save, CheckCircle2 } from 'lucide-react';
import { User, Route, AssignedStore } from '../types';

interface RouteManagerProps {
  onSaveRoute: (route: Route) => void;
  users: User[];
  existingRoutes: Route[];
}

const RouteManager: React.FC<RouteManagerProps> = ({ onSaveRoute, users, existingRoutes }) => {
  const [selectedUserId, setSelectedUserId] = useState(users[0]?.id || '');
  const [rawJson, setRawJson] = useState('');
  const [currentRouteStores, setCurrentRouteStores] = useState<AssignedStore[]>([]);
  const [success, setSuccess] = useState(false);

  const handleParseJson = () => {
    try {
      const parsed = JSON.parse(rawJson);
      if (Array.isArray(parsed)) {
        const stores = parsed.map(s => ({
          id: s.id || crypto.randomUUID(),
          name: s.name || 'Sin nombre',
          address: s.address || 'Sin dirección',
          completed: false
        }));
        setCurrentRouteStores(stores);
      }
    } catch (e) {
      alert('Formato JSON inválido. Use [{ "name": "...", "address": "..." }]');
    }
  };

  const handleSave = () => {
    if (!selectedUserId || currentRouteStores.length === 0) return;
    onSaveRoute({
      userId: selectedUserId,
      stores: currentRouteStores
    });
    setSuccess(true);
    setTimeout(() => setSuccess(false), 3000);
    setRawJson('');
    setCurrentRouteStores([]);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header>
        <h1 className="text-2xl font-bold text-slate-900">Gestión de Rutas</h1>
        <p className="text-slate-500">Asigna listados de tiendas a los auditores.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-6">
          <h3 className="text-lg font-bold flex items-center gap-2">
            <Plus size={20} className="text-blue-500" />
            Nueva Asignación
          </h3>

          <div className="space-y-4">
            <div>
              <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Seleccionar Auditor</label>
              <select
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50"
                value={selectedUserId}
                onChange={e => setSelectedUserId(e.target.value)}
              >
                {users.filter(u => u.role === 'auditor').map(u => (
                  <option key={u.id} value={u.id}>{u.name}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Pegar JSON de Tiendas</label>
              <textarea
                className="w-full h-32 px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50 font-mono text-xs"
                placeholder='[{"name": "Tienda A", "address": "Calle 1"}, {"name": "Tienda B", "address": "Calle 2"}]'
                value={rawJson}
                onChange={e => setRawJson(e.target.value)}
              />
              <button
                onClick={handleParseJson}
                className="mt-2 w-full flex items-center justify-center gap-2 py-2 px-4 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors font-bold text-xs"
              >
                <FileJson size={16} />
                Pre-visualizar Tiendas
              </button>
            </div>

            {currentRouteStores.length > 0 && (
              <div className="space-y-3">
                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest">Vista Previa ({currentRouteStores.length})</label>
                <div className="max-h-40 overflow-y-auto space-y-2 border rounded-xl p-2 bg-slate-50">
                  {currentRouteStores.map((s, idx) => (
                    <div key={idx} className="bg-white p-2 rounded-lg border border-slate-100 text-xs">
                      <div className="font-bold">{s.name}</div>
                      <div className="text-slate-500">{s.address}</div>
                    </div>
                  ))}
                </div>
                <button
                  onClick={handleSave}
                  className="w-full flex items-center justify-center gap-2 py-4 px-4 bg-blue-600 text-white rounded-2xl hover:bg-blue-700 transition-all font-bold shadow-lg shadow-blue-100"
                >
                  <Save size={20} />
                  Confirmar y Asignar Ruta
                </button>
              </div>
            )}

            {success && (
              <div className="p-4 bg-emerald-50 text-emerald-700 rounded-xl border border-emerald-100 flex items-center gap-3 font-bold animate-in zoom-in-95">
                <CheckCircle2 size={24} />
                Ruta asignada correctamente
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold flex items-center gap-2 mb-6">
            <Store size={20} className="text-blue-500" />
            Rutas Activas
          </h3>

          <div className="space-y-4">
            {existingRoutes.length === 0 ? (
              <p className="text-slate-400 text-center py-10 italic">No hay rutas asignadas todavía.</p>
            ) : (
              existingRoutes.map((route, idx) => {
                const user = users.find(u => u.id === route.userId);
                const progress = Math.round((route.stores.filter(s => s.completed).length / route.stores.length) * 100);
                return (
                  <div key={idx} className="p-4 rounded-2xl border border-slate-100 hover:border-blue-200 transition-all group">
                    <div className="flex justify-between items-start mb-3">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center font-bold text-sm">
                          {user?.name.charAt(0)}
                        </div>
                        <div>
                          <div className="font-bold text-slate-900">{user?.name}</div>
                          <div className="text-[10px] text-slate-500 font-bold uppercase">{route.stores.length} TIENDAS ASIGNADAS</div>
                        </div>
                      </div>
                      <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${progress === 100 ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'}`}>
                        {progress}% COMPLETADO
                      </div>
                    </div>
                    <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
                      <div className="bg-blue-600 h-full transition-all duration-1000" style={{ width: `${progress}%` }}></div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default RouteManager;

