import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS, User as UserType, AssignedStore } from '../types';
import { analyzeMaterialImage } from '../services/geminiService';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [items, setItems] = useState<MaterialItem[]>([]);
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [analyzingItemIds, setAnalyzingItemIds] = useState<Set<string>>(new Set());

  const handleAddItem = () => {
    const newItem: MaterialItem = {
      id: crypto.randomUUID(),
      type: MaterialType.POSTER,
      condition: Condition.PERFECT,
      observations: '',
      quantity: 1,
    };
    setItems([...items, newItem]);
  };

  const handleAddOOSItem = () => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: SKUCategory.CIGARRILLOS,
      skuName: SKU_LISTS[SKUCategory.CIGARRILLOS][0],
      meetsMinStock: true,
    };
    setOosItems([...oosItems, newOos]);
  };

  const handleRemoveItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleRemoveOOSItem = (id: string) => {
    setOosItems(oosItems.filter(item => item.id !== id));
  };

  const handleItemChange = (id: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        if (field === 'category') updated.skuName = SKU_LISTS[value as SKUCategory][0];
        if (field === 'meetsMinStock' && value === true) {
          updated.reason = undefined;
          updated.otherComment = undefined;
        }
        return updated;
      }
      return item;
    }));
  };

  const handlePhotoUpload = async (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      handleItemChange(id, 'photoBase64', base64String);
      const item = items.find(i => i.id === id);
      if (item) {
        setAnalyzingItemIds(prev => new Set(prev).add(id));
        const analysis = await analyzeMaterialImage(base64String, item.type);
        handleItemChange(id, 'aiAnalysis', analysis);
        setAnalyzingItemIds(prev => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName) {
      alert('Por favor complete los campos obligatorios.');
      return;
    }

    const invalidOos = oosItems.some(o => !o.meetsMinStock && !o.reason);
    if (invalidOos) {
      alert('Debe indicar un motivo para los SKUs que no cumplen el stock mínimo.');
      return;
    }

    setIsSubmitting(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items,
          oosItems,
          location: { lat: pos.coords.latitude, lng: pos.coords.longitude }
        };
        onSave(audit);
        setIsSubmitting(false);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items,
          oosItems,
        };
        onSave(audit);
        setIsSubmitting(false);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-28">
      <div className="flex items-center gap-4 mb-6">
        <button onClick={onCancel} className="p-2 hover:bg-white rounded-full text-slate-400 hover:text-slate-900 transition-colors">
          <ArrowLeft size={24} />
        </button>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight">Registro de Auditoría</h1>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Auditor Info (Auto) */}
        <section className="bg-slate-900 text-white p-6 rounded-3xl shadow-xl shadow-slate-200 border border-slate-800 flex items-center gap-4 relative overflow-hidden">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center relative z-10 shadow-lg shadow-blue-500/30">
            <User size={24} />
          </div>
          <div className="relative z-10">
            <div className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Auditor Asignado</div>
            <div className="text-xl font-bold tracking-tight">{user.name}</div>
          </div>
          <div className="absolute top-0 right-0 -mt-8 -mr-8 w-32 h-32 bg-blue-600/10 rounded-full blur-3xl"></div>
        </section>

        {/* Store Status Selection */}
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
          <h2 className="text-lg font-bold flex items-center gap-2 mb-4">
            <Store size={20} className="text-blue-500" />
            Condición del Punto de Venta
          </h2>
          <div className="flex gap-4">
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.OPEN)}
              className={`flex-1 flex flex-col items-center justify-center gap-2 p-6 rounded-2xl border-2 transition-all ${
                storeStatus === StoreStatus.OPEN 
                ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-lg shadow-emerald-900/10' 
                : 'bg-white border-slate-100 text-slate-300 grayscale opacity-60'
              }`}
            >
              <CheckCircle2 size={32} />
              <span className="font-black uppercase text-xs tracking-widest">Abierta</span>
            </button>
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.CLOSED)}
              className={`flex-1 flex flex-col items-center justify-center gap-2 p-6 rounded-2xl border-2 transition-all ${
                storeStatus === StoreStatus.CLOSED 
                ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-lg shadow-rose-900/10' 
                : 'bg-white border-slate-100 text-slate-300 grayscale opacity-60'
              }`}
            >
              <XCircle size={32} />
              <span className="font-black uppercase text-xs tracking-widest">Cerrada</span>
            </button>
          </div>
        </section>

        {/* Store Info */}
        <section className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
          <h2 className="text-lg font-bold flex items-center gap-2">
            <MapPin size={20} className="text-blue-500" />
            Datos de la Tienda
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Punto de Venta *</label>
              <input
                type="text"
                required
                disabled={!!prefillStore}
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50 disabled:opacity-70 disabled:cursor-not-allowed font-bold"
                value={storeName}
                onChange={e => setStoreName(e.target.value)}
                placeholder="Nombre"
              />
            </div>
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Dirección / Canal</label>
              <input
                type="text"
                disabled={!!prefillStore}
                className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50 disabled:opacity-70 disabled:cursor-not-allowed"
                value={address}
                onChange={e => setAddress(e.target.value)}
                placeholder="Ubicación"
              />
            </div>
          </div>
        </section>

        {/* OOS DETALLE */}
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-bold flex items-center gap-2">
              <Ban size={20} className="text-rose-600" />
              Gestión de Quiebres
            </h2>
            <button
              type="button"
              onClick={handleAddOOSItem}
              className="flex items-center gap-2 px-4 py-2 bg-rose-50 text-rose-700 rounded-xl hover:bg-rose-100 transition-colors font-bold text-xs shadow-sm"
            >
              <Plus size={16} />
              Añadir SKU
            </button>
          </div>

          <div className="space-y-4">
            {oosItems.map((oos, idx) => (
              <div key={oos.id} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4 relative">
                <button
                  type="button"
                  onClick={() => handleRemoveOOSItem(oos.id)}
                  className="absolute top-4 right-4 p-2 text-slate-300 hover:text-rose-500 transition-colors"
                >
                  <Trash2 size={20} />
                </button>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Categoría</label>
                      <div className="flex gap-1">
                        {Object.values(SKUCategory).map((cat) => (
                          <button
                            key={cat}
                            type="button"
                            onClick={() => handleOOSChange(oos.id, 'category', cat)}
                            className={`flex-1 py-2 rounded-lg text-[10px] font-black transition-all border ${
                              oos.category === cat ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-slate-50 text-slate-500 border-slate-100'
                            }`}
                          >
                            {cat}
                          </button>
                        ))}
                      </div>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">SKU Detectado</label>
                      <select
                        className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-rose-500 outline-none bg-slate-50/50 appearance-none font-bold text-sm"
                        value={oos.skuName}
                        onChange={e => handleOOSChange(oos.id, 'skuName', e.target.value)}
                      >
                        {SKU_LISTS[oos.category].map(sku => <option key={sku} value={sku}>{sku}</option>)}
                      </select>
                    </div>
                  </div>
                  <div className="space-y-4 bg-slate-50/50 p-4 rounded-xl border border-slate-100">
                    <div>
                      <label className="block text-[10px] font-black text-slate-700 uppercase tracking-widest mb-3">¿CUMPLE STOCK MÍNIMO?</label>
                      <div className="flex gap-2">
                        <button
                          type="button"
                          onClick={() => handleOOSChange(oos.id, 'meetsMinStock', true)}
                          className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all border ${
                            oos.meetsMinStock ? 'bg-emerald-500 text-white border-emerald-500 shadow-lg shadow-emerald-500/30' : 'bg-white text-slate-400 border-slate-100'
                          }`}
                        >
                          SÍ
                        </button>
                        <button
                          type="button"
                          onClick={() => handleOOSChange(oos.id, 'meetsMinStock', false)}
                          className={`flex-1 py-3 rounded-lg text-sm font-bold transition-all border ${
                            !oos.meetsMinStock ? 'bg-rose-500 text-white border-rose-500 shadow-lg shadow-rose-500/30' : 'bg-white text-slate-400 border-slate-100'
                          }`}
                        >
                          NO
                        </button>
                      </div>
                    </div>
                    {!oos.meetsMinStock && (
                      <div className="animate-in zoom-in-95 duration-200">
                        <label className="block text-[10px] font-black text-rose-600 uppercase tracking-widest mb-2">MOTIVO OBLIGATORIO</label>
                        <select
                          required
                          className="w-full px-4 py-3 rounded-xl border-2 border-rose-200 focus:border-rose-500 outline-none bg-white font-bold text-xs text-rose-700"
                          value={oos.reason || ''}
                          onChange={e => handleOOSChange(oos.id, 'reason', e.target.value)}
                        >
                          <option value="" disabled>Seleccione motivo...</option>
                          {OOS_REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                        </select>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {oosItems.length === 0 && (
              <div className="p-10 text-center bg-white rounded-3xl border-2 border-dashed border-slate-200 text-slate-400 text-sm">
                No hay quiebres reportados.
              </div>
            )}
          </div>
        </section>

        {/* Material POP List */}
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-bold flex items-center gap-2">
              <Package size={20} className="text-blue-500" />
              Material POP ({items.length})
            </h2>
            <button
              type="button"
              onClick={handleAddItem}
              className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-colors font-bold text-xs shadow-sm"
            >
              <Plus size={16} />
              Añadir Material
            </button>
          </div>

          {items.map((item, index) => (
            <div key={item.id} className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 relative">
              <button
                type="button"
                onClick={() => handleRemoveItem(item.id)}
                className="absolute top-4 right-4 p-2 text-slate-300 hover:text-rose-500 transition-colors"
              >
                <Trash2 size={18} />
              </button>
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                <div className="lg:col-span-3">
                  <div className="relative aspect-square rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden group">
                    {item.photoBase64 ? (
                      <>
                        <img src={item.photoBase64} alt="Preview" className="w-full h-full object-cover" />
                        <label className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer text-white flex-col gap-1">
                          <Camera size={24} />
                          <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handlePhotoUpload(item.id, e.target.files[0])} />
                        </label>
                      </>
                    ) : (
                      <label className="cursor-pointer w-full h-full flex flex-col items-center justify-center text-slate-300 hover:text-blue-500 transition-colors">
                        <Camera size={32} />
                        <span className="text-[10px] font-black uppercase mt-2 tracking-widest">Tomar Foto</span>
                        <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handlePhotoUpload(item.id, e.target.files[0])} />
                      </label>
                    )}
                  </div>
                </div>
                <div className="lg:col-span-9 space-y-4">
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Tipo de Material</label>
                      <select className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50 font-bold text-sm" value={item.type} onChange={e => handleItemChange(item.id, 'type', e.target.value)}>
                        {Object.values(MaterialType).map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Estado Físico</label>
                      <select className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50 font-bold text-sm" value={item.condition} onChange={e => handleItemChange(item.id, 'condition', e.target.value)}>
                        {Object.values(Condition).map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>
                  {(analyzingItemIds.has(item.id) || item.aiAnalysis) && (
                    <div className="p-4 rounded-xl bg-blue-50 border border-blue-100 flex gap-3">
                      {analyzingItemIds.has(item.id) ? <Loader2 className="animate-spin text-blue-500 shrink-0" size={18} /> : <Sparkles className="text-blue-500 shrink-0" size={18} />}
                      <p className="text-xs text-slate-600 italic leading-relaxed">
                        {analyzingItemIds.has(item.id) ? "Auditoría Visual Gemini en proceso..." : item.aiAnalysis}
                      </p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </section>

        {/* Final Action */}
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-6xl z-50">
          <button
            type="submit"
            disabled={isSubmitting}
            className="w-full bg-slate-900 text-white px-6 py-5 rounded-2xl font-black uppercase tracking-widest shadow-2xl hover:bg-black transition-all flex items-center justify-center gap-3 disabled:opacity-50 active:scale-95"
          >
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={24} />}
            Finalizar Reporte de Tienda
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import NewAuditForm from './components/NewAuditForm';
import HistoryView from './components/HistoryView';
import Login from './components/Login';
import RouteView from './components/RouteView';
import RouteManager from './components/RouteManager';
import { POSAudit, MaterialType, Condition, StoreStatus, User, Route, AssignedStore } from './types';

const INITIAL_USERS: User[] = [
  { id: 'u1', name: 'Administrador Central', role: 'admin' },
  { id: 'u2', name: 'Carlos Auditor', role: 'auditor' },
  { id: 'u3', name: 'Ana Trade', role: 'auditor' },
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('pos_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'route' | 'history' | 'admin'>('dashboard');

  const [audits, setAudits] = useState<POSAudit[]>(() => {
    const saved = localStorage.getItem('pos_audits');
    return saved ? JSON.parse(saved) : [];
  });

  const [routes, setRoutes] = useState<Route[]>(() => {
    const saved = localStorage.getItem('pos_routes');
    return saved ? JSON.parse(saved) : [];
  });

  const [auditingStore, setAuditingStore] = useState<AssignedStore | null>(null);

  useEffect(() => {
    localStorage.setItem('pos_user', JSON.stringify(currentUser));
  }, [currentUser]);

  useEffect(() => {
    localStorage.setItem('pos_audits', JSON.stringify(audits));
  }, [audits]);

  useEffect(() => {
    localStorage.setItem('pos_routes', JSON.stringify(routes));
  }, [routes]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setAuditingStore(null);
  };

  const handleSaveAudit = (newAudit: POSAudit) => {
    setAudits([newAudit, ...audits]);

    // Update route status if it was from a route
    if (newAudit.storeId && currentUser) {
      setRoutes(prev => prev.map(r => {
        if (r.userId === currentUser.id) {
          return {
            ...r,
            stores: r.stores.map(s => s.id === newAudit.storeId ? { ...s, completed: true } : s)
          };
        }
        return r;
      }));
    }

    setAuditingStore(null);
    setActiveTab('history');
  };

  const handleAuditFromRoute = (store: AssignedStore) => {
    setAuditingStore(store);
  };

  const handleSaveRoute = (newRoute: Route) => {
    setRoutes(prev => {
      const filtered = prev.filter(r => r.userId !== newRoute.userId);
      return [...filtered, newRoute];
    });
  };

  if (!currentUser) {
    return <Login onLogin={handleLogin} />;
  }

  // Intercept normal tab rendering if we are in the middle of an audit
  if (auditingStore) {
    return (
      <Layout activeTab="route" onTabChange={setActiveTab} user={currentUser} onLogout={handleLogout}>
        <NewAuditForm 
          onSave={handleSaveAudit} 
          user={currentUser} 
          prefillStore={auditingStore} 
          onCancel={() => setAuditingStore(null)}
        />
      </Layout>
    );
  }

  const userRoute = routes.find(r => r.userId === currentUser.id);

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard audits={audits} />;
      case 'route':
        return <RouteView route={userRoute} onAuditStore={handleAuditFromRoute} />;
      case 'history':
        return <HistoryView audits={audits} />;
      case 'admin':
        return currentUser.role === 'admin' ? (
          <RouteManager 
            users={INITIAL_USERS} 
            existingRoutes={routes} 
            onSaveRoute={handleSaveRoute} 
          />
        ) : <Dashboard audits={audits} />;
      default:
        return <Dashboard audits={audits} />;
    }
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab} user={currentUser} onLogout={handleLogout}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { ClipboardCheck, User as UserIcon, ShieldCheck, ArrowRight, ChevronRight } from 'lucide-react';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
  availableUsers: User[];
}

const Login: React.FC<LoginProps> = ({ onLogin, availableUsers }) => {
  const [isCreating, setIsCreating] = useState(false);
  const [name, setName] = useState('');
  const [role, setRole] = useState<'auditor' | 'admin'>('auditor');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    onLogin({
      id: crypto.randomUUID(),
      name: name.trim(),
      role
    });
  };

  return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in duration-500">
        <div className="p-8 bg-blue-600 text-white text-center relative overflow-hidden">
          <div className="relative z-10 flex flex-col items-center">
            <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center mb-4 backdrop-blur-md border border-white/30">
              <ClipboardCheck size={40} />
            </div>
            <h1 className="text-3xl font-black tracking-tighter">AuditPOS</h1>
            <p className="text-blue-100 mt-2 text-sm font-medium">Gestión Inteligente de Rutas</p>
          </div>
          <div className="absolute top-0 right-0 -mt-8 -mr-8 w-32 h-32 bg-white/10 rounded-full blur-2xl"></div>
          <div className="absolute bottom-0 left-0 -mb-8 -ml-8 w-24 h-24 bg-blue-400/20 rounded-full blur-xl"></div>
        </div>

        <div className="p-8">
          {!isCreating ? (
            <div className="space-y-6">
              <div>
