import React, { useState, useEffect } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS, User as UserType, AssignedStore, POS_CHECKLIST_ITEMS, MaterialChecklistRecord, NoMaterialReason } from '../types';
import { analyzeMaterialImage } from '../services/geminiService';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [items, setItems] = useState<MaterialItem[]>([]);
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [checklist, setChecklist] = useState<MaterialChecklistRecord[]>(
    POS_CHECKLIST_ITEMS.map(item => ({ itemName: item, hasMaterial: false }))
  );

  const [activeChecklistItem, setActiveChecklistItem] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [analyzingItemIds, setAnalyzingItemIds] = useState<Set<string>>(new Set());

  const handleAddItem = () => {
    const newItem: MaterialItem = {
      id: crypto.randomUUID(),
      type: MaterialType.POSTER,
      condition: Condition.PERFECT,
      observations: '',
      quantity: 1,
    };
    setItems([...items, newItem]);
  };

  const handleAddOOSItem = () => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: SKUCategory.CIGARRILLOS,
      skuName: SKU_LISTS[SKUCategory.CIGARRILLOS][0],
      meetsMinStock: true,
    };
    setOosItems([...oosItems, newOos]);
  };

  const handleRemoveItem = (id: string) => {
    setItems(items.filter(item => item.id !== id));
  };

  const handleRemoveOOSItem = (id: string) => {
    setOosItems(oosItems.filter(item => item.id !== id));
  };

  const handleItemChange = (id: string, field: keyof MaterialItem, value: any) => {
    setItems(items.map(item => item.id === id ? { ...item, [field]: value } : item));
  };

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        if (field === 'category') updated.skuName = SKU_LISTS[value as SKUCategory][0];
        if (field === 'meetsMinStock' && value === true) {
          updated.reason = undefined;
          updated.otherComment = undefined;
        }
        return updated;
      }
      return item;
    }));
  };

  const handleChecklistChange = (itemName: string, field: keyof MaterialChecklistRecord, value: any) => {
    setChecklist(checklist.map(item => 
      item.itemName === itemName ? { ...item, [field]: value } : item
    ));
  };

  const handleChecklistPhoto = (itemName: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      handleChecklistChange(itemName, 'photoBase64', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handlePhotoUpload = async (id: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      handleItemChange(id, 'photoBase64', base64String);
      const item = items.find(i => i.id === id);
      if (item) {
        setAnalyzingItemIds(prev => new Set(prev).add(id));
        const analysis = await analyzeMaterialImage(base64String, item.type);
        handleItemChange(id, 'aiAnalysis', analysis);
        setAnalyzingItemIds(prev => {
          const next = new Set(prev);
          next.delete(id);
          return next;
        });
      }
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName) {
      alert('Por favor complete los campos obligatorios.');
      return;
    }

    const invalidOos = oosItems.some(o => !o.meetsMinStock && !o.reason);
    if (invalidOos) {
      alert('Debe indicar un motivo para los SKUs que no cumplen el stock mínimo.');
      return;
    }

    // Validation for Checklist
    const incompleteChecklist = checklist.some(item => 
      (item.hasMaterial && !item.photoBase64) || (!item.hasMaterial && !item.reason)
    );
    // Note: In some workflows it might be optional, but based on request let's assume they must fill it.

    setIsSubmitting(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items,
          oosItems,
          checklist,
          location: { lat: pos.coords.latitude, lng: pos.coords.longitude }
        };
        onSave(audit);
        setIsSubmitting(false);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items,
          oosItems,
          checklist
        };
        onSave(audit);
        setIsSubmitting(false);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-28">
      {/* Header aligned with mockup */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <button onClick={onCancel} className="p-1">
            <ArrowLeft size={24} />
          </button>
          <h1 className="text-xl font-bold uppercase tracking-tight">AUDITORÍA FINAL</h1>
        </div>
        <button className="p-1">
          <Search size={22} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Info del Auditor */}
        <section className="bg-slate-900 text-white p-6 rounded-3xl shadow-xl shadow-slate-200 border border-slate-800 flex items-center gap-4 relative overflow-hidden">
          <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center relative z-10 shadow-lg shadow-blue-500/30">
            <User size={24} />
          </div>
          <div className="relative z-10">
            <div className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Auditor</div>
            <div className="text-xl font-bold tracking-tight">{user.name}</div>
          </div>
        </section>

        {/* Auditoría Final Checklist UI (Mockup inspired) */}
        <section className="space-y-3">
          {checklist.map((item) => {
            const isFilled = item.hasMaterial ? !!item.photoBase64 : !!item.reason;
            return (
              <div key={item.itemName} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="p-4 bg-[#e0e0e0] flex items-center justify-between">
                  <span className="font-bold text-slate-700 uppercase text-sm">{item.itemName}</span>
                  {isFilled && <Check size={20} className="text-emerald-600" />}
                </div>
                <div className="p-4">
                  <button
                    type="button"
                    onClick={() => setActiveChecklistItem(activeChecklistItem === item.itemName ? null : item.itemName)}
                    className="bg-[#1e3a5f] text-white px-6 py-1.5 rounded text-xs font-bold uppercase tracking-wide hover:bg-slate-800 transition-colors"
                  >
                    INGRESAR
                  </button>

                  {/* Detalle desplegable del item */}
                  {activeChecklistItem === item.itemName && (
                    <div className="mt-4 pt-4 border-t border-slate-200 animate-in slide-in-from-top-2 duration-200 space-y-4">
                      <div className="flex gap-4">
                        <button
                          type="button"
                          onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', true)}
                          className={`flex-1 py-3 rounded-lg font-bold text-sm border-2 transition-all ${
                            item.hasMaterial ? 'bg-emerald-50 border-emerald-500 text-emerald-700' : 'bg-white border-slate-100 text-slate-400'
                          }`}
                        >
                          TIENE
                        </button>
                        <button
                          type="button"
                          onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', false)}
                          className={`flex-1 py-3 rounded-lg font-bold text-sm border-2 transition-all ${
                            !item.hasMaterial ? 'bg-rose-50 border-rose-500 text-rose-700' : 'bg-white border-slate-100 text-slate-400'
                          }`}
                        >
                          NO TIENE
                        </button>
                      </div>

                      {item.hasMaterial ? (
                        <div className="space-y-2">
                          <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest">Foto del material instalado</label>
                          <div className="relative aspect-video rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden flex items-center justify-center">
                            {item.photoBase64 ? (
                              <>
                                <img src={item.photoBase64} alt="Material" className="w-full h-full object-cover" />
                                <label className="absolute inset-0 bg-black/40 opacity-0 hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer text-white flex-col gap-1">
                                  <Camera size={24} />
                                  <input type="file" accept="image/*" className="hidden" onChange={e => e.target.files?.[0] && handleChecklistPhoto(item.itemName, e.target.files[0])} />
