import React, { useState } from 'react';
import { Plus, Search, Trash2, FileJson, Database, Edit2, Check, X } from 'lucide-react';
import { StoreMaster } from '../types';

interface StoreCatalogProps {
  stores: StoreMaster[];
  onUpdateStores: (stores: StoreMaster[]) => void;
}

const StoreCatalog: React.FC<StoreCatalogProps> = ({ stores, onUpdateStores }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [rawJson, setRawJson] = useState('');
  const [isImporting, setIsImporting] = useState(false);

  const filteredStores = stores.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    s.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleImportJson = () => {
    try {
      const parsed = JSON.parse(rawJson);
      if (Array.isArray(parsed)) {
        const newStores = parsed.map(s => ({
          id: s.id || crypto.randomUUID(),
          name: s.name || 'PDV Sin Nombre',
          address: s.address || 'Sin Dirección',
          channel: s.channel || 'Tradicional',
          city: s.city || 'N/A'
        }));
        onUpdateStores([...stores, ...newStores]);
        setRawJson('');
        setIsImporting(false);
      }
    } catch (e) {
      alert('Error: JSON inválido.');
    }
  };

  const removeStore = (id: string) => {
    if (confirm('¿Eliminar esta tienda del catálogo maestro?')) {
      onUpdateStores(stores.filter(s => s.id !== id));
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Base de Datos de PDVs</h1>
          <p className="text-slate-500">Gestión centralizada de puntos de venta disponibles.</p>
        </div>
        <button 
          onClick={() => setIsImporting(!isImporting)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-200"
        >
          <FileJson size={18} />
          {isImporting ? 'Cancelar' : 'Importar Masivo'}
        </button>
      </header>

      {isImporting && (
        <div className="bg-white p-6 rounded-3xl border-2 border-dashed border-blue-200 animate-in zoom-in-95">
          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Pegar JSON de Tiendas</label>
          <textarea
            className="w-full h-32 px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 outline-none bg-slate-50/50 font-mono text-xs"
            placeholder='[{"name": "Oxxo 1", "address": "Av. Principal 123"}, {"name": "Bodega 2", "address": "Calle 4"}]'
            value={rawJson}
            onChange={e => setRawJson(e.target.value)}
          />
          <button
            onClick={handleImportJson}
            className="mt-3 w-full bg-slate-900 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2"
          >
            <Check size={18} /> Procesar e Importar al Catálogo
          </button>
        </div>
      )}

      <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100">
        <div className="relative mb-6">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input
            type="text"
            className="w-full pl-12 pr-4 py-4 rounded-2xl bg-slate-50 border-none focus:ring-2 focus:ring-blue-500 font-medium"
            placeholder="Buscar tienda por nombre o dirección..."
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="border-b text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="pb-4 px-4">Punto de Venta</th>
                <th className="pb-4 px-4">Dirección</th>
                <th className="pb-4 px-4">Canal</th>
                <th className="pb-4 px-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStores.map(store => (
                <tr key={store.id} className="group hover:bg-slate-50 transition-colors">
                  <td className="py-4 px-4 font-bold text-slate-900">{store.name}</td>
                  <td className="py-4 px-4 text-sm text-slate-500">{store.address}</td>
                  <td className="py-4 px-4 text-xs">
                    <span className="bg-blue-50 text-blue-600 px-2 py-1 rounded-md font-bold uppercase">{store.channel || 'General'}</span>
                  </td>
                  <td className="py-4 px-4 text-right">
                    <button 
                      onClick={() => removeStore(store.id)}
                      className="p-2 text-slate-300 hover:text-rose-600 transition-colors"
                    >
                      <Trash2 size={18} />
                    </button>
                  </td>
                </tr>
              ))}
              {filteredStores.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-400 italic">No hay tiendas en el catálogo.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default StoreCatalog;

import React, { useState } from 'react';
import { Plus, Trash2, User as UserIcon, Store, Save, CheckCircle2, Search, ArrowRight, Database } from 'lucide-react';
import { User, Route, AssignedStore, StoreMaster } from '../types';

interface RouteManagerProps {
  onSaveRoute: (route: Route) => void;
  users: User[];
  existingRoutes: Route[];
  masterStores: StoreMaster[];
}

const RouteManager: React.FC<RouteManagerProps> = ({ onSaveRoute, users, existingRoutes, masterStores }) => {
  const [selectedUserId, setSelectedUserId] = useState(users.find(u => u.role === 'auditor')?.id || '');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStores, setSelectedStores] = useState<StoreMaster[]>([]);
  const [success, setSuccess] = useState(false);

  const filteredMaster = masterStores.filter(s => 
    !selectedStores.find(ss => ss.id === s.id) &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.address.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleAddStoreToRoute = (store: StoreMaster) => {
    setSelectedStores([...selectedStores, store]);
  };

  const handleRemoveFromRoute = (id: string) => {
    setSelectedStores(selectedStores.filter(s => s.id !== id));
  };

  const handleSave = () => {
    if (!selectedUserId || selectedStores.length === 0) {
      alert('Seleccione un auditor y al menos una tienda.');
      return;
    }

    const newRoute: Route = {
      id: crypto.randomUUID(),
      userId: selectedUserId,
      date: new Date().toISOString().split('T')[0],
      stores: selectedStores.map(s => ({ ...s, completed: false }))
    };

    onSaveRoute(newRoute);
    setSuccess(true);
    setSelectedStores([]);
    setTimeout(() => setSuccess(false), 3000);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <header>
        <h1 className="text-2xl font-black text-slate-900 tracking-tight uppercase">Programación de Rutas</h1>
        <p className="text-slate-500">Relaciona tiendas del catálogo con tus auditores.</p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Selector de Tiendas de la BD */}
        <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 flex flex-col h-[600px]">
          <h3 className="text-lg font-bold flex items-center gap-2 mb-4">
            <Database size={20} className="text-blue-500" />
            Base de Datos Maestra
          </h3>

          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input
              type="text"
              className="w-full pl-10 pr-4 py-3 rounded-xl bg-slate-50 border-none outline-none focus:ring-2 focus:ring-blue-500 text-sm"
              placeholder="Buscar PDVs disponibles..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex-1 overflow-y-auto space-y-2 pr-2">
            {filteredMaster.length === 0 ? (
              <p className="text-center py-10 text-slate-400 text-xs italic">No hay más tiendas disponibles.</p>
            ) : (
              filteredMaster.map(s => (
                <div key={s.id} className="p-3 bg-slate-50 rounded-xl border border-slate-100 flex justify-between items-center group">
                  <div className="overflow-hidden">
                    <div className="font-bold text-sm text-slate-900 truncate">{s.name}</div>
                    <div className="text-[10px] text-slate-500 truncate">{s.address}</div>
                  </div>
                  <button 
                    onClick={() => handleAddStoreToRoute(s)}
                    className="p-2 bg-blue-100 text-blue-600 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Plus size={16} />
                  </button>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Armado de la Ruta */}
        <div className="bg-slate-900 text-white p-6 rounded-3xl shadow-xl flex flex-col h-[600px] relative overflow-hidden">
          <div className="relative z-10 flex flex-col h-full">
            <h3 className="text-lg font-bold flex items-center gap-2 mb-6">
              <MapIcon size={20} className="text-blue-400" />
              Configurar Nueva Ruta
            </h3>

            <div className="space-y-4 mb-6">
              <div>
                <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Asignar a:</label>
                <select
                  className="w-full px-4 py-3 rounded-xl bg-slate-800 border-none text-white focus:ring-2 focus:ring-blue-500"
                  value={selectedUserId}
                  onChange={e => setSelectedUserId(e.target.value)}
                >
                  {users.filter(u => u.role === 'auditor').map(u => (
                    <option key={u.id} value={u.id}>{u.name}</option>
                  ))}
                </select>
              </div>

              <div className="flex-1 overflow-y-auto min-h-0 space-y-2">
                <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Tiendas Seleccionadas ({selectedStores.length})</label>
                {selectedStores.map((s, idx) => (
                  <div key={s.id} className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/10 group">
                    <div className="overflow-hidden">
                      <div className="text-xs font-bold truncate">{s.name}</div>
                      <div className="text-[9px] text-slate-400 truncate">{s.address}</div>
                    </div>
                    <button 
                      onClick={() => handleRemoveFromRoute(s.id)}
                      className="p-1 text-slate-500 hover:text-rose-400 transition-colors"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                ))}
                {selectedStores.length === 0 && (
                  <div className="flex flex-col items-center justify-center py-10 text-slate-600 border-2 border-dashed border-white/5 rounded-2xl">
                    <Store size={32} className="mb-2 opacity-20" />
                    <p className="text-[10px] uppercase font-bold tracking-widest">Agregue PDVs de la BD</p>
                  </div>
                )}
              </div>
            </div>

            <div className="mt-auto pt-4 border-t border-white/10">
              <button
                disabled={selectedStores.length === 0}
                onClick={handleSave}
                className="w-full flex items-center justify-center gap-2 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-900/40 hover:bg-blue-500 transition-all disabled:opacity-30 active:scale-95"
              >
                <Save size={20} />
                Guardar Ruta en BD
              </button>
              {success && (
                <div className="mt-3 p-3 bg-emerald-500/20 text-emerald-400 text-[10px] font-black rounded-lg text-center border border-emerald-500/30 uppercase tracking-widest animate-in zoom-in-95">
                  ✓ Ruta Guardada Exitosamente
                </div>
              )}
            </div>
          </div>

          <div className="absolute -bottom-20 -right-20 w-64 h-64 bg-blue-600/10 rounded-full blur-3xl pointer-events-none"></div>
        </div>
      </div>
    </div>
  );
};

export default RouteManager;

