import React, { useState, useEffect } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS, User as UserType, AssignedStore, POS_CHECKLIST_ITEMS, MaterialChecklistRecord, NoMaterialReason } from '../types';
import { analyzeMaterialImage } from '../services/geminiService';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [items, setItems] = useState<MaterialItem[]>([]);
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [checklist, setChecklist] = useState<MaterialChecklistRecord[]>(
    POS_CHECKLIST_ITEMS.map(item => ({ itemName: item, hasMaterial: false }))
  );

  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        if (field === 'category') updated.skuName = SKU_LISTS[value as SKUCategory][0];
        if (field === 'meetsMinStock' && value === true) {
          updated.reason = undefined;
          updated.otherComment = undefined;
        }
        return updated;
      }
      return item;
    }));
  };

  const handleChecklistChange = (itemName: string, field: keyof MaterialChecklistRecord, value: any) => {
    setChecklist(checklist.map(item => 
      item.itemName === itemName ? { ...item, [field]: value } : item
    ));
  };

  const handleChecklistPhoto = (itemName: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      handleChecklistChange(itemName, 'photoBase64', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleAddOOSItem = () => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: SKUCategory.CIGARRILLOS,
      skuName: SKU_LISTS[SKUCategory.CIGARRILLOS][0],
      meetsMinStock: true,
    };
    setOosItems([...oosItems, newOos]);
  };

  const handleRemoveOOSItem = (id: string) => {
    setOosItems(oosItems.filter(item => item.id !== id));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName) {
      alert('Por favor complete los campos obligatorios.');
      return;
    }

    const incompleteChecklist = checklist.some(item => 
      (item.hasMaterial && !item.photoBase64) || (!item.hasMaterial && !item.reason)
    );

    if (incompleteChecklist && storeStatus === StoreStatus.OPEN) {
        if (!confirm('Hay materiales sin foto o motivo. ¿Deseas finalizar de todas formas?')) return;
    }

    setIsSubmitting(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items: [],
          oosItems,
          checklist,
          location: { lat: pos.coords.latitude, lng: pos.coords.longitude }
        };
        onSave(audit);
        setIsSubmitting(false);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items: [],
          oosItems,
          checklist
        };
        onSave(audit);
        setIsSubmitting(false);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      {/* Header Fijo Estilo App Nativa */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1 hover:bg-white/10 rounded-full">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-lg font-black uppercase tracking-tight leading-none">Nueva Auditoría</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1">{storeName || 'Punto de Venta'}</p>
          </div>
        </div>
        <div className="flex items-center gap-2 bg-white/10 px-3 py-1.5 rounded-full border border-white/20">
          <div className="w-2 h-2 bg-emerald-400 rounded-full animate-pulse"></div>
          <span className="text-[10px] font-black tracking-widest uppercase">En Vivo</span>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* Info del Auditor Compacta */}
        <div className="flex items-center justify-between bg-white p-4 rounded-2xl border border-slate-100 shadow-sm">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center font-bold">
                    {user.name.charAt(0)}
                </div>
                <div>
                    <div className="text-[10px] font-black text-slate-400 uppercase">Auditor</div>
                    <div className="text-sm font-bold text-slate-900">{user.name}</div>
                </div>
            </div>
            <div className="text-right">
                <div className="text-[10px] font-black text-slate-400 uppercase">Fecha</div>
                <div className="text-sm font-bold text-slate-900">{new Date().toLocaleDateString()}</div>
            </div>
        </div>

        {/* Sección 1: Estado de la Tienda */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Store size={18} className="text-blue-600" />
             <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Estado del Local</h2>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.OPEN)}
              className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${
                storeStatus === StoreStatus.OPEN 
                ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-md shadow-emerald-100 scale-[1.02]' 
                : 'bg-white border-slate-100 text-slate-400'
              }`}
            >
              <CheckCircle2 size={20} /> Abierto
            </button>
            <button
              type="button"
              onClick={() => setStoreStatus(StoreStatus.CLOSED)}
              className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${
                storeStatus === StoreStatus.CLOSED 
                ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-md shadow-rose-100 scale-[1.02]' 
                : 'bg-white border-slate-100 text-slate-400'
              }`}
            >
              <XCircle size={20} /> Cerrado
            </button>
          </div>
        </section>

        {/* Sección 2: Checklist de Materiales - LA MEJORA PRINCIPAL */}
        <section className="space-y-4">
          <div className="flex items-center justify-between px-1">
             <div className="flex items-center gap-2">
                <Sparkles size={18} className="text-blue-600" />
                <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Materiales P.O.P.</h2>
             </div>
             <span className="text-[10px] font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full">
                {checklist.filter(c => (c.hasMaterial && c.photoBase64) || (!c.hasMaterial && c.reason)).length} / {checklist.length}
             </span>
          </div>

          <div className="space-y-3">
            {checklist.map((item) => {
              const isCompleted = (item.hasMaterial && item.photoBase64) || (!item.hasMaterial && item.reason);

              return (
                <div 
                  key={item.itemName} 
                  className={`bg-white rounded-2xl border-2 transition-all duration-300 overflow-hidden ${
                    isCompleted ? 'border-emerald-100 shadow-sm' : 'border-slate-100'
                  }`}
                >
                  {/* Fila Principal: Nombre + Toggle */}
                  <div className="p-4 flex items-center justify-between gap-4">
                    <span className="font-bold text-slate-800 text-sm flex-1 leading-tight">{item.itemName}</span>

                    <div className="flex bg-slate-100 p-1 rounded-xl w-36">
                       <button
                         type="button"
                         onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', true)}
                         className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${
                           item.hasMaterial ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'
                         }`}
                       >
                         Tiene
                       </button>
                       <button
                         type="button"
                         onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', false)}
                         className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${
                           !item.hasMaterial ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'
                         }`}
                       >
                         No
                       </button>
                    </div>
                  </div>

                  {/* Área de Acción (Foto o Motivo) */}
                  <div className={`px-4 pb-4 animate-in slide-in-from-top-2 duration-300 ${item.hasMaterial ? 'block' : 'block'}`}>
                    {item.hasMaterial ? (
                      <div className="space-y-2">
                        <label className="relative block aspect-video w-full rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden group active:scale-[0.98] transition-all">
                          {item.photoBase64 ? (
                            <>
                              <img src={item.photoBase64} className="w-full h-full object-cover" />
                              <div className="absolute inset-0 bg-black/30 flex items-center justify-center text-white opacity-0 group-hover:opacity-100 transition-opacity">
                                <Camera size={32} />
                              </div>
                            </>
                          ) : (
                            <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-slate-400">
                               <Camera size={32} />
                               <span className="text-[10px] font-black uppercase">Click para Tomar Foto</span>
                            </div>
                          )}
                          <input 
                            type="file" 
                            accept="image/*" 
                            capture="environment" 
                            className="hidden" 
                            onChange={e => e.target.files?.[0] && handleChecklistPhoto(item.itemName, e.target.files[0])} 
                          />
                        </label>
                      </div>
                    ) : (
                      <div className="grid grid-cols-1 gap-2">
                         <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Motivo de Falta</div>
                         <div className="flex flex-wrap gap-2">
                            {Object.values(NoMaterialReason).map((r) => (
                              <button
                                key={r}
                                type="button"
                                onClick={() => handleChecklistChange(item.itemName, 'reason', r)}
                                className={`px-3 py-2 rounded-lg text-[10px] font-bold border transition-all ${
                                  item.reason === r 
                                  ? 'bg-rose-50 border-rose-200 text-rose-700' 
                                  : 'bg-white border-slate-100 text-slate-500'
                                }`}
                              >
                                {r}
                              </button>
                            ))}
                         </div>
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* Sección 3: Quiebres de Stock */}
        <section className="space-y-4">
           <div className="flex items-center justify-between px-1">
             <div className="flex items-center gap-2">
                <Ban size={18} className="text-rose-600" />
                <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Quiebres (OOS)</h2>
             </div>
             <button
                type="button"
                onClick={handleAddOOSItem}
                className="bg-slate-900 text-white p-1.5 rounded-lg shadow-sm active:scale-95"
              >
                <Plus size={16} />
              </button>
          </div>

          <div className="space-y-3">
            {oosItems.map((oos) => (
              <div key={oos.id} className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm relative animate-in zoom-in-95">
                <button type="button" onClick={() => handleRemoveOOSItem(oos.id)} className="absolute -top-2 -right-2 bg-white text-rose-500 p-1.5 rounded-full shadow-md border border-slate-100">
                  <X size={14} />
                </button>
                <div className="space-y-4">
                   <div>
                     <label className="text-[10px] font-black text-slate-400 uppercase block mb-1">Producto</label>
                     <select
                        className="w-full px-4 py-3 rounded-xl bg-slate-50 border-none font-bold text-xs appearance-none"
                        value={oos.skuName}
                        onChange={e => handleOOSChange(oos.id, 'skuName', e.target.value)}
                      >
                        {SKU_LISTS[oos.category].map(sku => <option key={sku} value={sku}>{sku}</option>)}
                      </select>
                   </div>

                  <div className="flex items-center justify-between gap-4">
                    <span className="text-[10px] font-black text-slate-400 uppercase">¿Hay Stock?</span>
                    <div className="flex bg-slate-100 p-1 rounded-xl w-32">
                        <button
                        type="button"
                        onClick={() => handleOOSChange(oos.id, 'meetsMinStock', true)}
                        className={`flex-1 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                            oos.meetsMinStock ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'
                        }`}
                        >SÍ</button>
                        <button
                        type="button"
                        onClick={() => handleOOSChange(oos.id, 'meetsMinStock', false)}
                        className={`flex-1 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${
                            !oos.meetsMinStock ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'
                        }`}
                        >NO</button>
                    </div>
                  </div>

                  {!oos.meetsMinStock && (
                    <div className="pt-2 animate-in slide-in-from-top-1">
                      <select
                        className="w-full px-4 py-3 rounded-xl bg-rose-50 border-none font-bold text-[10px] text-rose-700 uppercase"
                        value={oos.reason || ''}
                        onChange={e => handleOOSChange(oos.id, 'reason', e.target.value)}
                      >
                        <option value="">-- Seleccionar Motivo --</option>
                        {OOS_REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                      </select>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {oosItems.length === 0 && (
                <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-2xl bg-slate-50/50">
                    <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Sin quiebres reportados</p>
                </div>
            )}
          </div>
        </section>

        {/* Botón Flotante de Acción Principal */}
        <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-slate-50 via-slate-50 to-transparent z-[60]">
            <button
                type="submit"
                disabled={isSubmitting}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white h-16 rounded-2xl shadow-2xl shadow-blue-500/40 font-black uppercase tracking-widest flex items-center justify-between px-8 active:scale-95 transition-all group disabled:opacity-50"
            >
                <div className="flex items-center gap-3">
                    {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={24} />}
                    <span>Finalizar Visita</span>
                </div>
                <ChevronRight size={24} className="group-hover:translate-x-1 transition-transform" />
            </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

import React, { useState, useMemo } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight, Hash, Filter } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS, User as UserType, AssignedStore, POS_CHECKLIST_ITEMS, MaterialChecklistRecord, NoMaterialReason } from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [checklist, setChecklist] = useState<MaterialChecklistRecord[]>(
    POS_CHECKLIST_ITEMS.map(item => ({ itemName: item, hasMaterial: false }))
  );

  // Estados para el buscador de quiebres
  const [skuSearch, setSkuSearch] = useState('');
  const [activeSkuCategory, setActiveSkuCategory] = useState<SKUCategory | 'ALL'>('ALL');

  const [isSubmitting, setIsSubmitting] = useState(false);

  // Filtrado de SKUs disponibles para el buscador
  const filteredSkus = useMemo(() => {
    let allSkus: { name: string, category: SKUCategory }[] = [];
    Object.entries(SKU_LISTS).forEach(([category, skus]) => {
      if (activeSkuCategory === 'ALL' || activeSkuCategory === category) {
        skus.forEach(sku => {
          // No mostrar si ya está en la lista de quiebres
          if (!oosItems.find(item => item.skuName === sku)) {
            allSkus.push({ name: sku, category: category as SKUCategory });
          }
        });
      }
    });

    if (skuSearch) {
      return allSkus.filter(s => s.name.toLowerCase().includes(skuSearch.toLowerCase())).slice(0, 8);
    }
    return skuSearch ? allSkus.slice(0, 8) : [];
  }, [skuSearch, activeSkuCategory, oosItems]);

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    ));
  };

  const handleAddOOSFromSearch = (sku: { name: string, category: SKUCategory }) => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: sku.category,
      skuName: sku.name,
      meetsMinStock: false, // Por defecto si se añade es porque hay quiebre
      reason: OOS_REASONS[0]
    };
    setOosItems([newOos, ...oosItems]);
    setSkuSearch(''); // Limpiar búsqueda
  };

  const handleChecklistChange = (itemName: string, field: keyof MaterialChecklistRecord, value: any) => {
    setChecklist(checklist.map(item => 
      item.itemName === itemName ? { ...item, [field]: value } : item
    ));
  };

  const handleChecklistPhoto = (itemName: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      handleChecklistChange(itemName, 'photoBase64', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!storeName) {
      alert('Por favor complete los campos obligatorios.');
      return;
    }
    setIsSubmitting(true);

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items: [],
          oosItems,
          checklist,
          location: { lat: pos.coords.latitude, lng: pos.coords.longitude }
        };
        onSave(audit);
      },
      () => {
        const audit: POSAudit = {
          id: crypto.randomUUID(),
          timestamp: Date.now(),
          storeId: prefillStore?.id,
          storeName,
          address,
          auditorId: user.id,
          auditorName: user.name,
          storeStatus,
          items: [],
          oosItems,
          checklist
        };
        onSave(audit);
      }
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      {/* Header Fijo */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1 hover:bg-white/10 rounded-full">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-lg font-black uppercase tracking-tight leading-none">Visita: {storeName}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1">Checklist de Ejecución</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* Sección 1: Estado Local */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Store size={18} className="text-blue-600" />
             <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Apertura de Punto</h2>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-sm' : 'bg-white border-slate-100 text-slate-400'}`}>
              <CheckCircle2 size={20} /> Abierto
            </button>
            <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-sm' : 'bg-white border-slate-100 text-slate-400'}`}>
              <XCircle size={20} /> Cerrado
            </button>
          </div>
        </section>

        {/* Sección 2: Materiales P.O.P. */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Sparkles size={18} className="text-blue-600" />
             <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Materiales de Comunicación</h2>
          </div>
          <div className="space-y-3">
            {checklist.map((item) => {
              const isCompleted = (item.hasMaterial && item.photoBase64) || (!item.hasMaterial && item.reason);
              return (
                <div key={item.itemName} className={`bg-white rounded-2xl border-2 transition-all duration-300 overflow-hidden ${isCompleted ? 'border-emerald-100' : 'border-slate-100'}`}>
                  <div className="p-4 flex items-center justify-between gap-4">
                    <span className="font-bold text-slate-800 text-xs flex-1">{item.itemName}</span>
                    <div className="flex bg-slate-100 p-1 rounded-xl w-32">
                       <button type="button" onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', true)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${item.hasMaterial ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>Tiene</button>
                       <button type="button" onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', false)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${!item.hasMaterial ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>No</button>
                    </div>
                  </div>
                  <div className="px-4 pb-4">
                    {item.hasMaterial ? (
                      <label className="relative block aspect-video w-full rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden">
                        {item.photoBase64 ? <img src={item.photoBase64} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-1 text-slate-300"><Camera size={24} /><span className="text-[8px] font-black uppercase">Tomar Foto</span></div>}
                        <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleChecklistPhoto(item.itemName, e.target.files[0])} />
                      </label>
                    ) : (
                      <div className="flex flex-wrap gap-1.5">
                        {Object.values(NoMaterialReason).map((r) => (
                          <button key={r} type="button" onClick={() => handleChecklistChange(item.itemName, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${item.reason === r ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-100 text-slate-400'}`}>{r}</button>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* Sección 3: Quiebres de Stock (OOS) - LA MEJORA SOLICITADA */}
        <section className="space-y-4">
          <div className="flex items-center justify-between px-1">
             <div className="flex items-center gap-2">
                <Ban size={18} className="text-rose-600" />
                <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Reportar Quiebres</h2>
             </div>
             <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full text-[10px] font-black">{oosItems.length} Reportados</span>
          </div>

          {/* Buscador de SKUs */}
          <div className="bg-white p-4 rounded-3xl border-2 border-slate-100 shadow-sm space-y-3">
            <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
              {['ALL', ...Object.values(SKUCategory)].map((cat) => (
                <button
                  key={cat}
                  type="button"
                  onClick={() => setActiveSkuCategory(cat as any)}
                  className={`whitespace-nowrap px-3 py-1.5 rounded-full text-[10px] font-black uppercase border transition-all ${
                    activeSkuCategory === cat ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 border-slate-100 text-slate-400'
                  }`}
                >
                  {cat === 'ALL' ? 'Todos' : cat}
                </button>
              ))}
            </div>

            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input
                type="text"
                placeholder="Buscar producto..."
                className="w-full pl-10 pr-4 py-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-blue-500 font-bold text-xs"
                value={skuSearch}
                onChange={e => setSkuSearch(e.target.value)}
              />
            </div>

            {/* Resultados de búsqueda rápidos */}
            {filteredSkus.length > 0 && (
              <div className="grid grid-cols-1 gap-2 animate-in fade-in slide-in-from-top-2">
                {filteredSkus.map(sku => (
                  <button
                    key={sku.name}
                    type="button"
                    onClick={() => handleAddOOSFromSearch(sku)}
                    className="flex items-center justify-between p-3 bg-blue-50/50 rounded-xl border border-blue-100 group active:bg-blue-100"
                  >
                    <div className="text-left">
                      <div className="text-[10px] font-bold text-slate-900">{sku.name}</div>
                      <div className="text-[8px] font-black text-blue-500 uppercase">{sku.category}</div>
                    </div>
                    <Plus size={16} className="text-blue-500" />
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Listado de Quiebres Reportados */}
          <div className="space-y-3">
            {oosItems.map((oos) => (
              <div key={oos.id} className="bg-white p-4 rounded-2xl border border-rose-100 shadow-sm relative animate-in zoom-in-95">
                <button type="button" onClick={() => setOosItems(oosItems.filter(i => i.id !== oos.id))} className="absolute top-3 right-3 text-slate-300 hover:text-rose-500"><Trash2 size={16} /></button>
                <div className="pr-8">
                  <div className="text-[8px] font-black text-rose-500 uppercase tracking-widest">{oos.category}</div>
                  <div className="font-bold text-slate-900 text-xs mb-3">{oos.skuName}</div>

                  <div className="space-y-2">
                    <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">¿Por qué no hay stock?</div>
                    <div className="flex flex-wrap gap-1.5">
                      {OOS_REASONS.map(r => (
                        <button
                          key={r}
                          type="button"
                          onClick={() => handleOOSChange(oos.id, 'reason', r)}
                          className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${
                            oos.reason === r ? 'bg-rose-600 border-rose-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'
                          }`}
                        >
                          {r}
                        </button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
            {oosItems.length === 0 && !skuSearch && (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-3xl bg-slate-50/50">
                <Package size={32} className="mx-auto text-slate-200 mb-2" />
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest">No hay quiebres reportados aún</p>
              </div>
            )}
          </div>
        </section>

        {/* Botón Flotante */}
        <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-slate-50 to-transparent z-[60]">
            <button type="submit" disabled={isSubmitting} className="w-full bg-slate-900 text-white h-16 rounded-2xl shadow-2xl font-black uppercase tracking-widest flex items-center justify-between px-8 active:scale-95 disabled:opacity-50">
                <div className="flex items-center gap-3">
                    {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />}
                    <span>Finalizar Auditoría</span>
                </div>
                <ChevronRight size={20} />
            </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

