import React, { useState, useMemo } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight, Hash, Filter, Info, ShieldAlert } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS, User as UserType, AssignedStore, POS_CHECKLIST_ITEMS, MaterialChecklistRecord, NoMaterialReason, AuditAccess, DENIAL_REASONS } from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');

  // Estados de Apertura
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);
  const [auditAccess, setAuditAccess] = useState<AuditAccess>(AuditAccess.ALLOWED);
  const [denialReason, setDenialReason] = useState<string>('');

  // Estados de Checklist y OOS
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [checklist, setChecklist] = useState<MaterialChecklistRecord[]>(
    POS_CHECKLIST_ITEMS.map(item => ({ itemName: item, hasMaterial: false }))
  );

  const [skuSearch, setSkuSearch] = useState('');
  const [activeSkuCategory, setActiveSkuCategory] = useState<SKUCategory | 'ALL'>('ALL');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const filteredSkus = useMemo(() => {
    let allSkus: { name: string, category: SKUCategory }[] = [];
    Object.entries(SKU_LISTS).forEach(([category, skus]) => {
      if (activeSkuCategory === 'ALL' || activeSkuCategory === category) {
        skus.forEach(sku => {
          if (!oosItems.find(item => item.skuName === sku)) {
            allSkus.push({ name: sku, category: category as SKUCategory });
          }
        });
      }
    });

    if (skuSearch) {
      return allSkus.filter(s => s.name.toLowerCase().includes(skuSearch.toLowerCase())).slice(0, 8);
    }
    return skuSearch ? allSkus.slice(0, 8) : [];
  }, [skuSearch, activeSkuCategory, oosItems]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    ));
  };

  const handleAddOOSFromSearch = (sku: { name: string, category: SKUCategory }) => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: sku.category,
      skuName: sku.name,
      meetsMinStock: false,
      reason: OOS_REASONS[0]
    };
    setOosItems([newOos, ...oosItems]);
    setSkuSearch('');
  };

  const handleChecklistChange = (itemName: string, field: keyof MaterialChecklistRecord, value: any) => {
    setChecklist(checklist.map(item => 
      item.itemName === itemName ? { ...item, [field]: value } : item
    ));
  };

  const handleChecklistPhoto = (itemName: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      handleChecklistChange(itemName, 'photoBase64', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) {
      alert('Es obligatorio tomar una foto de la fachada de la tienda.');
      return;
    }
    if (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED && !denialReason) {
      alert('Debe especificar un motivo por el cual no se permitió auditar.');
      return;
    }

    setIsSubmitting(true);

    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        storeId: prefillStore?.id,
        storeName,
        address,
        auditorId: user.id,
        auditorName: user.name,
        storeStatus,
        statusPhotoBase64: statusPhoto || undefined,
        auditAccess: storeStatus === StoreStatus.OPEN ? auditAccess : undefined,
        denialReason: (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED) ? denialReason : undefined,
        items: [],
        oosItems: (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.ALLOWED) ? oosItems : [],
        checklist: (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.ALLOWED) ? checklist : [],
        location: coords
      };
      onSave(audit);
    };

    navigator.geolocation.getCurrentPosition(
      (pos) => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => finalize()
    );
  };

  const showExecutionSections = storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.ALLOWED;

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      {/* Header */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1 hover:bg-white/10 rounded-full transition-colors">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-lg font-black uppercase tracking-tight leading-none truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1">Checklist de Punto de Venta</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* Sección Inicial: Foto de Fachada y Estado */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Store size={18} className="text-blue-600" />
             <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Apertura de Visita</h2>
          </div>

          <div className="bg-white p-5 rounded-3xl border-2 border-slate-100 shadow-sm space-y-6">
            {/* Foto de Estado Oblogatoria */}
            <div className="space-y-3">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Foto de Fachada / Estado PDV *</label>
              <label className="relative block aspect-[4/3] w-full rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden active:scale-[0.98] transition-all">
                {statusPhoto ? (
                  <img src={statusPhoto} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-slate-300">
                     <Camera size={48} className="text-slate-200" />
                     <span className="text-[10px] font-black uppercase tracking-widest">Capturar Evidencia</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
              </label>
            </div>

            {/* Selector de Estado Abierto/Cerrado */}
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-sm' : 'bg-white border-slate-100 text-slate-400'}`}>
                <CheckCircle2 size={20} /> Abierto
              </button>
              <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-sm' : 'bg-white border-slate-100 text-slate-400'}`}>
                <XCircle size={20} /> Cerrado
              </button>
            </div>

            {/* Pregunta de Permiso (Solo si está Abierto) */}
            {storeStatus === StoreStatus.OPEN && (
              <div className="pt-4 border-t border-slate-100 animate-in slide-in-from-top-2">
                <div className="flex flex-col gap-4">
                  <div className="flex items-center gap-2">
                    <Info size={16} className="text-blue-500" />
                    <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest">¿Te permitieron tomar información?</span>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-2xl">
                    <button 
                      type="button" 
                      onClick={() => setAuditAccess(AuditAccess.ALLOWED)} 
                      className={`flex-1 py-3 rounded-xl text-xs font-black uppercase transition-all ${auditAccess === AuditAccess.ALLOWED ? 'bg-white text-blue-600 shadow-md' : 'text-slate-400'}`}
                    >
                      Sí, permitido
                    </button>
                    <button 
                      type="button" 
                      onClick={() => setAuditAccess(AuditAccess.DENIED)} 
                      className={`flex-1 py-3 rounded-xl text-xs font-black uppercase transition-all ${auditAccess === AuditAccess.DENIED ? 'bg-white text-rose-600 shadow-md' : 'text-slate-400'}`}
                    >
                      No permitido
                    </button>
                  </div>
                </div>

                {/* Motivos de Rechazo */}
                {auditAccess === AuditAccess.DENIED && (
                  <div className="mt-6 space-y-3 animate-in fade-in zoom-in-95">
                    <div className="flex items-center gap-2 text-rose-600">
                      <ShieldAlert size={16} />
                      <span className="text-[10px] font-black uppercase tracking-widest">Seleccionar Motivo de Rechazo</span>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {DENIAL_REASONS.map((reason) => (
                        <button
                          key={reason}
                          type="button"
                          onClick={() => setDenialReason(reason)}
                          className={`px-4 py-2.5 rounded-xl text-[10px] font-bold border transition-all ${denialReason === reason ? 'bg-rose-600 border-rose-600 text-white shadow-lg shadow-rose-200' : 'bg-white border-slate-200 text-slate-500'}`}
                        >
                          {reason}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </section>

        {/* Secciones de Ejecución: Solo si es permitido auditar */}
        {showExecutionSections ? (
          <>
            {/* Sección 2: Materiales P.O.P. */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1">
                <Sparkles size={18} className="text-blue-600" />
                <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Materiales de Comunicación</h2>
              </div>
              <div className="space-y-3">
                {checklist.map((item) => {
                  const isCompleted = (item.hasMaterial && item.photoBase64) || (!item.hasMaterial && item.reason);
                  return (
                    <div key={item.itemName} className={`bg-white rounded-2xl border-2 transition-all duration-300 overflow-hidden ${isCompleted ? 'border-emerald-100' : 'border-slate-100'}`}>
                      <div className="p-4 flex items-center justify-between gap-4">
                        <span className="font-bold text-slate-800 text-xs flex-1">{item.itemName}</span>
                        <div className="flex bg-slate-100 p-1 rounded-xl w-32">
                          <button type="button" onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', true)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${item.hasMaterial ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>Tiene</button>
                          <button type="button" onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', false)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${!item.hasMaterial ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>No</button>
                        </div>
                      </div>
                      <div className="px-4 pb-4">
                        {item.hasMaterial ? (
                          <label className="relative block aspect-video w-full rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden">
                            {item.photoBase64 ? <img src={item.photoBase64} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-1 text-slate-300"><Camera size={24} /><span className="text-[8px] font-black uppercase">Tomar Foto</span></div>}
                            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleChecklistPhoto(item.itemName, e.target.files[0])} />
                          </label>
                        ) : (
                          <div className="flex flex-wrap gap-1.5">
                            {Object.values(NoMaterialReason).map((r) => (
                              <button key={r} type="button" onClick={() => handleChecklistChange(item.itemName, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${item.reason === r ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-100 text-slate-400'}`}>{r}</button>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>

            {/* Sección 3: Quiebres de Stock (OOS) */}
            <section className="space-y-4">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-2">
                    <Ban size={18} className="text-rose-600" />
                    <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Reportar Quiebres</h2>
                </div>
                <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full text-[10px] font-black">{oosItems.length} Reportados</span>
              </div>

              <div className="bg-white p-4 rounded-3xl border-2 border-slate-100 shadow-sm space-y-3">
                <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
                  {['ALL', ...Object.values(SKUCategory)].map((cat) => (
                    <button key={cat} type="button" onClick={() => setActiveSkuCategory(cat as any)} className={`whitespace-nowrap px-3 py-1.5 rounded-full text-[10px] font-black uppercase border transition-all ${activeSkuCategory === cat ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 border-slate-100 text-slate-400'}`}>
                      {cat === 'ALL' ? 'Todos' : cat}
                    </button>
                  ))}
                </div>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" placeholder="Buscar producto..." className="w-full pl-10 pr-4 py-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-blue-500 font-bold text-xs" value={skuSearch} onChange={e => setSkuSearch(e.target.value)} />
                </div>
                {filteredSkus.length > 0 && (
                  <div className="grid grid-cols-1 gap-2 animate-in fade-in slide-in-from-top-2">
                    {filteredSkus.map(sku => (
                      <button key={sku.name} type="button" onClick={() => handleAddOOSFromSearch(sku)} className="flex items-center justify-between p-3 bg-blue-50/50 rounded-xl border border-blue-100 group active:bg-blue-100">
                        <div className="text-left">
                          <div className="text-[10px] font-bold text-slate-900">{sku.name}</div>
                          <div className="text-[8px] font-black text-blue-500 uppercase">{sku.category}</div>
                        </div>
                        <Plus size={16} className="text-blue-500" />
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="space-y-3">
                {oosItems.map((oos) => (
                  <div key={oos.id} className="bg-white p-4 rounded-2xl border border-rose-100 shadow-sm relative animate-in zoom-in-95">
                    <button type="button" onClick={() => setOosItems(oosItems.filter(i => i.id !== oos.id))} className="absolute top-3 right-3 text-slate-300 hover:text-rose-500"><Trash2 size={16} /></button>
                    <div className="pr-8">
                      <div className="text-[8px] font-black text-rose-500 uppercase tracking-widest">{oos.category}</div>
                      <div className="font-bold text-slate-900 text-xs mb-3">{oos.skuName}</div>
                      <div className="space-y-2">
                        <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">¿Por qué no hay stock?</div>
                        <div className="flex flex-wrap gap-1.5">
                          {OOS_REASONS.map(r => (
                            <button key={r} type="button" onClick={() => handleOOSChange(oos.id, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${oos.reason === r ? 'bg-rose-600 border-rose-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </>
        ) : storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED ? (
          <div className="p-10 text-center bg-rose-50 rounded-3xl border-2 border-dashed border-rose-100 animate-in fade-in">
            <ShieldAlert size={48} className="mx-auto text-rose-300 mb-4" />
            <h3 className="text-sm font-black text-rose-700 uppercase tracking-widest">Visita con Acceso Denegado</h3>
            <p className="text-xs text-rose-500 mt-2">La información de ejecución no será recolectada. Pulse "Finalizar" para registrar el rechazo.</p>
          </div>
        ) : storeStatus === StoreStatus.CLOSED ? (
          <div className="p-10 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 animate-in fade-in">
            <XCircle size={48} className="mx-auto text-slate-300 mb-4" />
            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest">Local Cerrado</h3>
            <p className="text-xs text-slate-400 mt-2">Se registró la evidencia fotográfica del local cerrado. Pulse "Finalizar" para concluir la visita.</p>
          </div>
        ) : null}

        {/* Botón Flotante de Finalización */}
        <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-slate-50 to-transparent z-[60]">
            <button type="submit" disabled={isSubmitting} className="w-full bg-slate-900 text-white h-16 rounded-2xl shadow-2xl font-black uppercase tracking-widest flex items-center justify-between px-8 active:scale-95 disabled:opacity-50 transition-all">
                <div className="flex items-center gap-3">
                    {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />}
                    <span>Finalizar Visita</span>
                </div>
                <ChevronRight size={20} />
            </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

import React, { useState, useMemo } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight, Hash, Filter, Info, ShieldAlert, Lightbulb } from 'lucide-react';
import { MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, OOS_REASONS, User as UserType, AssignedStore, POS_CHECKLIST_ITEMS, MaterialChecklistRecord, NoMaterialReason, AuditAccess, DENIAL_REASONS } from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');

  // Estados de Apertura
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);
  const [auditAccess, setAuditAccess] = useState<AuditAccess>(AuditAccess.ALLOWED);
  const [denialReason, setDenialReason] = useState<string>('');

  // Estados de Checklist y OOS
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);
  const [checklist, setChecklist] = useState<MaterialChecklistRecord[]>(
    POS_CHECKLIST_ITEMS.map(item => ({ itemName: item, hasMaterial: false }))
  );

  const [skuSearch, setSkuSearch] = useState('');
  const [activeSkuCategory, setActiveSkuCategory] = useState<SKUCategory | 'ALL'>('ALL');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const filteredSkus = useMemo(() => {
    let allSkus: { name: string, category: SKUCategory }[] = [];
    Object.entries(SKU_LISTS).forEach(([category, skus]) => {
      if (activeSkuCategory === 'ALL' || activeSkuCategory === category) {
        skus.forEach(sku => {
          if (!oosItems.find(item => item.skuName === sku)) {
            allSkus.push({ name: sku, category: category as SKUCategory });
          }
        });
      }
    });

    if (skuSearch) {
      return allSkus.filter(s => s.name.toLowerCase().includes(skuSearch.toLowerCase())).slice(0, 8);
    }
    return skuSearch ? allSkus.slice(0, 8) : [];
  }, [skuSearch, activeSkuCategory, oosItems]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handleOOSChange = (id: string, field: keyof OOSItem, value: any) => {
    setOosItems(oosItems.map(item => 
      item.id === id ? { ...item, [field]: value } : item
    ));
  };

  const handleAddOOSFromSearch = (sku: { name: string, category: SKUCategory }) => {
    const newOos: OOSItem = {
      id: crypto.randomUUID(),
      category: sku.category,
      skuName: sku.name,
      meetsMinStock: false,
      reason: OOS_REASONS[0]
    };
    setOosItems([newOos, ...oosItems]);
    setSkuSearch('');
  };

  const handleChecklistChange = (itemName: string, field: keyof MaterialChecklistRecord, value: any) => {
    setChecklist(checklist.map(item => 
      item.itemName === itemName ? { ...item, [field]: value } : item
    ));
  };

  const handleChecklistPhoto = (itemName: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      handleChecklistChange(itemName, 'photoBase64', reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) {
      alert('Es obligatorio tomar una foto de la fachada de la tienda.');
      return;
    }
    if (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED && !denialReason) {
      alert('Debe especificar un motivo por el cual no se permitió auditar.');
      return;
    }

    setIsSubmitting(true);

    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(),
        timestamp: Date.now(),
        storeId: prefillStore?.id,
        storeName,
        address,
        auditorId: user.id,
        auditorName: user.name,
        storeStatus,
        statusPhotoBase64: statusPhoto || undefined,
        auditAccess: storeStatus === StoreStatus.OPEN ? auditAccess : undefined,
        denialReason: (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED) ? denialReason : undefined,
        items: [],
        oosItems,
        checklist,
        location: coords
      };
      onSave(audit);
    };

    navigator.geolocation.getCurrentPosition(
      (pos) => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => finalize()
    );
  };

  const showExecutionSections = storeStatus === StoreStatus.OPEN;

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      {/* Header */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1 hover:bg-white/10 rounded-full transition-colors">
            <ArrowLeft size={24} />
          </button>
          <div>
            <h1 className="text-lg font-black uppercase tracking-tight leading-none truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1">Checklist de Punto de Venta</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* Sección Inicial: Apertura */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1">
             <Store size={18} className="text-blue-600" />
             <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Apertura de Visita</h2>
          </div>

          <div className="bg-white p-5 rounded-3xl border-2 border-slate-100 shadow-sm space-y-6">
            {/* Foto de Estado - Ahora más pequeña */}
            <div className="space-y-3">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Foto de Fachada *</label>
              <label className="relative block aspect-[21/9] w-full rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden active:scale-[0.98] transition-all">
                {statusPhoto ? (
                  <img src={statusPhoto} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full flex flex-col items-center justify-center gap-1 text-slate-300">
                     <Camera size={28} className="text-slate-200" />
                     <span className="text-[9px] font-black uppercase tracking-widest">Tomar Foto</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
              </label>
            </div>

            {/* Selector de Estado */}
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-sm' : 'bg-white border-slate-100 text-slate-400'}`}>
                <CheckCircle2 size={20} /> Abierto
              </button>
              <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 transition-all font-bold text-sm ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-sm' : 'bg-white border-slate-100 text-slate-400'}`}>
                <XCircle size={20} /> Cerrado
              </button>
            </div>

            {/* Pregunta de Permiso */}
            {storeStatus === StoreStatus.OPEN && (
              <div className="pt-4 border-t border-slate-100 animate-in slide-in-from-top-2">
                <div className="flex flex-col gap-4">
                  <div className="flex items-center gap-2">
                    <Info size={16} className="text-blue-500" />
                    <span className="text-[10px] font-black text-slate-800 uppercase tracking-widest">¿Te permitieron tomar información?</span>
                  </div>
                  <div className="flex bg-slate-100 p-1 rounded-2xl">
                    <button 
                      type="button" 
                      onClick={() => setAuditAccess(AuditAccess.ALLOWED)} 
                      className={`flex-1 py-3 rounded-xl text-xs font-black uppercase transition-all ${auditAccess === AuditAccess.ALLOWED ? 'bg-white text-blue-600 shadow-md' : 'text-slate-400'}`}
                    >
                      Sí
                    </button>
                    <button 
                      type="button" 
                      onClick={() => setAuditAccess(AuditAccess.DENIED)} 
                      className={`flex-1 py-3 rounded-xl text-xs font-black uppercase transition-all ${auditAccess === AuditAccess.DENIED ? 'bg-white text-rose-600 shadow-md' : 'text-slate-400'}`}
                    >
                      No
                    </button>
                  </div>
                </div>

                {/* Motivos y MENSAJE DE CONTINGENCIA */}
                {auditAccess === AuditAccess.DENIED && (
                  <div className="mt-6 space-y-4 animate-in fade-in zoom-in-95">
                    {/* El Mensaje solicitado */}
                    <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 flex gap-3 shadow-sm shadow-amber-100/50">
                      <div className="p-2 bg-amber-100 text-amber-600 rounded-xl h-fit">
                        <Lightbulb size={20} />
                      </div>
                      <p className="text-xs font-bold text-amber-800 leading-relaxed italic">
                        Recuerda si no pudiste ingresar al counter, puedes trabajar por fuera del counter, implementa materiales y limpia activos! Y completa el app.
                      </p>
                    </div>

                    <div className="flex items-center gap-2 text-rose-600">
                      <ShieldAlert size={16} />
                      <span className="text-[10px] font-black uppercase tracking-widest">Seleccionar Motivo</span>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {DENIAL_REASONS.map((reason) => (
                        <button
                          key={reason}
                          type="button"
                          onClick={() => setDenialReason(reason)}
                          className={`px-4 py-2.5 rounded-xl text-[10px] font-bold border transition-all ${denialReason === reason ? 'bg-rose-600 border-rose-600 text-white shadow-lg shadow-rose-200' : 'bg-white border-slate-200 text-slate-500'}`}
                        >
                          {reason}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </section>

        {/* Secciones de Ejecución: Permanecen visibles si el local está abierto */}
        {showExecutionSections ? (
          <>
            {/* Sección 2: Materiales P.O.P. */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1">
                <Sparkles size={18} className="text-blue-600" />
                <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Materiales de Comunicación</h2>
              </div>
              <div className="space-y-3">
                {checklist.map((item) => {
                  const isCompleted = (item.hasMaterial && item.photoBase64) || (!item.hasMaterial && item.reason);
                  return (
                    <div key={item.itemName} className={`bg-white rounded-2xl border-2 transition-all duration-300 overflow-hidden ${isCompleted ? 'border-emerald-100 shadow-sm' : 'border-slate-100'}`}>
                      <div className="p-4 flex items-center justify-between gap-4">
                        <span className="font-bold text-slate-800 text-xs flex-1">{item.itemName}</span>
                        <div className="flex bg-slate-100 p-1 rounded-xl w-32">
                          <button type="button" onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', true)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${item.hasMaterial ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>Tiene</button>
                          <button type="button" onClick={() => handleChecklistChange(item.itemName, 'hasMaterial', false)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase transition-all ${!item.hasMaterial ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>No</button>
                        </div>
                      </div>
                      <div className="px-4 pb-4">
                        {item.hasMaterial ? (
                          <label className="relative block aspect-video w-full rounded-xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden active:scale-[0.99] transition-all">
                            {item.photoBase64 ? <img src={item.photoBase64} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-1 text-slate-300"><Camera size={20} /><span className="text-[7px] font-black uppercase">Click para Foto</span></div>}
                            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleChecklistPhoto(item.itemName, e.target.files[0])} />
                          </label>
                        ) : (
                          <div className="flex flex-wrap gap-1.5">
                            {Object.values(NoMaterialReason).map((r) => (
                              <button key={r} type="button" onClick={() => handleChecklistChange(item.itemName, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${item.reason === r ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-white border-slate-100 text-slate-400'}`}>{r}</button>
                            ))}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>

            {/* Sección 3: Quiebres de Stock (OOS) */}
            <section className="space-y-4">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-2">
                    <Ban size={18} className="text-rose-600" />
                    <h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Reportar Quiebres</h2>
                </div>
                <span className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full text-[10px] font-black">{oosItems.length} Reportados</span>
              </div>

              <div className="bg-white p-4 rounded-3xl border-2 border-slate-100 shadow-sm space-y-3">
                <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
                  {['ALL', ...Object.values(SKUCategory)].map((cat) => (
                    <button key={cat} type="button" onClick={() => setActiveSkuCategory(cat as any)} className={`whitespace-nowrap px-3 py-1.5 rounded-full text-[10px] font-black uppercase border transition-all ${activeSkuCategory === cat ? 'bg-slate-900 border-slate-900 text-white' : 'bg-slate-50 border-slate-100 text-slate-400'}`}>
                      {cat === 'ALL' ? 'Todos' : cat}
                    </button>
                  ))}
                </div>
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" placeholder="Buscar producto..." className="w-full pl-10 pr-4 py-3 bg-slate-50 rounded-xl border-none outline-none focus:ring-2 focus:ring-blue-500 font-bold text-xs" value={skuSearch} onChange={e => setSkuSearch(e.target.value)} />
                </div>
                {filteredSkus.length > 0 && (
                  <div className="grid grid-cols-1 gap-2 animate-in fade-in slide-in-from-top-2">
                    {filteredSkus.map(sku => (
                      <button key={sku.name} type="button" onClick={() => handleAddOOSFromSearch(sku)} className="flex items-center justify-between p-3 bg-blue-50/50 rounded-xl border border-blue-100 group active:bg-blue-100">
                        <div className="text-left">
                          <div className="text-[10px] font-bold text-slate-900">{sku.name}</div>
                          <div className="text-[8px] font-black text-blue-500 uppercase">{sku.category}</div>
                        </div>
                        <Plus size={16} className="text-blue-500" />
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <div className="space-y-3">
                {oosItems.map((oos) => (
                  <div key={oos.id} className="bg-white p-4 rounded-2xl border border-rose-100 shadow-sm relative animate-in zoom-in-95">
                    <button type="button" onClick={() => setOosItems(oosItems.filter(i => i.id !== oos.id))} className="absolute top-3 right-3 text-slate-300 hover:text-rose-500"><Trash2 size={16} /></button>
                    <div className="pr-8">
                      <div className="text-[8px] font-black text-rose-500 uppercase tracking-widest">{oos.category}</div>
                      <div className="font-bold text-slate-900 text-xs mb-3">{oos.skuName}</div>
                      <div className="space-y-2">
                        <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">¿Por qué no hay stock?</div>
                        <div className="flex flex-wrap gap-1.5">
                          {OOS_REASONS.map(r => (
                            <button key={r} type="button" onClick={() => handleOOSChange(oos.id, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${oos.reason === r ? 'bg-rose-600 border-rose-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>
                          ))}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </>
        ) : storeStatus === StoreStatus.CLOSED ? (
          <div className="p-10 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200 animate-in fade-in">
            <XCircle size={48} className="mx-auto text-slate-300 mb-4" />
            <h3 className="text-sm font-black text-slate-500 uppercase tracking-widest">Local Cerrado</h3>
            <p className="text-xs text-slate-400 mt-2">Se registró la evidencia fotográfica del local cerrado. Pulse "Finalizar" para concluir la visita.</p>
          </div>
        ) : null}

        {/* Botón Flotante de Finalización */}
        <div className="fixed bottom-0 left-0 w-full p-4 bg-gradient-to-t from-slate-50 to-transparent z-[60]">
            <button type="submit" disabled={isSubmitting} className="w-full bg-slate-900 text-white h-16 rounded-2xl shadow-2xl font-black uppercase tracking-widest flex items-center justify-between px-8 active:scale-95 disabled:opacity-50 transition-all">
                <div className="flex items-center gap-3">
                    {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />}
                    <span>Finalizar Visita</span>
                </div>
                <ChevronRight size={20} />
            </button>
        </div>
      </form>
    </div>
  );
};

