import React, { useState, useMemo } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight, Hash, Filter, Info, ShieldAlert, Lightbulb, ClipboardList, Wrench, Calendar, ListTodo, Camera as CameraIcon } from 'lucide-react';
import { 
  MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, 
  OOS_REASONS, User as UserType, AssignedStore, CURRENT_CAMPAIGNS, CampaignRecord, 
  NoMaterialReason, AuditAccess, DENIAL_REASONS, AuditArea, LAYOUT_FAIL_REASONS, POSAuditDetails,
  LAYOUT_FIX_REASONS, INCIDENCE_REASONS, ACTIVE_FIX_REASONS, EXHIBITION_REASONS, AuditIndicator,
  MaintenanceStatus, MAINTENANCE_INCIDENTS, MAINTENANCE_ASSETS, MaintenanceRecord, MaintenanceSection,
  StockCountItem, FinalAudit
} from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');

  // Apertura
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);
  const [panoramicBefore, setPanoramicBefore] = useState<string | null>(null);
  const [auditAccess, setAuditAccess] = useState<AuditAccess>(AuditAccess.ALLOWED);
  const [denialReason, setDenialReason] = useState<string>('');

  // Indicadores PDV
  const [auditDetails, setAuditDetails] = useState<POSAuditDetails>({
    area: AuditArea.CIGARRERA,
    fefo: { value: null, comment: '' },
    initialLayout: { value: null, comment: '' },
    finalLayout: { value: null, comment: '' },
    contamination: { value: null, comment: '' },
    finalContamination: { value: null, comment: '' },
    vuseStorage: { value: null, comment: '' },
    incidence: { value: null, comment: '' },
    activeStatus: { value: null, comment: '' },
    exhibitionStatus: { value: null, comment: '' }
  });

  // Mantenimiento
  const [maintenance, setMaintenance] = useState<MaintenanceSection>({
    records: MAINTENANCE_ASSETS.map(asset => ({ assetName: asset, status: null })),
    generalComment: '',
  });

  // Stock y Vencimientos
  const [stockCounts, setStockCounts] = useState<StockCountItem[]>([]);
  const [stockSearch, setStockSearch] = useState('');
  const [activeStockCategory, setActiveStockCategory] = useState<SKUCategory.VUSE | SKUCategory.VELO>(SKUCategory.VUSE);

  // Campañas Actuales
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  // Checklist y OOS (Removido checklist anterior por Campañas Actuales)
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);

  const [skuSearch, setSkuSearch] = useState('');
  const [activeSkuCategory, setActiveSkuCategory] = useState<SKUCategory | 'ALL'>('ALL');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const showExecutionSections = storeStatus === StoreStatus.OPEN;

  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    if (!stockSearch) return list;
    return list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase()));
  }, [activeStockCategory, stockSearch]);

  const filteredSkus = useMemo(() => {
    let allSkus: { name: string, category: SKUCategory }[] = [];
    Object.entries(SKU_LISTS).forEach(([category, skus]) => {
      if (activeSkuCategory === 'ALL' || activeSkuCategory === category) {
        skus.forEach(sku => {
          if (!oosItems.find(item => item.skuName === sku)) {
            allSkus.push({ name: sku, category: category as SKUCategory });
          }
        });
      }
    });
    if (skuSearch) return allSkus.filter(s => s.name.toLowerCase().includes(skuSearch.toLowerCase())).slice(0, 8);
    return [];
  }, [skuSearch, activeSkuCategory, oosItems]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => {
      const currentIndicator = (prev[key] as AuditIndicator) || { value: null, comment: '' };
      return { ...prev, [key]: { ...currentIndicator, [field]: value } };
    });
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateMaintenanceRecord = (assetName: string, field: keyof MaintenanceRecord, value: any) => {
    setMaintenance(prev => ({
      ...prev,
      records: prev.records.map(r => r.assetName === assetName ? { ...r, [field]: value } : r)
    }));
  };

  const handleMaintenancePhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setMaintenance(prev => ({ ...prev, photoBase64: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const updateStockItem = (skuName: string, field: keyof StockCountItem, value: any) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      if (existing) {
        return prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i);
      } else {
        return [...prev, { skuName, quantity: field === 'quantity' ? value : 0, expirationDate: field === 'expirationDate' ? value : '' }];
      }
    });
  };

  const updateCampaign = (name: string, updates: Partial<CampaignRecord>) => {
    setCampaigns(prev => prev.map(c => c.name === name ? { ...c, ...updates } : c));
  };

  const handleCampaignPhoto = (name: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCampaign(name, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('Es obligatorio tomar una foto de la fachada.'); return; }
    if (showExecutionSections && !panoramicBefore) { alert('Es obligatoria la foto panorámica antes de la visita.'); return; }
    if (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED && !denialReason) { alert('Especifique un motivo de rechazo.'); return; }
    if (showExecutionSections && finalAudit.assetsCleaned === null) { alert('Por favor responda si se dejaron limpios los activos.'); return; }
    if (showExecutionSections && !finalAudit.panoramicPhoto) { alert('Es obligatoria la foto panorámica del counter.'); return; }

    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address, auditorId: user.id, auditorName: user.name,
        storeStatus, statusPhotoBase64: statusPhoto || undefined, panoramicPhotoBefore: panoramicBefore || undefined,
        auditAccess: storeStatus === StoreStatus.OPEN ? auditAccess : undefined,
        denialReason: (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED) ? denialReason : undefined,
        details: storeStatus === StoreStatus.OPEN ? auditDetails : undefined,
        maintenance: storeStatus === StoreStatus.OPEN ? maintenance : undefined,
        stockCounts: storeStatus === StoreStatus.OPEN ? stockCounts : undefined,
        campaigns: storeStatus === StoreStatus.OPEN ? campaigns : undefined,
        finalAudit: storeStatus === StoreStatus.OPEN ? finalAudit : undefined,
        items: [], oosItems, checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  const IndicatorCard = ({ label, keyName, reasons, showReasonIf, isVuseStorage }: any) => {
    const detail = (auditDetails[keyName] as AuditIndicator) || { value: null, comment: '' };
    return (
      <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4">
        <div className="flex justify-between items-center"><span className="text-xs font-bold text-slate-900 uppercase">{label}</span>
          {!isVuseStorage && (
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button type="button" onClick={() => updateAuditIndicator(keyName, 'value', true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${detail.value === true ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400'}`}>SI</button>
              <button type="button" onClick={() => updateAuditIndicator(keyName, 'value', false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${detail.value === false ? 'bg-rose-600 text-white shadow-sm' : 'text-slate-400'}`}>NO</button>
            </div>
          )}
        </div>
        {reasons && (showReasonIf ?? detail.value === false) && (
          <div className="flex flex-wrap gap-1.5 py-2">
            {reasons.map((r: any) => (<button key={r} type="button" onClick={() => updateAuditIndicator(keyName, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${detail.reason === r ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-400'}`}>{r}</button>))}
          </div>
        )}
        <input type="text" placeholder="Comentario..." className="w-full bg-slate-50 border-none rounded-xl py-2 px-4 text-xs font-medium" value={detail.comment} onChange={e => updateAuditIndicator(keyName, 'comment', e.target.value)} />
        {(detail.value !== null || isVuseStorage) && (
          <label className={`flex items-center justify-center gap-2 py-3 rounded-xl border cursor-pointer ${detail.photo ? 'bg-emerald-50 text-emerald-600' : 'bg-yellow-100 text-red-600'}`}>
            <Camera size={18} /><span className="text-[10px] font-black uppercase">FOTO</span>
            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleAuditPhoto(keyName, e.target.files[0])} />
          </label>
        )}
      </div>
    );
  };

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4"><button type="button" onClick={onCancel} className="p-1"><ArrowLeft size={24} /></button>
          <div><h1 className="text-lg font-black uppercase truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1><p className="text-[10px] text-blue-300 font-bold uppercase mt-1">Checklist PDV</p></div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* Apertura */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1"><Store size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Apertura</h2></div>
          <div className="bg-white p-5 rounded-3xl border-2 border-slate-100 shadow-sm space-y-4">
            <label className="relative block aspect-[21/9] w-full rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden">
              {statusPhoto ? <img src={statusPhoto} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-1 text-slate-300"><Camera size={28} /><span className="text-[9px] font-black uppercase">Foto Fachada *</span></div>}
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
            </label>
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 font-bold ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700' : 'bg-white border-slate-100 text-slate-400'}`}>Abierto</button>
              <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center gap-3 p-4 rounded-2xl border-2 font-bold ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700' : 'bg-white border-slate-100 text-slate-400'}`}>Cerrado</button>
            </div>
          </div>
        </section>

        {/* FOTO PANORÁMICA ANTES DE LA VISITA */}
        {showExecutionSections && (
          <section className="space-y-4 animate-in fade-in">
             <div className="flex items-center gap-2 px-1"><ImageIcon size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">FOTO ANTES DE LA VISITA</h2></div>
             <div className="bg-white p-5 rounded-3xl border-2 border-slate-100 shadow-sm">
                <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-2xl border-2 border-dashed transition-all cursor-pointer ${panoramicBefore ? 'bg-emerald-50 border-emerald-300' : 'bg-slate-50 border-slate-200 text-slate-400 hover:bg-slate-100'}`}>
                  {panoramicBefore ? (
                    <img src={panoramicBefore} className="w-full h-full object-cover rounded-2xl" />
                  ) : (
                    <div className="flex flex-col items-center gap-2">
                      <Camera size={40} className="text-slate-300" />
                      <span className="text-[10px] font-black uppercase tracking-widest">Foto Panorámica Obligatoria *</span>
                    </div>
                  )}
                  <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handlePanoramicBefore(e.target.files[0])} />
                </label>
             </div>
          </section>
        )}

        {/* Indicadores */}
        {showExecutionSections && (
          <section className="space-y-4">
            <div className="flex bg-slate-200 p-1 rounded-2xl overflow-x-auto no-scrollbar gap-1">
                 {Object.values(AuditArea).map(area => (<button key={area} type="button" onClick={() => setAuditDetails(prev => ({ ...prev, area }))} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase ${auditDetails.area === area ? 'bg-slate-900 text-white' : 'text-slate-500'}`}>{area}</button>))}
            </div>
            <div className="space-y-4">
               {auditDetails.area === AuditArea.CIGARRERA && (
                 <><IndicatorCard label="1. ¿CUMPLE FEFO?" keyName="fefo" /><IndicatorCard label="2. ¿CUMPLE LAYOUT?" keyName="initialLayout" reasons={LAYOUT_FAIL_REASONS} /><IndicatorCard label="3. ¿SE DEJÓ OK EL LAYOUT?" keyName="finalLayout" reasons={LAYOUT_FIX_REASONS} /><IndicatorCard label="4. ¿DÓNDE SE GUARDA LA MERCADERÍA?" keyName="vuseStorage" isVuseStorage /><IndicatorCard label="5. ¿INCIDENCIA?" keyName="incidence" reasons={INCIDENCE_REASONS} /><IndicatorCard label="6. ¿SE DEJÓ OK EL ACTIVO?" keyName="activeStatus" reasons={ACTIVE_FIX_REASONS} /></>
               )}
            </div>
          </section>
        )}

        {/* CAMPAÑAS ACTUALES (NUEVA SECCIÓN OPTIMIZADA) */}
        {showExecutionSections && (
          <section className="space-y-0 animate-in fade-in">
            <div className="bg-[#002060] text-white p-3 flex items-center gap-3">
              <span className="font-black text-sm">3</span>
              <h2 className="text-xs font-black uppercase tracking-widest">CAMPAÑAS ACTUALES</h2>
            </div>

            <div className="border-x border-slate-200 divide-y divide-slate-200">
              {campaigns.map((camp) => (
                <div key={camp.name} className="bg-white">
                  <div className="grid grid-cols-12 min-h-[50px] items-stretch">
                    {/* Material Name */}
                    <div className="col-span-4 bg-[#002060] text-white flex items-center px-4 py-3 border-r border-slate-200">
                      <span className="text-[9px] font-black leading-tight uppercase">{camp.name}</span>
                    </div>

                    {/* Logic Columns */}
                    <div className="col-span-8 flex flex-col">
                      {/* Top Row: Implementado / Foto / Comentario */}
                      <div className="grid grid-cols-12 flex-1 border-b border-slate-100">
                        <button 
                          type="button" 
                          onClick={() => updateCampaign(camp.name, { status: 'IMPLEMENTED', incidenceType: null })}
                          className={`col-span-4 flex items-center justify-center text-[10px] font-bold border-r border-slate-100 transition-colors ${camp.status === 'IMPLEMENTED' ? 'bg-blue-50 text-[#002060]' : 'text-slate-400'}`}
                        >
                          SE IMPLEMENTO
                        </button>

                        <label className="col-span-4 flex items-center justify-center text-[10px] font-bold border-r border-slate-100 cursor-pointer hover:bg-slate-50">
                          {camp.photo ? (
                            <div className="flex items-center gap-1 text-emerald-600">
                              <Check size={14} /> <span>FOTO OK</span>
                            </div>
                          ) : (
                            <span className="text-slate-400">FOTO</span>
                          )}
                          <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCampaignPhoto(camp.name, e.target.files[0])} />
                        </label>

                        <div className="col-span-4 flex items-center px-2">
                          <input 
                            type="text" 
                            placeholder="COMENTARIO" 
                            className="w-full text-[9px] font-bold outline-none placeholder:text-slate-300 text-center"
                            value={camp.comment}
                            onChange={e => updateCampaign(camp.name, { comment: e.target.value })}
                          />
                        </div>
                      </div>

                      {/* Bottom Row: Incidencia */}
                      <div className="flex-1">
                        <button 
                          type="button" 
                          onClick={() => updateCampaign(camp.name, { status: 'INCIDENCE', implementationType: null })}
                          className={`w-full h-full flex items-center justify-center text-[10px] font-bold transition-colors ${camp.status === 'INCIDENCE' ? 'bg-rose-50 text-rose-600' : 'text-slate-400'}`}
                        >
                          INCIDENCIA
                        </button>
                      </div>
                    </div>
                  </div>

                  {/* Contextual Options for "IMPLEMENTADO" */}
                  {camp.status === 'IMPLEMENTED' && (
                    <div className="grid grid-cols-12 bg-slate-50 border-t border-slate-100 animate-in slide-in-from-top-1">
                      <div className="col-span-4 border-r border-slate-100 py-3 flex items-center justify-center">
                         <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[8px] border-t-[#002060]"></div>
                      </div>
                      <div className="col-span-8 grid grid-cols-2 divide-x divide-slate-100">
                        <button 
                          type="button" 
                          onClick={() => updateCampaign(camp.name, { implementationType: 'PRIMERA' })}
                          className={`flex items-center justify-between px-3 py-3 transition-colors ${camp.implementationType === 'PRIMERA' ? 'bg-blue-100' : 'hover:bg-slate-100'}`}
                        >
                          <span className="text-[9px] font-bold">PRIMERA</span>
                          <span className="bg-[#8ec641] text-white text-[8px] font-black px-2 py-1 rounded">AGREGAR</span>
                        </button>
                        <button 
                          type="button" 
                          onClick={() => updateCampaign(camp.name, { implementationType: 'REABASTECIMIENTO' })}
                          className={`flex items-center justify-between px-3 py-3 transition-colors ${camp.implementationType === 'REABASTECIMIENTO' ? 'bg-blue-100' : 'hover:bg-slate-100'}`}
                        >
                          <span className="text-[9px] font-bold">REABASTECIMIENTO</span>
                          <span className="bg-[#8ec641] text-white text-[8px] font-black px-2 py-1 rounded">AGREGAR</span>
                        </button>
                      </div>
                    </div>
                  )}

                  {/* Contextual Options for "INCIDENCIA" */}
                  {camp.status === 'INCIDENCE' && (
                    <div className="grid grid-cols-12 bg-slate-50 border-t border-slate-100 animate-in slide-in-from-top-1">
                      <div className="col-span-4 border-r border-slate-100 py-3 flex items-center justify-center">
                         <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[8px] border-t-rose-500"></div>
                      </div>
                      <div className="col-span-8 grid grid-cols-2 divide-x divide-slate-100">
                        <button 
                          type="button" 
                          onClick={() => updateCampaign(camp.name, { incidenceType: 'NO_STOCK' })}
                          className={`flex items-center justify-between px-3 py-3 transition-colors ${camp.incidenceType === 'NO_STOCK' ? 'bg-rose-100' : 'hover:bg-slate-100'}`}
                        >
                          <span className="text-[9px] font-bold">NO TENGO STOCK DEL MATERIAL</span>
                          <span className="bg-[#8ec641] text-white text-[8px] font-black px-2 py-1 rounded">AGREGAR</span>
                        </button>
                        <button 
                          type="button" 
                          onClick={() => updateCampaign(camp.name, { incidenceType: 'OTHER' })}
                          className={`flex items-center justify-between px-3 py-3 transition-colors ${camp.incidenceType === 'OTHER' ? 'bg-rose-100' : 'hover:bg-slate-100'}`}
                        >
                          <span className="text-[9px] font-bold">OTRO COMENTARIO</span>
                          <span className="bg-[#8ec641] text-white text-[8px] font-black px-2 py-1 rounded">AGREGAR</span>
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>

            <div className="p-2 text-center bg-white border border-t-0 border-slate-200">
              <span className="text-[8px] font-bold text-rose-500">* Marcar solo una opción, no considerar comentarios</span>
            </div>
          </section>
        )}

        {/* Mantenimientos */}
        {showExecutionSections && (
          <section className="space-y-4">
            <div className="bg-[#8ec641] text-white p-3 rounded-t-2xl flex items-center gap-2"><Wrench size={20} /><h2 className="text-xs font-black uppercase">MANTENIMIENTOS</h2></div>
            <div className="bg-white border-2 border-[#8ec641]/20 rounded-b-2xl p-4 space-y-4">
                {maintenance.records.map(r => (
                  <div key={r.assetName} className="flex flex-col gap-2 p-2 border-b border-slate-50">
                    <div className="flex justify-between items-center"><span className="text-[10px] font-black uppercase text-slate-800">{r.assetName}</span>
                      <div className="flex bg-slate-100 p-1 rounded-xl">
                        <button type="button" onClick={() => updateMaintenanceRecord(r.assetName, 'status', MaintenanceStatus.GOOD)} className={`px-3 py-1 rounded-lg text-[9px] font-black ${r.status === MaintenanceStatus.GOOD ? 'bg-[#1e3a5f] text-white' : 'text-slate-400'}`}>BIEN</button>
                        <button type="button" onClick={() => updateMaintenanceRecord(r.assetName, 'status', MaintenanceStatus.BAD)} className={`px-3 py-1 rounded-lg text-[9px] font-black ${r.status === MaintenanceStatus.BAD ? 'bg-[#1e3a5f] text-white' : 'text-slate-400'}`}>MAL</button>
                      </div>
                    </div>
                  </div>
                ))}
            </div>
          </section>
        )}

        {/* CONTEO STOCK */}
        {showExecutionSections && (
          <section className="space-y-4">
            <div className="bg-[#1e3a5f] text-white p-3 rounded-t-2xl flex items-center justify-between">
              <div className="flex items-center gap-2"><Package size={20} /><h2 className="text-xs font-black uppercase">CONTEO STOCK</h2></div>
            </div>
            <div className="bg-white border-2 border-[#1e3a5f]/10 rounded-b-2xl overflow-hidden shadow-sm">
              <div className="p-3 bg-slate-50 flex flex-col gap-2">
                <div className="flex bg-slate-200 p-1 rounded-xl">
                  <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VUSE)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase ${activeStockCategory === SKUCategory.VUSE ? 'bg-white text-blue-600' : 'text-slate-500'}`}>VUSE</button>
                  <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VELO)} className={`flex-1 py-1.5 rounded-lg text-[9px] font-black uppercase ${activeStockCategory === SKUCategory.VELO ? 'bg-white text-blue-600' : 'text-slate-500'}`}>VELO</button>
                </div>
              </div>
              <div className="grid grid-cols-12 bg-slate-100 px-4 py-2 border-b text-[8px] font-black text-slate-500 uppercase tracking-widest">
                <div className="col-span-6">Producto</div><div className="col-span-2 text-center">Cant</div><div className="col-span-4 text-center">Vencimiento</div>
              </div>
              <div className="divide-y max-h-[400px] overflow-y-auto no-scrollbar">
                {filteredStockSkus.map(sku => {
                  const data = stockCounts.find(i => i.skuName === sku);
                  return (
                    <div key={sku} className={`grid grid-cols-12 items-center px-2 py-1.5 ${data && data.quantity > 0 ? 'bg-blue-50/40' : 'bg-white'}`}>
                      <div className="col-span-6 text-[10px] font-bold text-slate-800 truncate px-1">{sku}</div>
                      <div className="col-span-2 px-1"><input type="number" placeholder="0" className="w-full text-center py-1 bg-white border rounded text-[10px] font-black" value={data?.quantity || ''} onChange={e => updateStockItem(sku, 'quantity', parseInt(e.target.value) || 0)} /></div>
                      <div className="col-span-4 px-1"><input type="date" className="w-full text-[9px] py-1 bg-white border rounded" value={data?.expirationDate || ''} onChange={e => updateStockItem(sku, 'expirationDate', e.target.value)} /></div>
                    </div>
                  );
                })}
              </div>
            </div>
          </section>
        )}

        {/* AUDITORÍA FINAL */}
        {showExecutionSections && (
          <section className="space-y-0 animate-in fade-in">
            <div className="bg-[#c2920b] text-white p-3 text-center">
              <h2 className="text-xs font-black uppercase tracking-[0.2em]">AUDITORÍA FINAL</h2>
            </div>

            <div className="border border-slate-200">
              {/* Pregunta 1: Limpieza */}
              <div className="grid grid-cols-12 items-stretch border-b border-slate-200 min-h-[60px]">
                <div className="col-span-1 flex items-center justify-center bg-[#002060] text-white font-black text-xs border-r border-slate-200">
                  1
                </div>
                <div className="col-span-4 flex items-center px-4 bg-[#002060] text-white font-black text-[9px] uppercase leading-tight border-r border-slate-200">
                  ¿SE DEJARON LIMPIOS LOS ACTIVOS?
                </div>
                <div className="col-span-7 grid grid-cols-2 divide-x divide-slate-200 bg-white">
                  <button 
                    type="button" 
                    onClick={() => setFinalAudit(prev => ({ ...prev, assetsCleaned: true }))}
                    className={`flex items-center justify-center text-[10px] font-bold transition-colors ${finalAudit.assetsCleaned === true ? 'bg-blue-50 text-blue-700' : 'text-slate-400'}`}
                  >
                    SI
                  </button>
                  <button 
                    type="button" 
                    onClick={() => setFinalAudit(prev => ({ ...prev, assetsCleaned: false }))}
                    className={`flex items-center justify-center text-[10px] font-bold transition-colors ${finalAudit.assetsCleaned === false ? 'bg-rose-50 text-rose-700' : 'text-slate-400'}`}
                  >
                    NO
                  </button>
                </div>
              </div>

              {/* Comentario Limpieza */}
              <div className="bg-white border-b border-slate-200">
                <div className="px-12 py-1 text-center border-b border-dotted border-slate-300">
                  <span className="text-[8px] font-black text-[#002060] uppercase tracking-widest">COMENTARIO</span>
                </div>
                <textarea 
                  className="w-full px-4 py-2 text-xs font-medium outline-none text-center bg-transparent resize-none"
                  rows={2}
                  placeholder="..."
                  value={finalAudit.comment}
                  onChange={e => setFinalAudit(prev => ({ ...prev, comment: e.target.value }))}
                />
              </div>

              {/* Pregunta 2: Foto Panorámica */}
              <div className="grid grid-cols-12 items-stretch min-h-[50px]">
                <div className="col-span-1 flex items-center justify-center bg-[#002060] text-white font-black text-xs border-r border-slate-200">
                  2
                </div>
                <div className="col-span-4 flex items-center px-4 bg-[#002060] text-white font-black text-[9px] uppercase leading-tight border-r border-slate-200">
                  FOTO PANORÁMICA DEL COUNTER
                </div>
                <div className="col-span-7 relative bg-[#ffff00] active:bg-yellow-400 transition-colors">
                  <label className="flex items-center justify-center w-full h-full cursor-pointer gap-2">
                    {finalAudit.panoramicPhoto ? (
                      <>
                        <Check size={16} className="text-emerald-600" />
                        <span className="text-[10px] font-black text-emerald-600 uppercase">FOTO CAPTURADA</span>
                      </>
                    ) : (
                      <span className="text-[10px] font-black text-red-600 uppercase">FOTO</span>
                    )}
                    <input 
                      type="file" 
                      accept="image/*" 
                      capture="environment" 
                      className="hidden" 
                      onChange={e => e.target.files?.[0] && handleFinalPhoto(e.target.files[0])} 
                    />
                  </label>
                  {finalAudit.panoramicPhoto && (
                    <div className="absolute inset-0 pointer-events-none border-2 border-emerald-500 animate-pulse"></div>
                  )}
                </div>
              </div>
            </div>

            {/* Vista Previa Foto Panorámica */}
            {finalAudit.panoramicPhoto && (
              <div className="mt-2 rounded-xl overflow-hidden border border-slate-200 shadow-inner">
                <img src={finalAudit.panoramicPhoto} className="w-full h-32 object-cover" />
              </div>
            )}
          </section>
        )}

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/80 backdrop-blur-md border-t z-50">
          <button type="submit" disabled={isSubmitting} className="w-full bg-[#1e3a5f] text-white py-4 rounded-2xl font-black uppercase shadow-xl flex items-center justify-center gap-3">
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />} Finalizar Auditoría
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

import React, { useState, useMemo } from 'react';
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight, Hash, Filter, Info, ShieldAlert, Lightbulb, ClipboardList, Wrench, Calendar, ListTodo, Camera as CameraIcon } from 'lucide-react';
import { 
  MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, 
  OOS_REASONS, User as UserType, AssignedStore, CURRENT_CAMPAIGNS, CampaignRecord, 
  NoMaterialReason, AuditAccess, DENIAL_REASONS, AuditArea, LAYOUT_FAIL_REASONS, POSAuditDetails,
// Removed non-existent EXHIBITION_REASONS export which was causing a compilation error.
  LAYOUT_FIX_REASONS, INCIDENCE_REASONS, ACTIVE_FIX_REASONS, AuditIndicator,
  MaintenanceStatus, MAINTENANCE_INCIDENTS, MAINTENANCE_ASSETS, MaintenanceRecord, MaintenanceSection,
  StockCountItem, FinalAudit
} from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');

  // Apertura
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);
  const [panoramicBefore, setPanoramicBefore] = useState<string | null>(null);
  const [auditAccess, setAuditAccess] = useState<AuditAccess>(AuditAccess.ALLOWED);
  const [denialReason, setDenialReason] = useState<string>('');

  // Indicadores PDV
  const [auditDetails, setAuditDetails] = useState<POSAuditDetails>({
    area: AuditArea.CIGARRERA,
    fefo: { value: null, comment: '' },
    initialLayout: { value: null, comment: '' },
    finalLayout: { value: null, comment: '' },
    contamination: { value: null, comment: '' },
    finalContamination: { value: null, comment: '' },
    vuseStorage: { value: null, comment: '' },
    incidence: { value: null, comment: '' },
    activeStatus: { value: null, comment: '' },
    exhibitionStatus: { value: null, comment: '' }
  });

  // Mantenimiento
  const [maintenance, setMaintenance] = useState<MaintenanceSection>({
    records: MAINTENANCE_ASSETS.map(asset => ({ assetName: asset, status: null })),
    generalComment: '',
  });

  // Stock y Vencimientos
  const [stockCounts, setStockCounts] = useState<StockCountItem[]>([]);
  const [stockSearch, setStockSearch] = useState('');
  const [activeStockCategory, setActiveStockCategory] = useState<SKUCategory.VUSE | SKUCategory.VELO>(SKUCategory.VUSE);

  // Campañas Actuales
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  // Checklist y OOS (Removido checklist anterior por Campañas Actuales)
  const [oosItems, setOosItems] = useState<OOSItem[]>([]);

  const [skuSearch, setSkuSearch] = useState('');
  const [activeSkuCategory, setActiveSkuCategory] = useState<SKUCategory | 'ALL'>('ALL');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const showExecutionSections = storeStatus === StoreStatus.OPEN;

  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    if (!stockSearch) return list;
    return list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase()));
  }, [activeStockCategory, stockSearch]);

  const filteredSkus = useMemo(() => {
    let allSkus: { name: string, category: SKUCategory }[] = [];
    Object.entries(SKU_LISTS).forEach(([category, skus]) => {
      if (activeSkuCategory === 'ALL' || activeSkuCategory === category) {
        skus.forEach(sku => {
          if (!oosItems.find(item => item.skuName === sku)) {
            allSkus.push({ name: sku, category: category as SKUCategory });
          }
        });
      }
    });
    if (skuSearch) return allSkus.filter(s => s.name.toLowerCase().includes(skuSearch.toLowerCase())).slice(0, 8);
    return [];
  }, [skuSearch, activeSkuCategory, oosItems]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => {
      const currentIndicator = (prev[key] as AuditIndicator) || { value: null, comment: '' };
      return { ...prev, [key]: { ...currentIndicator, [field]: value } };
    });
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateMaintenanceRecord = (assetName: string, field: keyof MaintenanceRecord, value: any) => {
    setMaintenance(prev => ({
      ...prev,
      records: prev.records.map(r => r.assetName === assetName ? { ...r, [field]: value } : r)
    }));
  };

  const handleMaintenancePhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setMaintenance(prev => ({ ...prev, photoBase64: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const updateStockItem = (skuName: string, field: keyof StockCountItem, value: any) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      if (existing) {
        return prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i);
      } else {
        return [...prev, { skuName, quantity: field === 'quantity' ? value : 0, expirationDate: field === 'expirationDate' ? value : '' }];
      }
    });
  };

  const updateCampaign = (name: string, updates: Partial<CampaignRecord>) => {
    setCampaigns(prev => prev.map(c => c.name === name ? { ...c, ...updates } : c));
  };

  const handleCampaignPhoto = (name: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCampaign(name, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('Es obligatorio tomar una foto de la fachada.'); return; }
    if (showExecutionSections && !panoramicBefore) { alert('Es obligatoria la foto panorámica antes de la visita.'); return; }
    if (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED && !denialReason) { alert('Especifique un motivo de rechazo.'); return; }
    if (showExecutionSections && finalAudit.assetsCleaned === null) { alert('Por favor responda si se dejaron limpios los activos.'); return; }
    if (showExecutionSections && !finalAudit.panoramicPhoto) { alert('Es obligatoria la foto panorámica del counter.'); return; }

    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address, auditorId: user.id, auditorName: user.name,
        storeStatus, statusPhotoBase64: statusPhoto || undefined, panoramicPhotoBefore: panoramicBefore || undefined,
        auditAccess: storeStatus === StoreStatus.OPEN ? auditAccess : undefined,
        denialReason: (storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.DENIED) ? denialReason : undefined,
        details: storeStatus === StoreStatus.OPEN ? auditDetails : undefined,
        maintenance: storeStatus === StoreStatus.OPEN ? maintenance : undefined,
        stockCounts: storeStatus === StoreStatus.OPEN ? stockCounts : undefined,
        campaigns: storeStatus === StoreStatus.OPEN ? campaigns : undefined,
        finalAudit: storeStatus === StoreStatus.OPEN ? finalAudit : undefined,
        items: [], oosItems, checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  const IndicatorCard = ({ label, keyName, reasons, showReasonIf, isVuseStorage }: any) => {
    const detail = (auditDetails[keyName] as AuditIndicator) || { value: null, comment: '' };
    return (
      <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4">
        <div className="flex justify-between items-center"><span className="text-xs font-bold text-slate-900 uppercase">{label}</span>
          {!isVuseStorage && (
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button type="button" onClick={() => updateAuditIndicator(keyName, 'value', true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${detail.value === true ? 'bg-blue-600 text-white shadow-sm' : 'text-slate-400'}`}>SI</button>
              <button type="button" onClick={() => updateAuditIndicator(keyName, 'value', false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase transition-all ${detail.value === false ? 'bg-rose-600 text-white shadow-sm' : 'text-slate-400'}`}>NO</button>
            </div>
          )}
        </div>
        {reasons && (showReasonIf ?? detail.value === false) && (
          <div className="flex flex-wrap gap-1.5 py-2">
            {reasons.map((r: any) => (<button key={r} type="button" onClick={() => updateAuditIndicator(keyName, 'reason', r)} className={`px-2 py-1.5 rounded-lg text-[8px] font-bold border transition-all ${detail.reason === r ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-400'}`}>{r}</button>))}
