  // Campañas Actuales
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  // Lógica de visibilidad
  const showAccessQuestion = storeStatus === StoreStatus.OPEN;
  const showAuditFlow = storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.ALLOWED;

  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    if (!stockSearch) return list;
    return list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase()));
  }, [activeStockCategory, stockSearch]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => {
      const currentIndicator = (prev[key] as AuditIndicator) || { value: null, comment: '' };
      return { ...prev, [key]: { ...currentIndicator, [field]: value } };
    });
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateMaintenanceRecord = (assetName: string, field: keyof MaintenanceRecord, value: any) => {
    setMaintenance(prev => ({
      ...prev,
      records: prev.records.map(r => r.assetName === assetName ? { ...r, [field]: value } : r)
    }));
  };

  const updateStockItem = (skuName: string, field: keyof StockCountItem, value: any) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      if (existing) {
        return prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i);
      } else {
        return [...prev, { skuName, quantity: field === 'quantity' ? value : 0, expirationDate: field === 'expirationDate' ? value : '' }];
      }
    });
  };

  const updateCampaign = (name: string, updates: Partial<CampaignRecord>) => {
    setCampaigns(prev => prev.map(c => c.name === name ? { ...c, ...updates } : c));
  };

  const handleCampaignPhoto = (name: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCampaign(name, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('Es obligatorio tomar una foto de la fachada.'); return; }
    if (showAccessQuestion && !auditAccess) { alert('Por favor responda si se permitió tomar información.'); return; }
    if (showAuditFlow && !panoramicBefore) { alert('Es obligatoria la foto panorámica antes de la visita.'); return; }
    if (showAuditFlow && finalAudit.assetsCleaned === null) { alert('Por favor responda si se dejaron limpios los activos.'); return; }
    if (showAuditFlow && !finalAudit.panoramicPhoto) { alert('Es obligatoria la foto panorámica final.'); return; }

    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address, auditorId: user.id, auditorName: user.name,
        storeStatus, statusPhotoBase64: statusPhoto || undefined, panoramicPhotoBefore: panoramicBefore || undefined,
        auditAccess: showAccessQuestion ? (auditAccess || undefined) : undefined,
        denialReason: (showAccessQuestion && auditAccess === AuditAccess.DENIED) ? denialReason : undefined,
        details: showAuditFlow ? auditDetails : undefined,
        maintenance: showAuditFlow ? maintenance : undefined,
        stockCounts: showAuditFlow ? stockCounts : undefined,
        campaigns: showAuditFlow ? campaigns : undefined,
        finalAudit: showAuditFlow ? finalAudit : undefined,
        items: [], oosItems: [], checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  // Componente de Pregunta Amigable Estándar
  const QuestionCard = ({ label, icon: Icon, value, onChange, photo, onPhoto, comment, onComment, reasons, currentReason, onReason, isRequired }: any) => (
    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4 animate-in fade-in slide-in-from-top-2">
      <div className="flex justify-between items-start gap-3">
        <div className="flex gap-3">
          <div className={`p-2 rounded-xl shrink-0 ${value === null ? 'bg-slate-50 text-slate-400' : 'bg-blue-50 text-blue-600'}`}>
            <Icon size={18} />
          </div>
          <span className="text-[11px] font-black text-slate-700 uppercase leading-tight mt-1">{label} {isRequired && <span className="text-rose-500">*</span>}</span>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl">
          <button type="button" onClick={() => onChange(true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === true ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>SI</button>
          <button type="button" onClick={() => onChange(false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === false ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>NO</button>
        </div>
      </div>

      {reasons && value === false && (
        <div className="flex flex-wrap gap-2 py-1">
          {reasons.map((r: string) => (
            <button key={r} type="button" onClick={() => onReason(r)} className={`px-3 py-1.5 rounded-xl text-[9px] font-bold border transition-all ${currentReason === r ? 'bg-[#002060] border-[#002060] text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>
          ))}
        </div>
      )}

      {onComment && (
        <input 
          type="text" 
          placeholder="Añadir comentario (opcional)..." 
          className="w-full bg-slate-50 border-none rounded-2xl py-2.5 px-4 text-xs font-medium focus:ring-2 focus:ring-blue-100 transition-all" 
          value={comment || ''} 
          onChange={e => onComment(e.target.value)} 
        />
      )}

      {onPhoto && value !== null && (
        <label className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-yellow-50 border-yellow-200 text-amber-600'}`}>
          {photo ? <CheckCircle2 size={18} /> : <Camera size={18} />}
          <span className="text-[10px] font-black uppercase tracking-widest">{photo ? 'FOTO CAPTURADA' : 'TOMAR FOTO'}</span>
          <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && onPhoto(e.target.files[0])} />
        </label>
      )}
    </div>
  );

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1"><ArrowLeft size={24} /></button>
          <div>
            <h1 className="text-lg font-black uppercase truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1">Auditoría Trade Marketing</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* SECCIÓN 1: APERTURA */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1"><Store size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 1: Estado del Local</h2></div>
          <div className="bg-white p-5 rounded-3xl border-2 border-slate-100 shadow-sm space-y-5">
            <label className="relative block aspect-video w-full rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden cursor-pointer">
              {statusPhoto ? <img src={statusPhoto} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-slate-300"><Camera size={32} /><span className="text-[10px] font-black uppercase tracking-widest">Foto de la Fachada *</span></div>}
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
            </label>
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center py-4 rounded-2xl border-2 font-black uppercase text-[11px] tracking-widest transition-all ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-inner shadow-emerald-200' : 'bg-white border-slate-100 text-slate-400'}`}>ABIERTO</button>
              <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center py-4 rounded-2xl border-2 font-black uppercase text-[11px] tracking-widest transition-all ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-inner shadow-rose-200' : 'bg-white border-slate-100 text-slate-400'}`}>CERRADO</button>
            </div>
          </div>

          {/* PREGUNTA DE ACCESO (REINCORPORADA) */}
          {showAccessQuestion && (
            <QuestionCard 
              label="¿Permitió tomar información / realizar auditoría?"
              icon={ShieldAlert}
              value={auditAccess === AuditAccess.ALLOWED ? true : auditAccess === AuditAccess.DENIED ? false : null}
              onChange={(val: boolean) => setAuditAccess(val ? AuditAccess.ALLOWED : AuditAccess.DENIED)}
              reasons={DENIAL_REASONS}
              currentReason={denialReason}
              onReason={setDenialReason}
              isRequired
            />
          )}

          {/* FOTO PANORÁMICA PREVIA (SOLO SI PERMITIÓ) */}
          {showAuditFlow && (
            <div className="space-y-4 animate-in zoom-in-95">
              <div className="flex items-center gap-2 px-1"><ImageIcon size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 2: Registro Inicial</h2></div>
              <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-3xl border-2 border-dashed transition-all cursor-pointer shadow-sm ${panoramicBefore ? 'bg-blue-50 border-blue-300' : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'}`}>
                {panoramicBefore ? (
                  <img src={panoramicBefore} className="w-full h-full object-cover rounded-3xl" />
                ) : (
                  <div className="flex flex-col items-center gap-2">
                    <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center"><Camera size={24} className="text-slate-400" /></div>
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">Foto Panorámica Previa *</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handlePanoramicBefore(e.target.files[0])} />
              </label>
            </div>
          )}
        </section>

        {/* FLUJO PRINCIPAL DE AUDITORÍA */}
        {showAuditFlow && (
          <>
            {/* Áreas e Indicadores */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ListTodo size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 3: Checklist de Áreas</h2></div>
              <div className="flex bg-slate-200 p-1 rounded-2xl overflow-x-auto no-scrollbar gap-1 shadow-inner">
                   {Object.values(AuditArea).map(area => (<button key={area} type="button" onClick={() => setAuditDetails(prev => ({ ...prev, area }))} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${auditDetails.area === area ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-500'}`}>{area}</button>))}
              </div>
              <div className="space-y-4">
                 <QuestionCard 
                    label="1. ¿CUMPLE FEFO?" 
                    icon={Calendar} 
                    value={auditDetails.fefo?.value} 
                    onChange={(v: boolean) => updateAuditIndicator('fefo', 'value', v)} 
                    onComment={(c: string) => updateAuditIndicator('fefo', 'comment', c)}
                    comment={auditDetails.fefo?.comment}
                 />
                 <QuestionCard 
                    label="2. ¿CUMPLE LAYOUT?" 
                    icon={LayoutDashboard} 
                    value={auditDetails.initialLayout?.value} 
                    onChange={(v: boolean) => updateAuditIndicator('initialLayout', 'value', v)} 
                    onComment={(c: string) => updateAuditIndicator('initialLayout', 'comment', c)}
                    comment={auditDetails.initialLayout?.comment}
                    reasons={LAYOUT_FAIL_REASONS}
                    currentReason={auditDetails.initialLayout?.reason}
                    onReason={(r: string) => updateAuditIndicator('initialLayout', 'reason', r)}
                 />
                 <QuestionCard 
                    label="3. ¿DÓNDE SE GUARDA LA MERCADERÍA?" 
                    icon={Database} 
                    value={true} 
                    onChange={() => {}} 
                    onPhoto={(f: File) => handleAuditPhoto('vuseStorage', f)}
                    photo={auditDetails.vuseStorage?.photo}
                    onComment={(c: string) => updateAuditIndicator('vuseStorage', 'comment', c)}
                    comment={auditDetails.vuseStorage?.comment}
                 />
              </div>
            </section>

            {/* CAMPAÑAS ACTUALES */}
            <section className="space-y-4">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-2"><Sparkles size={18} className="text-[#002060]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 4: Campañas</h2></div>
                <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-3 py-1 rounded-full uppercase">3. Ejecución Actual</span>
              </div>

              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="bg-[#002060] p-4 text-white flex items-center justify-between">
                  <span className="text-[10px] font-black tracking-widest">LISTADO DE MATERIALES</span>
                  <HelpCircle size={16} className="opacity-50" />
                </div>
                <div className="divide-y divide-slate-50">
                  {campaigns.map((camp) => (
                    <div key={camp.name} className="p-4 space-y-4">
                      <div className="flex justify-between items-start gap-3">
                        <span className="text-[10px] font-black text-[#002060] uppercase leading-tight mt-1">{camp.name}</span>
                        <div className="flex bg-slate-100 p-0.5 rounded-xl shrink-0">
                           <button type="button" onClick={() => updateCampaign(camp.name, { status: 'IMPLEMENTED', incidenceType: null })} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${camp.status === 'IMPLEMENTED' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>VISTO</button>
                           <button type="button" onClick={() => updateCampaign(camp.name, { status: 'INCIDENCE', implementationType: null })} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${camp.status === 'INCIDENCE' ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>FALLA</button>
                        </div>
                      </div>

                      {camp.status && (
                        <div className="grid grid-cols-2 gap-3 animate-in fade-in zoom-in-95">
                          <label className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed transition-all cursor-pointer ${camp.photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
                            {camp.photo ? <CheckCircle2 size={16} /> : <Camera size={16} />}
                            <span className="text-[8px] font-black uppercase mt-1">{camp.photo ? 'CAPTURA OK' : 'FOTO'}</span>
                            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCampaignPhoto(camp.name, e.target.files[0])} />
                          </label>
                          <input 
                            type="text" 
                            placeholder="Obs..." 
                            className="bg-slate-50 border-none rounded-2xl px-4 text-[10px] font-bold outline-none" 
                            value={camp.comment}
                            onChange={e => updateCampaign(camp.name, { comment: e.target.value })}
                          />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </section>

            {/* CONTEO STOCK */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Package size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 5: Conteo de Productos</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 flex flex-col gap-4">
                  <div className="flex bg-slate-200 p-1 rounded-2xl">
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VUSE)} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VUSE ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>VUSE</button>
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VELO)} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VELO ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>VELO</button>
                  </div>
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input type="text" placeholder="Filtrar por SKU..." className="w-full pl-9 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold shadow-inner" value={stockSearch} onChange={e => setStockSearch(e.target.value)} />
                  </div>
                </div>
                <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto no-scrollbar">
                  {filteredStockSkus.map(sku => {
                    const data = stockCounts.find(i => i.skuName === sku);
                    return (
                      <div key={sku} className={`px-4 py-3 flex flex-col gap-2 ${data && data.quantity > 0 ? 'bg-blue-50/20' : ''}`}>
                        <div className="flex justify-between items-start gap-4">
                          <span className="text-[10px] font-bold text-slate-700 leading-tight flex-1">{sku}</span>
                          <div className="flex items-center gap-2">
                             <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">STOCK:</span>
                             <input type="number" placeholder="0" className="w-16 text-center py-1.5 bg-white border border-slate-200 rounded-xl text-[11px] font-black outline-none focus:ring-2 focus:ring-blue-500" value={data?.quantity || ''} onChange={e => updateStockItem(sku, 'quantity', parseInt(e.target.value) || 0)} />
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </section>

            {/* AUDITORÍA FINAL */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><CheckCircle2 size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso Final: Cierre</h2></div>
              <div className="space-y-4">
                <QuestionCard 
                  label="¿Se dejaron limpios y ordenados los activos?"
                  icon={CheckCircle2}
                  value={finalAudit.assetsCleaned}
                  onChange={(v: boolean) => setFinalAudit(prev => ({ ...prev, assetsCleaned: v }))}
                  onComment={(c: string) => setFinalAudit(prev => ({ ...prev, comment: c }))}
                  comment={finalAudit.comment}
                  isRequired
                />

                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-xl"><ImageIcon size={18} /></div>
                    <span className="text-[11px] font-black text-slate-700 uppercase">FOTO PANORÁMICA FINAL DEL COUNTER *</span>
                  </div>
                  <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-2xl border-2 border-dashed transition-all cursor-pointer ${finalAudit.panoramicPhoto ? 'bg-emerald-50 border-emerald-300' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
                    {finalAudit.panoramicPhoto ? <img src={finalAudit.panoramicPhoto} className="w-full h-full object-cover rounded-2xl" /> : (
                      <div className="flex flex-col items-center gap-2">
                        <Camera size={28} className="text-slate-300" />
                        <span className="text-[9px] font-black uppercase tracking-widest">CAPTURA FINAL</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleFinalPhoto(e.target.files[0])} />
                  </label>
                </div>
              </div>
            </section>
          </>
        )}

        {/* BOTÓN DE ENVÍO */}
        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-slate-100 z-50">
          <button type="submit" disabled={isSubmitting} className="w-full bg-[#1e3a5f] text-white py-4.5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />} FINALIZAR REPORTE
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

import React, { useState, useMemo } from 'react';
// Added missing LayoutDashboard and Database icons to the imports
import { Camera, Plus, Trash2, Save, MapPin, Sparkles, Loader2, Image as ImageIcon, Package, Ban, Store, CheckCircle2, XCircle, ChevronDown, User, ArrowLeft, Search, Check, AlertCircle, X, ChevronRight, Hash, Filter, Info, ShieldAlert, Lightbulb, ClipboardList, Wrench, Calendar, ListTodo, Camera as CameraIcon, HelpCircle, LayoutDashboard, Database } from 'lucide-react';
import { 
  MaterialType, Condition, MaterialItem, POSAudit, StoreStatus, OOSItem, SKUCategory, SKU_LISTS, 
  OOS_REASONS, User as UserType, AssignedStore, CURRENT_CAMPAIGNS, CampaignRecord, 
  NoMaterialReason, AuditAccess, DENIAL_REASONS, AuditArea, LAYOUT_FAIL_REASONS, POSAuditDetails,
  LAYOUT_FIX_REASONS, INCIDENCE_REASONS, ACTIVE_FIX_REASONS, AuditIndicator,
  MaintenanceStatus, MAINTENANCE_INCIDENTS, MAINTENANCE_ASSETS, MaintenanceRecord, MaintenanceSection,
  StockCountItem, FinalAudit
} from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName, setStoreName] = useState(prefillStore?.name || '');
  const [address, setAddress] = useState(prefillStore?.address || '');

  // Apertura y Acceso
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);
  const [auditAccess, setAuditAccess] = useState<AuditAccess | null>(null);
  const [denialReason, setDenialReason] = useState<string>('');
  const [panoramicBefore, setPanoramicBefore] = useState<string | null>(null);

  // Indicadores PDV
  const [auditDetails, setAuditDetails] = useState<POSAuditDetails>({
    area: AuditArea.CIGARRERA,
    fefo: { value: null, comment: '' },
    initialLayout: { value: null, comment: '' },
    finalLayout: { value: null, comment: '' },
    contamination: { value: null, comment: '' },
    finalContamination: { value: null, comment: '' },
    vuseStorage: { value: null, comment: '' },
    incidence: { value: null, comment: '' },
    activeStatus: { value: null, comment: '' },
    exhibitionStatus: { value: null, comment: '' }
  });

  // Mantenimiento
  const [maintenance, setMaintenance] = useState<MaintenanceSection>({
    records: MAINTENANCE_ASSETS.map(asset => ({ assetName: asset, status: null })),
    generalComment: '',
  });

  // Stock y Vencimientos
  const [stockCounts, setStockCounts] = useState<StockCountItem[]>([]);
  const [stockSearch, setStockSearch] = useState('');
  const [activeStockCategory, setActiveStockCategory] = useState<SKUCategory.VUSE | SKUCategory.VELO>(SKUCategory.VUSE);

  // Campañas Actuales
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  // Lógica de visibilidad
  const showAccessQuestion = storeStatus === StoreStatus.OPEN;
  const showAuditFlow = storeStatus === StoreStatus.OPEN && auditAccess === AuditAccess.ALLOWED;

  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    if (!stockSearch) return list;
    return list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase()));
  }, [activeStockCategory, stockSearch]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => {
      const currentIndicator = (prev[key] as AuditIndicator) || { value: null, comment: '' };
      return { ...prev, [key]: { ...currentIndicator, [field]: value } };
    });
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateMaintenanceRecord = (assetName: string, field: keyof MaintenanceRecord, value: any) => {
    setMaintenance(prev => ({
      ...prev,
      records: prev.records.map(r => r.assetName === assetName ? { ...r, [field]: value } : r)
    }));
  };

  const updateStockItem = (skuName: string, field: keyof StockCountItem, value: any) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      if (existing) {
        return prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i);
      } else {
        return [...prev, { skuName, quantity: field === 'quantity' ? value : 0, expirationDate: field === 'expirationDate' ? value : '' }];
      }
    });
  };

  const updateCampaign = (name: string, updates: Partial<CampaignRecord>) => {
    setCampaigns(prev => prev.map(c => c.name === name ? { ...c, ...updates } : c));
  };

  const handleCampaignPhoto = (name: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCampaign(name, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('Es obligatorio tomar una foto de la fachada.'); return; }
    if (showAccessQuestion && !auditAccess) { alert('Por favor responda si se permitió tomar información.'); return; }
    if (showAuditFlow && !panoramicBefore) { alert('Es obligatoria la foto panorámica antes de la visita.'); return; }
    if (showAuditFlow && finalAudit.assetsCleaned === null) { alert('Por favor responda si se dejaron limpios los activos.'); return; }
    if (showAuditFlow && !finalAudit.panoramicPhoto) { alert('Es obligatoria la foto panorámica final.'); return; }

    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address, auditorId: user.id, auditorName: user.name,
        storeStatus, statusPhotoBase64: statusPhoto || undefined, panoramicPhotoBefore: panoramicBefore || undefined,
        auditAccess: showAccessQuestion ? (auditAccess || undefined) : undefined,
        denialReason: (showAccessQuestion && auditAccess === AuditAccess.DENIED) ? denialReason : undefined,
        details: showAuditFlow ? auditDetails : undefined,
        maintenance: showAuditFlow ? maintenance : undefined,
        stockCounts: showAuditFlow ? stockCounts : undefined,
        campaigns: showAuditFlow ? campaigns : undefined,
        finalAudit: showAuditFlow ? finalAudit : undefined,
        items: [], oosItems: [], checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  // Componente de Pregunta Amigable Estándar
  const QuestionCard = ({ label, icon: Icon, value, onChange, photo, onPhoto, comment, onComment, reasons, currentReason, onReason, isRequired }: any) => (
    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4 animate-in fade-in slide-in-from-top-2">
      <div className="flex justify-between items-start gap-3">
        <div className="flex gap-3">
          <div className={`p-2 rounded-xl shrink-0 ${value === null ? 'bg-slate-50 text-slate-400' : 'bg-blue-50 text-blue-600'}`}>
            <Icon size={18} />
          </div>
          <span className="text-[11px] font-black text-slate-700 uppercase leading-tight mt-1">{label} {isRequired && <span className="text-rose-500">*</span>}</span>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl">
          <button type="button" onClick={() => onChange(true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === true ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>SI</button>
          <button type="button" onClick={() => onChange(false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === false ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>NO</button>
        </div>
      </div>

      {reasons && value === false && (
        <div className="flex flex-wrap gap-2 py-1">
          {reasons.map((r: string) => (
            <button key={r} type="button" onClick={() => onReason(r)} className={`px-3 py-1.5 rounded-xl text-[9px] font-bold border transition-all ${currentReason === r ? 'bg-[#002060] border-[#002060] text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>
          ))}
        </div>
      )}

      {onComment && (
        <input 
          type="text" 
          placeholder="Añadir comentario (opcional)..." 
          className="w-full bg-slate-50 border-none rounded-2xl py-2.5 px-4 text-xs font-medium focus:ring-2 focus:ring-blue-100 transition-all" 
          value={comment || ''} 
          onChange={e => onComment(e.target.value)} 
        />
      )}

      {onPhoto && value !== null && (
        <label className={`flex items-center justify-center gap-2 py-3 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-yellow-50 border-yellow-200 text-amber-600'}`}>
          {photo ? <CheckCircle2 size={18} /> : <Camera size={18} />}
          <span className="text-[10px] font-black uppercase tracking-widest">{photo ? 'FOTO CAPTURADA' : 'TOMAR FOTO'}</span>
          <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && onPhoto(e.target.files[0])} />
        </label>
      )}
    </div>
  );

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1"><ArrowLeft size={24} /></button>
          <div>
            <h1 className="text-lg font-black uppercase truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1">Auditoría Trade Marketing</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* SECCIÓN 1: APERTURA */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1"><Store size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 1: Estado del Local</h2></div>
          <div className="bg-white p-5 rounded-3xl border-2 border-slate-100 shadow-sm space-y-5">
            <label className="relative block aspect-video w-full rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden cursor-pointer">
              {statusPhoto ? <img src={statusPhoto} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-slate-300"><Camera size={32} /><span className="text-[10px] font-black uppercase tracking-widest">Foto de la Fachada *</span></div>}
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
            </label>
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center py-4 rounded-2xl border-2 font-black uppercase text-[11px] tracking-widest transition-all ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-inner shadow-emerald-200' : 'bg-white border-slate-100 text-slate-400'}`}>ABIERTO</button>
              <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center py-4 rounded-2xl border-2 font-black uppercase text-[11px] tracking-widest transition-all ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-inner shadow-rose-200' : 'bg-white border-slate-100 text-slate-400'}`}>CERRADO</button>
            </div>
          </div>

          {/* PREGUNTA DE ACCESO (REINCORPORADA) */}
          {showAccessQuestion && (
            <QuestionCard 
              label="¿Permitió tomar información / realizar auditoría?"
              icon={ShieldAlert}
              value={auditAccess === AuditAccess.ALLOWED ? true : auditAccess === AuditAccess.DENIED ? false : null}
              onChange={(val: boolean) => setAuditAccess(val ? AuditAccess.ALLOWED : AuditAccess.DENIED)}
              reasons={DENIAL_REASONS}
              currentReason={denialReason}
              onReason={setDenialReason}
              isRequired
            />
          )}

          {/* FOTO PANORÁMICA PREVIA (SOLO SI PERMITIÓ) */}
          {showAuditFlow && (
            <div className="space-y-4 animate-in zoom-in-95">
              <div className="flex items-center gap-2 px-1"><ImageIcon size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 2: Registro Inicial</h2></div>
              <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-3xl border-2 border-dashed transition-all cursor-pointer shadow-sm ${panoramicBefore ? 'bg-blue-50 border-blue-300' : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'}`}>
                {panoramicBefore ? (
                  <img src={panoramicBefore} className="w-full h-full object-cover rounded-3xl" />
                ) : (
                  <div className="flex flex-col items-center gap-2">
                    <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center"><Camera size={24} className="text-slate-400" /></div>
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">Foto Panorámica Previa *</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handlePanoramicBefore(e.target.files[0])} />
              </label>
            </div>
          )}
        </section>

        {/* FLUJO PRINCIPAL DE AUDITORÍA */}
        {showAuditFlow && (
          <>
            {/* Áreas e Indicadores */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ListTodo size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 3: Checklist de Áreas</h2></div>
              <div className="flex bg-slate-200 p-1 rounded-2xl overflow-x-auto no-scrollbar gap-1 shadow-inner">
                   {Object.values(AuditArea).map(area => (<button key={area} type="button" onClick={() => setAuditDetails(prev => ({ ...prev, area }))} className={`px-5 py-2.5 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${auditDetails.area === area ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-500'}`}>{area}</button>))}
              </div>
              <div className="space-y-4">
                 <QuestionCard 
                    label="1. ¿CUMPLE FEFO?" 
                    icon={Calendar} 
                    value={auditDetails.fefo?.value} 
                    onChange={(v: boolean) => updateAuditIndicator('fefo', 'value', v)} 
                    onComment={(c: string) => updateAuditIndicator('fefo', 'comment', c)}
                    comment={auditDetails.fefo?.comment}
                 />
                 <QuestionCard 
                    label="2. ¿CUMPLE LAYOUT?" 
                    icon={LayoutDashboard} 
                    value={auditDetails.initialLayout?.value} 
                    onChange={(v: boolean) => updateAuditIndicator('initialLayout', 'value', v)} 
                    onComment={(c: string) => updateAuditIndicator('initialLayout', 'comment', c)}
                    comment={auditDetails.initialLayout?.comment}
                    reasons={LAYOUT_FAIL_REASONS}
                    currentReason={auditDetails.initialLayout?.reason}
                    onReason={(r: string) => updateAuditIndicator('initialLayout', 'reason', r)}
                 />
                 <QuestionCard 
                    label="3. ¿DÓNDE SE GUARDA LA MERCADERÍA?" 
                    icon={Database} 
                    value={true} 
                    onChange={() => {}} 
                    onPhoto={(f: File) => handleAuditPhoto('vuseStorage', f)}
                    photo={auditDetails.vuseStorage?.photo}
                    onComment={(c: string) => updateAuditIndicator('vuseStorage', 'comment', c)}
                    comment={auditDetails.vuseStorage?.comment}
                 />
              </div>
            </section>

            {/* CAMPAÑAS ACTUALES */}
            <section className="space-y-4">
              <div className="flex items-center justify-between px-1">
                <div className="flex items-center gap-2"><Sparkles size={18} className="text-[#002060]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 4: Campañas</h2></div>
                <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-3 py-1 rounded-full uppercase">3. Ejecución Actual</span>
              </div>

              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="bg-[#002060] p-4 text-white flex items-center justify-between">
                  <span className="text-[10px] font-black tracking-widest">LISTADO DE MATERIALES</span>
                  <HelpCircle size={16} className="opacity-50" />
                </div>
                <div className="divide-y divide-slate-50">
                  {campaigns.map((camp) => (
                    <div key={camp.name} className="p-4 space-y-4">
                      <div className="flex justify-between items-start gap-3">
                        <span className="text-[10px] font-black text-[#002060] uppercase leading-tight mt-1">{camp.name}</span>
                        <div className="flex bg-slate-100 p-0.5 rounded-xl shrink-0">
                           <button type="button" onClick={() => updateCampaign(camp.name, { status: 'IMPLEMENTED', incidenceType: null })} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${camp.status === 'IMPLEMENTED' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>VISTO</button>
                           <button type="button" onClick={() => updateCampaign(camp.name, { status: 'INCIDENCE', implementationType: null })} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${camp.status === 'INCIDENCE' ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>FALLA</button>
                        </div>
                      </div>

                      {camp.status && (
                        <div className="grid grid-cols-2 gap-3 animate-in fade-in zoom-in-95">
                          <label className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 border-dashed transition-all cursor-pointer ${camp.photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
                            {camp.photo ? <CheckCircle2 size={16} /> : <Camera size={16} />}
                            <span className="text-[8px] font-black uppercase mt-1">{camp.photo ? 'CAPTURA OK' : 'FOTO'}</span>
                            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCampaignPhoto(camp.name, e.target.files[0])} />
                          </label>
                          <input 
                            type="text" 
                            placeholder="Obs..." 
                            className="bg-slate-50 border-none rounded-2xl px-4 text-[10px] font-bold outline-none" 
                            value={camp.comment}
                            onChange={e => updateCampaign(camp.name, { comment: e.target.value })}
                          />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </section>

            {/* CONTEO STOCK */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Package size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 5: Conteo de Productos</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 flex flex-col gap-4">
                  <div className="flex bg-slate-200 p-1 rounded-2xl">
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VUSE)} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VUSE ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>VUSE</button>
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VELO)} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VELO ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>VELO</button>
                  </div>
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input type="text" placeholder="Filtrar por SKU..." className="w-full pl-9 pr-4 py-3 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold shadow-inner" value={stockSearch} onChange={e => setStockSearch(e.target.value)} />
                  </div>
                </div>
                <div className="divide-y divide-slate-50 max-h-[400px] overflow-y-auto no-scrollbar">
                  {filteredStockSkus.map(sku => {
                    const data = stockCounts.find(i => i.skuName === sku);
                    return (
                      <div key={sku} className={`px-4 py-3 flex flex-col gap-2 ${data && data.quantity > 0 ? 'bg-blue-50/20' : ''}`}>
                        <div className="flex justify-between items-start gap-4">
                          <span className="text-[10px] font-bold text-slate-700 leading-tight flex-1">{sku}</span>
                          <div className="flex items-center gap-2">
                             <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">STOCK:</span>
                             <input type="number" placeholder="0" className="w-16 text-center py-1.5 bg-white border border-slate-200 rounded-xl text-[11px] font-black outline-none focus:ring-2 focus:ring-blue-500" value={data?.quantity || ''} onChange={e => updateStockItem(sku, 'quantity', parseInt(e.target.value) || 0)} />
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </section>

            {/* AUDITORÍA FINAL */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><CheckCircle2 size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso Final: Cierre</h2></div>
              <div className="space-y-4">
                <QuestionCard 
                  label="¿Se dejaron limpios y ordenados los activos?"
                  icon={CheckCircle2}
                  value={finalAudit.assetsCleaned}
                  onChange={(v: boolean) => setFinalAudit(prev => ({ ...prev, assetsCleaned: v }))}
                  onComment={(c: string) => setFinalAudit(prev => ({ ...prev, comment: c }))}
                  comment={finalAudit.comment}
                  isRequired
                />

                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-xl"><ImageIcon size={18} /></div>
                    <span className="text-[11px] font-black text-slate-700 uppercase">FOTO PANORÁMICA FINAL DEL COUNTER *</span>
                  </div>
                  <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-2xl border-2 border-dashed transition-all cursor-pointer ${finalAudit.panoramicPhoto ? 'bg-emerald-50 border-emerald-300' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
                    {finalAudit.panoramicPhoto ? <img src={finalAudit.panoramicPhoto} className="w-full h-full object-cover rounded-2xl" /> : (
                      <div className="flex flex-col items-center gap-2">
                        <Camera size={28} className="text-slate-300" />
                        <span className="text-[9px] font-black uppercase tracking-widest">CAPTURA FINAL</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleFinalPhoto(e.target.files[0])} />
                  </label>
                </div>
              </div>
            </section>
          </>
        )}

        {/* BOTÓN DE ENVÍO */}
        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-slate-100 z-50">
          <button type="submit" disabled={isSubmitting} className="w-full bg-[#1e3a5f] text-white py-4.5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />} FINALIZAR REPORTE
          </button>
        </div>
      </form>
    </div>
  );
};

export default NewAuditForm;

import React, { useState, useMemo } from 'react';
import { 
  Camera, Save, ArrowLeft, Search, Check, Info, ShieldAlert, Store, 
  CheckCircle2, ImageIcon, Package, Sparkles, Loader2, Calendar, 
  ListTodo, LayoutDashboard, Database, HelpCircle 
} from 'lucide-react';
import { 
  POSAudit, StoreStatus, SKUCategory, SKU_LISTS, User as UserType, 
  AssignedStore, CURRENT_CAMPAIGNS, CampaignRecord, AuditAccess, 
  DENIAL_REASONS, AuditArea, LAYOUT_FAIL_REASONS, POSAuditDetails,
  INCIDENCE_REASONS, AuditIndicator, MaintenanceStatus, 
  MAINTENANCE_ASSETS, MaintenanceRecord, MaintenanceSection,
  StockCountItem, FinalAudit
} from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName] = useState(prefillStore?.name || '');

  // Estados de Apertura y Acceso
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);
  const [auditAccess, setAuditAccess] = useState<AuditAccess | null>(null);
  const [denialReason, setDenialReason] = useState<string>('');
  const [panoramicBefore, setPanoramicBefore] = useState<string | null>(null);

  // Indicadores PDV
  const [auditDetails, setAuditDetails] = useState<POSAuditDetails>({
    area: AuditArea.CIGARRERA,
    fefo: { value: null, comment: '' },
    initialLayout: { value: null, comment: '' },
    vuseStorage: { value: null, comment: '' },
    incidence: { value: null, comment: '' },
  } as any);

  // Mantenimiento
  const [maintenance, setMaintenance] = useState<MaintenanceSection>({
    records: MAINTENANCE_ASSETS.map(asset => ({ assetName: asset, status: null })),
    generalComment: '',
  });

  // Stock
  const [stockCounts, setStockCounts] = useState<StockCountItem[]>([]);
  const [stockSearch, setStockSearch] = useState('');
  const [activeStockCategory, setActiveStockCategory] = useState<SKUCategory.VUSE | SKUCategory.VELO>(SKUCategory.VUSE);

  // Campañas
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  // Lógica de visibilidad: si está abierta y respondió acceso (sea SI o NO), puede auditar
  const showAccessQuestion = storeStatus === StoreStatus.OPEN;
  const canProceedWithAudit = storeStatus === StoreStatus.OPEN && auditAccess !== null;

  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    if (!stockSearch) return list;
    return list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase()));
  }, [activeStockCategory, stockSearch]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => {
      const currentIndicator = (prev[key] as AuditIndicator) || { value: null, comment: '' };
      return { ...prev, [key]: { ...currentIndicator, [field]: value } };
    });
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateMaintenanceRecord = (assetName: string, field: keyof MaintenanceRecord, value: any) => {
    setMaintenance(prev => ({
      ...prev,
      records: prev.records.map(r => r.assetName === assetName ? { ...r, [field]: value } : r)
    }));
  };

  const updateStockItem = (skuName: string, field: keyof StockCountItem, value: any) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      if (existing) {
        return prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i);
      } else {
        return [...prev, { skuName, quantity: field === 'quantity' ? value : 0, expirationDate: field === 'expirationDate' ? value : '' }];
      }
    });
  };

  const updateCampaign = (name: string, updates: Partial<CampaignRecord>) => {
    setCampaigns(prev => prev.map(c => c.name === name ? { ...c, ...updates } : c));
  };

  const handleCampaignPhoto = (name: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCampaign(name, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('Es obligatorio tomar una foto de la fachada.'); return; }
    if (showAccessQuestion && !auditAccess) { alert('Por favor responda si se permitió tomar información.'); return; }
    if (canProceedWithAudit && !panoramicBefore) { alert('Es obligatoria la foto panorámica previa.'); return; }
    if (canProceedWithAudit && finalAudit.assetsCleaned === null) { alert('Por favor responda si se dejaron limpios los activos.'); return; }
    if (canProceedWithAudit && !finalAudit.panoramicPhoto) { alert('Es obligatoria la foto panorámica final.'); return; }

    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address: prefillStore?.address || '',
        auditorId: user.id, auditorName: user.name, storeStatus, statusPhotoBase64: statusPhoto || undefined,
        panoramicPhotoBefore: panoramicBefore || undefined, auditAccess: auditAccess || undefined,
        denialReason: auditAccess === AuditAccess.DENIED ? denialReason : undefined,
        details: canProceedWithAudit ? auditDetails : undefined,
        maintenance: canProceedWithAudit ? maintenance : undefined,
        stockCounts: canProceedWithAudit ? stockCounts : undefined,
        campaigns: canProceedWithAudit ? campaigns : undefined,
        finalAudit: canProceedWithAudit ? finalAudit : undefined,
        items: [], oosItems: [], checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  // Componente de Pregunta Estándar Uniforme
  const QuestionCard = ({ label, icon: Icon, value, onChange, photo, onPhoto, comment, onComment, reasons, currentReason, onReason, isRequired }: any) => (
    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4 animate-in fade-in slide-in-from-bottom-2">
      <div className="flex justify-between items-start gap-3">
        <div className="flex gap-3">
          <div className={`p-2 rounded-xl shrink-0 ${value === null ? 'bg-slate-50 text-slate-400' : 'bg-blue-50 text-blue-600'}`}>
            <Icon size={18} />
          </div>
          <span className="text-[11px] font-black text-slate-700 uppercase leading-tight mt-1">{label} {isRequired && <span className="text-rose-500">*</span>}</span>
        </div>
        <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner shrink-0">
          <button type="button" onClick={() => onChange(true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === true ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>SI</button>
          <button type="button" onClick={() => onChange(false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === false ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>NO</button>
        </div>
      </div>

      {reasons && value === false && (
        <div className="flex flex-wrap gap-2 pt-1">
          {reasons.map((r: string) => (
            <button key={r} type="button" onClick={() => onReason(r)} className={`px-3 py-1.5 rounded-xl text-[9px] font-bold border transition-all ${currentReason === r ? 'bg-[#1e3a5f] border-[#1e3a5f] text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>
          ))}
        </div>
      )}

      {onComment && (
        <input 
          type="text" 
          placeholder="Escribe un comentario..." 
          className="w-full bg-slate-50 border-none rounded-2xl py-2.5 px-4 text-xs font-medium focus:ring-2 focus:ring-blue-100 transition-all shadow-inner" 
          value={comment || ''} 
          onChange={e => onComment(e.target.value)} 
        />
      )}

      {onPhoto && value !== null && (
        <label className={`flex items-center justify-center gap-2 py-3.5 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-yellow-50 border-yellow-200 text-amber-600'}`}>
          {photo ? <CheckCircle2 size={18} /> : <Camera size={18} />}
          <span className="text-[10px] font-black uppercase tracking-widest">{photo ? 'FOTO CAPTURADA' : 'TOMAR FOTO'}</span>
          <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && onPhoto(e.target.files[0])} />
        </label>
      )}
    </div>
  );

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      {/* Header Fijo */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1 active:scale-90 transition-transform"><ArrowLeft size={24} /></button>
          <div>
            <h1 className="text-lg font-black uppercase truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1 tracking-widest">Auditoría Trade Marketing</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* PASO 1: ESTADO DEL LOCAL */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1"><Store size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 1: Apertura</h2></div>
          <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-5">
            <label className="relative block aspect-video w-full rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden cursor-pointer">
              {statusPhoto ? <img src={statusPhoto} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-2 text-slate-300"><Camera size={32} /><span className="text-[10px] font-black uppercase tracking-widest">Foto de la Fachada *</span></div>}
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
            </label>
            <div className="grid grid-cols-2 gap-3">
              <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`flex items-center justify-center py-4 rounded-2xl border-2 font-black uppercase text-[11px] tracking-widest transition-all ${storeStatus === StoreStatus.OPEN ? 'bg-emerald-50 border-emerald-500 text-emerald-700 shadow-inner' : 'bg-white border-slate-50 text-slate-300'}`}>ABIERTO</button>
              <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`flex items-center justify-center py-4 rounded-2xl border-2 font-black uppercase text-[11px] tracking-widest transition-all ${storeStatus === StoreStatus.CLOSED ? 'bg-rose-50 border-rose-500 text-rose-700 shadow-inner' : 'bg-white border-slate-50 text-slate-300'}`}>CERRADO</button>
            </div>
          </div>

          {showAccessQuestion && (
            <div className="space-y-4">
              <QuestionCard 
                label="¿Permitió tomar información / realizar auditoría?"
                icon={ShieldAlert}
                value={auditAccess === AuditAccess.ALLOWED ? true : auditAccess === AuditAccess.DENIED ? false : null}
                onChange={(val: boolean) => setAuditAccess(val ? AuditAccess.ALLOWED : AuditAccess.DENIED)}
                reasons={DENIAL_REASONS}
                currentReason={denialReason}
                onReason={setDenialReason}
                isRequired
              />

              {/* MENSAJE CUANDO NO PERMITE ACCESO */}
              {auditAccess === AuditAccess.DENIED && (
                <div className="mx-1 p-5 bg-amber-50 border border-amber-200 rounded-3xl flex gap-3 animate-in slide-in-from-left-4 duration-500">
                  <div className="shrink-0 w-10 h-10 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600">
                    <Info size={24} />
                  </div>
                  <p className="text-[11px] font-black text-amber-800 leading-relaxed uppercase">
                    Recuerda si no pudiste ingresar al counter, puedes trabajar por fuera del counter, ¡implementa materiales y limpia activos! Y completa el app.
                  </p>
                </div>
              )}
            </div>
          )}
        </section>

        {/* FLUJO DE AUDITORÍA (VISIBLE SI RESPONDIÓ ACCESO) */}
        {canProceedWithAudit && (
          <>
            {/* PASO 2: REGISTRO INICIAL */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ImageIcon size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 2: Registro Inicial</h2></div>
              <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-3xl border-2 border-dashed transition-all cursor-pointer shadow-sm ${panoramicBefore ? 'bg-blue-50 border-blue-300' : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'}`}>
                {panoramicBefore ? (
                  <img src={panoramicBefore} className="w-full h-full object-cover rounded-3xl" />
                ) : (
                  <div className="flex flex-col items-center gap-3">
                    <div className="w-14 h-14 bg-slate-50 rounded-full flex items-center justify-center text-slate-400 group-hover:bg-blue-100"><Camera size={28} /></div>
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">Foto Panorámica Previa *</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handlePanoramicBefore(e.target.files[0])} />
              </label>
            </section>

            {/* PASO 3: INDICADORES */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ListTodo size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 3: Áreas e Indicadores</h2></div>
              <div className="flex bg-slate-200 p-1.5 rounded-2xl overflow-x-auto no-scrollbar gap-1.5 shadow-inner">
                   {Object.values(AuditArea).map(area => (<button key={area} type="button" onClick={() => setAuditDetails(prev => ({ ...prev, area }))} className={`px-5 py-3 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${auditDetails.area === area ? 'bg-white text-[#1e3a5f] shadow-md' : 'text-slate-500'}`}>{area}</button>))}
              </div>
              <div className="space-y-4">
                 <QuestionCard 
                    label="1. ¿CUMPLE FEFO?" 
                    icon={Calendar} 
                    value={auditDetails.fefo?.value} 
                    onChange={(v: boolean) => updateAuditIndicator('fefo', 'value', v)} 
                    onComment={(c: string) => updateAuditIndicator('fefo', 'comment', c)}
                    comment={auditDetails.fefo?.comment}
                 />
                 <QuestionCard 
                    label="2. ¿CUMPLE LAYOUT?" 
                    icon={LayoutDashboard} 
                    value={auditDetails.initialLayout?.value} 
                    onChange={(v: boolean) => updateAuditIndicator('initialLayout', 'value', v)} 
                    onComment={(c: string) => updateAuditIndicator('initialLayout', 'comment', c)}
                    comment={auditDetails.initialLayout?.comment}
                    reasons={LAYOUT_FAIL_REASONS}
                    currentReason={auditDetails.initialLayout?.reason}
                    onReason={(r: string) => updateAuditIndicator('initialLayout', 'reason', r)}
                 />
                 <QuestionCard 
                    label="3. REGISTRO FOTO CIGARRERA" 
                    icon={Database} 
                    value={true} 
                    onChange={() => {}} 
                    onPhoto={(f: File) => handleAuditPhoto('vuseStorage', f)}
                    photo={auditDetails.vuseStorage?.photo}
                    onComment={(c: string) => updateAuditIndicator('vuseStorage', 'comment', c)}
                    comment={auditDetails.vuseStorage?.comment}
                 />
              </div>
            </section>

            {/* PASO 4: CAMPAÑAS */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Sparkles size={18} className="text-[#002060]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 4: Ejecución POP</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden divide-y divide-slate-50">
                  <div className="bg-[#002060] p-4 text-white flex justify-between items-center">
                    <span className="text-[10px] font-black uppercase tracking-widest">Materiales Actuales</span>
                    <HelpCircle size={16} className="opacity-40" />
                  </div>
                  {campaigns.map((camp) => (
                    <div key={camp.name} className="p-4 space-y-4">
                      <div className="flex justify-between items-start gap-4">
                        <span className="text-[10px] font-black text-[#002060] uppercase leading-tight mt-1">{camp.name}</span>
                        <div className="flex bg-slate-100 p-0.5 rounded-xl shrink-0">
                           <button type="button" onClick={() => updateCampaign(camp.name, { status: 'IMPLEMENTED', incidenceType: null })} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${camp.status === 'IMPLEMENTED' ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>VISTO</button>
                           <button type="button" onClick={() => updateCampaign(camp.name, { status: 'INCIDENCE', implementationType: null })} className={`px-3 py-1.5 rounded-lg text-[9px] font-black transition-all ${camp.status === 'INCIDENCE' ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>FALLA</button>
                        </div>
                      </div>
                      {camp.status && (
                        <div className="flex gap-3 animate-in fade-in zoom-in-95">
                          <label className={`flex flex-1 items-center justify-center gap-2 py-3 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${camp.photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-slate-50 border-slate-200 text-slate-400'}`}>
                            {camp.photo ? <CheckCircle2 size={16} /> : <Camera size={16} />}
                            <span className="text-[8px] font-black uppercase tracking-widest">{camp.photo ? 'OK' : 'FOTO'}</span>
                            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCampaignPhoto(camp.name, e.target.files[0])} />
                          </label>
                          <input type="text" placeholder="Obs..." className="flex-[2] bg-slate-50 border-none rounded-2xl px-4 text-[10px] font-bold outline-none" value={camp.comment} onChange={e => updateCampaign(camp.name, { comment: e.target.value })} />
                        </div>
                      )}
                    </div>
                  ))}
              </div>
            </section>

            {/* PASO 5: STOCK */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Package size={18} className="text-[#1e3a5f]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso 5: Inventario</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 space-y-4">
                  <div className="flex bg-slate-200 p-1.5 rounded-2xl shadow-inner">
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VUSE)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VUSE ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500'}`}>VUSE</button>
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VELO)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VELO ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500'}`}>VELO</button>
                  </div>
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" placeholder="Filtrar por SKU..." className="w-full pl-11 pr-4 py-4 bg-white border border-slate-100 rounded-2xl text-[11px] font-bold shadow-inner" value={stockSearch} onChange={e => setStockSearch(e.target.value)} />
                  </div>
                </div>
                <div className="divide-y divide-slate-50 max-h-[350px] overflow-y-auto no-scrollbar">
                  {filteredStockSkus.map(sku => {
                    const data = stockCounts.find(i => i.skuName === sku);
                    return (
                      <div key={sku} className={`px-4 py-4 flex items-center justify-between gap-4 ${data && data.quantity > 0 ? 'bg-blue-50/20' : ''}`}>
                          <span className="text-[10px] font-bold text-slate-700 leading-tight flex-1">{sku}</span>
                          <div className="flex items-center gap-3">
                             <span className="text-[9px] font-black text-slate-400 uppercase">CANT:</span>
                             <input type="number" placeholder="0" className="w-16 text-center py-2 bg-white border border-slate-200 rounded-xl text-[11px] font-black focus:ring-2 focus:ring-blue-500 outline-none" value={data?.quantity || ''} onChange={e => updateStockItem(sku, 'quantity', parseInt(e.target.value) || 0)} />
                          </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </section>

            {/* PASO FINAL: CIERRE */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><CheckCircle2 size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Paso Final: Cierre</h2></div>
              <div className="space-y-4">
                <QuestionCard 
                  label="¿Se dejaron limpios y ordenados los activos?"
                  icon={CheckCircle2}
                  value={finalAudit.assetsCleaned}
                  onChange={(v: boolean) => setFinalAudit(prev => ({ ...prev, assetsCleaned: v }))}
                  onComment={(c: string) => setFinalAudit(prev => ({ ...prev, comment: c }))}
                  comment={finalAudit.comment}
                  isRequired
                />

                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-xl"><ImageIcon size={18} /></div>
                    <span className="text-[11px] font-black text-slate-700 uppercase">Foto Panorámica Final *</span>
                  </div>
                  <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-2xl border-2 border-dashed transition-all cursor-pointer ${finalAudit.panoramicPhoto ? 'bg-emerald-50 border-emerald-300' : 'bg-slate-50 border-slate-200 text-slate-400 hover:bg-slate-100'}`}>
                    {finalAudit.panoramicPhoto ? <img src={finalAudit.panoramicPhoto} className="w-full h-full object-cover rounded-2xl" /> : (
                      <div className="flex flex-col items-center gap-2">
                        <Camera size={28} className="text-slate-300" />
                        <span className="text-[9px] font-black uppercase tracking-widest">Capturar Foto de Cierre</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleFinalPhoto(e.target.files[0])} />
                  </label>
                </div>
              </div>
            </section>
          </>
        )}

        {/* BOTÓN FLOTANTE DE FINALIZAR */}
        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-slate-100 z-50">
          <button type="submit" disabled={isSubmitting} className="w-full bg-[#1e3a5f] text-white py-4.5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all">
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />} 
            Finalizar Reporte
          </button>
        </div>
      </form>
    </div>
  );
};

