  POSAudit, StoreStatus, SKUCategory, SKU_LISTS, User as UserType, 
  AssignedStore, CURRENT_CAMPAIGNS, CampaignRecord, AuditAccess, 
  DENIAL_REASONS, AuditArea, LAYOUT_FAIL_REASONS, POSAuditDetails,
  AuditIndicator, StockCountItem, FinalAudit, CLOSURE_REASONS,
  LAYOUT_FIX_REASONS, INCIDENCE_REASONS, ACTIVE_FIX_REASONS, EXHIBITION_REASONS
} from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName] = useState(prefillStore?.name || '');

  // Estados de Apertura
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [personnelName, setPersonnelName] = useState('');
  const [openingComment, setOpeningComment] = useState('');
  const [closureReason, setClosureReason] = useState('');
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);

  // Estados de Acceso al Counter
  const [auditAccess, setAuditAccess] = useState<AuditAccess | null>(null);
  const [denialReason, setDenialReason] = useState<string>('');
  const [panoramicBefore, setPanoramicBefore] = useState<string | null>(null);

  // Indicadores PDV (Estado centralizado)
  const [auditDetails, setAuditDetails] = useState<POSAuditDetails>({
    area: AuditArea.CIGARRERA,
    fefo: { value: null, comment: '' },
    initialLayout: { value: null, comment: '' },
    finalLayout: { value: null, comment: '' },
    vuseStorage: { value: null, comment: '' },
    incidence: { value: null, comment: '' },
    activeStatus: { value: null, comment: '' },
    contamination: { value: null, comment: '' },
    finalContamination: { value: null, comment: '' },
    exhibitionStatus: { value: null, comment: '' }
  });

  // Stock
  const [stockCounts, setStockCounts] = useState<StockCountItem[]>([]);
  const [stockSearch, setStockSearch] = useState('');
  const [activeStockCategory, setActiveStockCategory] = useState<SKUCategory.VUSE | SKUCategory.VELO>(SKUCategory.VUSE);

  // Campañas
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  // Lógica de visibilidad
  const isStoreOpen = storeStatus === StoreStatus.OPEN;
  const showAuditFlow = isStoreOpen && auditAccess !== null;

  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    if (!stockSearch) return list;
    return list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase()));
  }, [activeStockCategory, stockSearch]);

  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => {
      const currentIndicator = (prev[key] as AuditIndicator) || { value: null, comment: '' };
      return { ...prev, [key]: { ...currentIndicator, [field]: value } };
    });
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateStockItem = (skuName: string, value: number) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      if (existing) {
        return prev.map(i => i.skuName === skuName ? { ...i, quantity: value } : i);
      } else {
        return [...prev, { skuName, quantity: value }];
      }
    });
  };

  const updateCampaign = (name: string, updates: Partial<CampaignRecord>) => {
    setCampaigns(prev => prev.map(c => c.name === name ? { ...c, ...updates } : c));
  };

  const handleCampaignPhoto = (name: string, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCampaign(name, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('La FOTO de fachada es obligatoria.'); return; }
    if (isStoreOpen) {
      if (!personnelName) { alert('Indique el nombre del personal.'); return; }
      if (!openingComment) { alert('El comentario de apertura es obligatorio.'); return; }
      if (auditAccess === null) { alert('Debe indicar si se permitió tomar información.'); return; }
      if (!panoramicBefore) { alert('La foto panorámica previa es obligatoria.'); return; }
    } else {
      if (!closureReason) { alert('Seleccione un motivo de cierre.'); return; }
    }

    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address: prefillStore?.address || '',
        auditorId: user.id, auditorName: user.name, storeStatus, statusPhotoBase64: statusPhoto || undefined,
        personnelName: isStoreOpen ? personnelName : undefined,
        openingComment: isStoreOpen ? openingComment : undefined,
        closureReason: !isStoreOpen ? closureReason : undefined,
        panoramicPhotoBefore: panoramicBefore || undefined, auditAccess: auditAccess || undefined,
        denialReason: auditAccess === AuditAccess.DENIED ? denialReason : undefined,
        details: showAuditFlow ? auditDetails : undefined,
        stockCounts: showAuditFlow ? stockCounts : undefined,
        campaigns: showAuditFlow ? campaigns : undefined,
        finalAudit: showAuditFlow ? finalAudit : undefined,
        items: [], oosItems: [], checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  // Componente de Pregunta Estándar
  const QuestionCard = ({ 
    label, 
    icon: Icon, 
    value, 
    onChange, 
    photo, 
    onPhoto, 
    comment, 
    onComment, 
    reasons, 
    currentReason, 
    onReason, 
    isRequired,
    options 
  }: any) => (
    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4 animate-in fade-in slide-in-from-bottom-2">
      <div className="flex justify-between items-start gap-3">
        <div className="flex gap-3">
          <div className={`p-2 rounded-xl shrink-0 ${value === null ? 'bg-slate-50 text-slate-400' : 'bg-blue-50 text-blue-600'}`}>
            <Icon size={18} />
          </div>
          <span className="text-[11px] font-black text-slate-700 uppercase leading-tight mt-1">{label} {isRequired && <span className="text-rose-500">*</span>}</span>
        </div>

        {!options && (
          <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner shrink-0">
            <button type="button" onClick={() => onChange(true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === true ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>SI</button>
            <button type="button" onClick={() => onChange(false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === false ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>NO</button>
          </div>
        )}
      </div>

      {options && (
        <div className="grid gap-2">
           {options.map((opt: string) => (
             <button key={opt} type="button" onClick={() => onChange(opt)} className={`w-full text-left px-4 py-3 rounded-2xl text-[10px] font-black border transition-all ${value === opt ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>
               {opt}
             </button>
           ))}
        </div>
      )}

      {reasons && value === false && (
        <div className="flex flex-wrap gap-2 pt-1">
          {reasons.map((r: string) => (
            <button key={r} type="button" onClick={() => onReason(r)} className={`px-3 py-1.5 rounded-xl text-[9px] font-bold border transition-all ${currentReason === r ? 'bg-[#1e3a5f] border-[#1e3a5f] text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>
          ))}
        </div>
      )}

      <div className="space-y-3">
        {onComment && (
          <div className="relative">
            <MessageSquare size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input 
              type="text" 
              placeholder="COMENTARIO..." 
              className="w-full bg-slate-50 border-none rounded-2xl py-2.5 pl-9 pr-4 text-[10px] font-black focus:ring-2 focus:ring-blue-100 transition-all shadow-inner uppercase" 
              value={comment || ''} 
              onChange={e => onComment(e.target.value)} 
            />
          </div>
        )}

        {onPhoto && value !== null && (
          <label className={`flex items-center justify-center gap-2 py-3.5 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-yellow-400/20 border-yellow-400 text-amber-700'}`}>
            {photo ? <CheckCircle2 size={18} /> : <Camera size={18} />}
            <span className="text-[10px] font-black uppercase tracking-widest">{photo ? 'FOTO CAPTURADA' : 'FOTO'}</span>
            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && onPhoto(e.target.files[0])} />
          </label>
        )}
      </div>
    </div>
  );

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      {/* Header Fijo */}
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4">
          <button type="button" onClick={onCancel} className="p-1 active:scale-90 transition-transform"><ArrowLeft size={24} /></button>
          <div>
            <h1 className="text-lg font-black uppercase truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1>
            <p className="text-[10px] text-blue-300 font-bold uppercase mt-1 tracking-widest">Auditoría Trade Marketing</p>
          </div>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* PASO 1: APERTURA */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1"><Store size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">1. Apertura</h2></div>

          <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-6">
            <div className="flex justify-between items-center bg-[#002060] p-4 rounded-2xl text-white">
               <div className="flex items-center gap-3">
                 <span className="text-lg font-black italic">1</span>
                 <span className="text-[11px] font-black uppercase tracking-widest">LOCAL SE ENCUENTRA ABIERTO</span>
               </div>
               <div className="flex bg-white/10 p-1 rounded-xl border border-white/20">
                 <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`px-5 py-2 rounded-lg text-[10px] font-black transition-all ${isStoreOpen ? 'bg-white text-[#002060]' : 'text-white/60'}`}>SI</button>
                 <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`px-5 py-2 rounded-lg text-[10px] font-black transition-all ${!isStoreOpen ? 'bg-white text-rose-600' : 'text-white/60'}`}>NO</button>
               </div>
            </div>

            {isStoreOpen ? (
              <div className="space-y-4 animate-in slide-in-from-top-2">
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">INDICAR NOMBRE PERSONAL QUE ATENDIÓ *</label>
                   <div className="relative">
                     <User size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                     <input type="text" placeholder="..." className="w-full pl-11 pr-4 py-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner uppercase" value={personnelName} onChange={e => setPersonnelName(e.target.value)} />
                   </div>
                 </div>
                 <div className="space-y-2">
                   <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">COMENTARIO OBLIGATORIO *</label>
                   <div className="relative">
                     <MessageSquare size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                     <input type="text" placeholder="..." className="w-full pl-11 pr-4 py-4 bg-slate-50 border-none rounded-2xl text-xs font-black shadow-inner uppercase" value={openingComment} onChange={e => setOpeningComment(e.target.value)} />
                   </div>
                 </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-top-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">MOTIVOS DE CIERRE *</label>
                <div className="grid gap-2">
                  {CLOSURE_REASONS.map(reason => (
                    <button key={reason} type="button" onClick={() => setClosureReason(reason)} className={`w-full text-left p-4 rounded-2xl text-[10px] font-black border transition-all ${closureReason === reason ? 'bg-rose-600 border-rose-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>
                      {reason}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div className="space-y-3">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">FOTO OBLIGATORIA FACHADA *</label>
              <label className={`relative block aspect-video w-full rounded-2xl border-2 border-dashed overflow-hidden cursor-pointer transition-all ${statusPhoto ? 'bg-emerald-50 border-emerald-300' : 'bg-yellow-400/20 border-yellow-400'}`}>
                {statusPhoto ? <img src={statusPhoto} className="w-full h-full object-cover" /> : (
                  <div className="w-full h-full flex flex-col items-center justify-center gap-2">
                    <Camera size={32} className="text-yellow-600" />
                    <span className="text-[10px] font-black text-red-600 uppercase tracking-widest">FOTO OBLIGATORIA</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
              </label>
            </div>
          </div>

          {isStoreOpen && (
            <div className="space-y-4">
              <QuestionCard 
                label="¿Permitió realizar auditoría en counter?"
                icon={ShieldAlert}
                value={auditAccess === AuditAccess.ALLOWED ? true : auditAccess === AuditAccess.DENIED ? false : null}
                onChange={(val: boolean) => setAuditAccess(val ? AuditAccess.ALLOWED : AuditAccess.DENIED)}
                reasons={DENIAL_REASONS}
                currentReason={denialReason}
                onReason={setDenialReason}
                isRequired
              />

              {auditAccess === AuditAccess.DENIED && (
                <div className="p-5 bg-amber-50 border border-amber-200 rounded-3xl flex gap-3 animate-in slide-in-from-left-4">
                  <div className="shrink-0 w-10 h-10 bg-amber-100 rounded-2xl flex items-center justify-center text-amber-600">
                    <Info size={24} />
                  </div>
                  <p className="text-[11px] font-black text-amber-800 leading-relaxed uppercase italic">
                    Recuerda si no pudiste ingresar al counter, puedes trabajar por fuera del counter, ¡implementa materiales y limpia activos! Y completa el app.
                  </p>
                </div>
              )}
            </div>
          )}
        </section>

        {/* PASO 2: REGISTRO INICIAL (AUDITORÍA) */}
        {showAuditFlow && (
          <>
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ImageIcon size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">2. Registro Inicial</h2></div>
              <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-3xl border-2 border-dashed transition-all cursor-pointer shadow-sm ${panoramicBefore ? 'bg-blue-50 border-blue-300' : 'bg-white border-slate-200 text-slate-400 hover:bg-slate-50'}`}>
                {panoramicBefore ? (
                  <img src={panoramicBefore} className="w-full h-full object-cover rounded-3xl" />
                ) : (
                  <div className="flex flex-col items-center gap-3">
                    <div className="w-14 h-14 bg-slate-50 rounded-full flex items-center justify-center text-slate-400"><Camera size={28} /></div>
                    <span className="text-[10px] font-black uppercase tracking-[0.2em]">FOTO PANORÁMICA PREVIA *</span>
                  </div>
                )}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handlePanoramicBefore(e.target.files[0])} />
              </label>
            </section>

            {/* PASO 3: INDICADORES */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ListTodo size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">3. Indicadores</h2></div>

              <div className="flex bg-slate-200 p-1.5 rounded-2xl overflow-x-auto no-scrollbar gap-1.5 shadow-inner">
                   {Object.values(AuditArea).map(area => (<button key={area} type="button" onClick={() => setAuditDetails(prev => ({ ...prev, area }))} className={`px-5 py-3 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${auditDetails.area === area ? 'bg-[#1e3a5f] text-white shadow-md' : 'text-slate-500'}`}>{area}</button>))}
              </div>

              <div className="space-y-4">
                 {auditDetails.area === AuditArea.CIGARRERA && (
                   <>
                     <QuestionCard 
                        label="1. ¿CUMPLE FEFO?" icon={Calendar} 
                        value={auditDetails.fefo?.value} onChange={(v: boolean) => updateAuditIndicator('fefo', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('fefo', 'comment', c)} comment={auditDetails.fefo?.comment}
                        onPhoto={(f: File) => handleAuditPhoto('fefo', f)} photo={auditDetails.fefo?.photo}
                     />
                     <QuestionCard 
                        label="2. ¿CUMPLE LAYOUT? (COMO SE ENCONTRÓ)" icon={LayoutDashboard} 
                        value={auditDetails.initialLayout?.value} onChange={(v: boolean) => updateAuditIndicator('initialLayout', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('initialLayout', 'comment', c)} comment={auditDetails.initialLayout?.comment}
                        reasons={LAYOUT_FAIL_REASONS} currentReason={auditDetails.initialLayout?.reason} onReason={(r: string) => updateAuditIndicator('initialLayout', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('initialLayout', f)} photo={auditDetails.initialLayout?.photo}
                     />
                     <QuestionCard 
                        label="3. ¿SE DEJÓ OK EL LAYOUT?" icon={CheckCircle2} 
                        value={auditDetails.finalLayout?.value} onChange={(v: boolean) => updateAuditIndicator('finalLayout', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('finalLayout', 'comment', c)} comment={auditDetails.finalLayout?.comment}
                        reasons={LAYOUT_FIX_REASONS} currentReason={auditDetails.finalLayout?.reason} onReason={(r: string) => updateAuditIndicator('finalLayout', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('finalLayout', f)} photo={auditDetails.finalLayout?.photo}
                     />
                     <QuestionCard 
                        label="4. SI NO TIENE ACTIVO VUSE, ¿DÓNDE SE GUARDA LA MERCADERÍA?" icon={Database} 
                        value={true} onChange={() => {}} 
                        onComment={(c: string) => updateAuditIndicator('vuseStorage', 'comment', c)} comment={auditDetails.vuseStorage?.comment}
                        onPhoto={(f: File) => handleAuditPhoto('vuseStorage', f)} photo={auditDetails.vuseStorage?.photo}
                     />
                     <QuestionCard 
                        label="5. ¿PRESENTA ALGUNA INCIDENCIA?" icon={Info} 
                        value={auditDetails.incidence?.value} onChange={(v: boolean) => updateAuditIndicator('incidence', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('incidence', 'comment', c)} comment={auditDetails.incidence?.comment}
                        reasons={INCIDENCE_REASONS} currentReason={auditDetails.incidence?.reason} onReason={(r: string) => updateAuditIndicator('incidence', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('incidence', f)} photo={auditDetails.incidence?.photo}
                     />
                     <QuestionCard 
                        label="6. ¿SE DEJÓ OK EL ACTIVO?" icon={CheckCircle2} 
                        value={auditDetails.activeStatus?.value} onChange={(v: boolean) => updateAuditIndicator('activeStatus', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('activeStatus', 'comment', c)} comment={auditDetails.activeStatus?.comment}
                        reasons={ACTIVE_FIX_REASONS} currentReason={auditDetails.activeStatus?.reason} onReason={(r: string) => updateAuditIndicator('activeStatus', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('activeStatus', f)} photo={auditDetails.activeStatus?.photo}
                     />
                   </>
                 )}

                 {(auditDetails.area === AuditArea.CAJONERA || auditDetails.area === AuditArea.DISPENSER) && (
                   <>
                     <QuestionCard 
                        label="1. ¿CONTAMINADO?" icon={Ban} 
                        value={auditDetails.contamination?.value} onChange={(v: boolean) => updateAuditIndicator('contamination', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('contamination', 'comment', c)} comment={auditDetails.contamination?.comment}
                        onPhoto={(f: File) => handleAuditPhoto('contamination', f)} photo={auditDetails.contamination?.photo}
                     />
                     <QuestionCard 
                        label="2. ¿SE DEJÓ SIN CONTAMINACION?" icon={CheckCircle2} 
                        value={auditDetails.finalContamination?.value} onChange={(v: boolean) => updateAuditIndicator('finalContamination', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('finalContamination', 'comment', c)} comment={auditDetails.finalContamination?.comment}
                        reasons={ACTIVE_FIX_REASONS} currentReason={auditDetails.finalContamination?.reason} onReason={(r: string) => updateAuditIndicator('finalContamination', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('finalContamination', f)} photo={auditDetails.finalContamination?.photo}
                     />
                     {auditDetails.area === AuditArea.DISPENSER && (
                        <>
                          <QuestionCard 
                              label="3. ¿SE ENCUENTRA EXHIBIDO CORRECTAMENTE?" icon={LayoutDashboard} 
                              value={auditDetails.exhibitionStatus?.value} onChange={(v: string) => updateAuditIndicator('exhibitionStatus', 'value', v)} 
                              onComment={(c: string) => updateAuditIndicator('exhibitionStatus', 'comment', c)} comment={auditDetails.exhibitionStatus?.comment}
                              options={EXHIBITION_REASONS}
                              onPhoto={(f: File) => handleAuditPhoto('exhibitionStatus', f)} photo={auditDetails.exhibitionStatus?.photo}
                          />
                          <QuestionCard 
                              label="4. ¿PRESENTA ALGUNA INCIDENCIA?" icon={Info} 
                              value={auditDetails.incidence?.value} onChange={(v: boolean) => updateAuditIndicator('incidence', 'value', v)} 
                              onComment={(c: string) => updateAuditIndicator('incidence', 'comment', c)} comment={auditDetails.incidence?.comment}
                              reasons={INCIDENCE_REASONS} currentReason={auditDetails.incidence?.reason} onReason={(r: string) => updateAuditIndicator('incidence', 'reason', r)}
                              onPhoto={(f: File) => handleAuditPhoto('incidence', f)} photo={auditDetails.incidence?.photo}
                          />
                          <QuestionCard 
                              label="5. ¿SE DEJÓ OK EL ACTIVO?" icon={CheckCircle2} 
                              value={auditDetails.activeStatus?.value} onChange={(v: boolean) => updateAuditIndicator('activeStatus', 'value', v)} 
                              onComment={(c: string) => updateAuditIndicator('activeStatus', 'comment', c)} comment={auditDetails.activeStatus?.comment}
                              reasons={ACTIVE_FIX_REASONS} currentReason={auditDetails.activeStatus?.reason} onReason={(r: string) => updateAuditIndicator('activeStatus', 'reason', r)}
                              onPhoto={(f: File) => handleAuditPhoto('activeStatus', f)} photo={auditDetails.activeStatus?.photo}
                          />
                        </>
                     )}
                   </>
                 )}

                 {auditDetails.area === AuditArea.GLORIFICADOR && (
                   <>
                     <QuestionCard 
                        label="1. ¿SE ENCUENTRA EXHIBIDO CORRECTAMENTE?" icon={LayoutDashboard} 
                        value={auditDetails.exhibitionStatus?.value} onChange={(v: string) => updateAuditIndicator('exhibitionStatus', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('exhibitionStatus', 'comment', c)} comment={auditDetails.exhibitionStatus?.comment}
                        options={EXHIBITION_REASONS.filter(r => r !== 'SI - PRIMERA POSICIÓN (DISPENSER)')}
                        onPhoto={(f: File) => handleAuditPhoto('exhibitionStatus', f)} photo={auditDetails.exhibitionStatus?.photo}
                     />
                     <QuestionCard 
                        label="2. ¿PRESENTA ALGUNA INCIDENCIA?" icon={Info} 
                        value={auditDetails.incidence?.value} onChange={(v: boolean) => updateAuditIndicator('incidence', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('incidence', 'comment', c)} comment={auditDetails.incidence?.comment}
                        reasons={INCIDENCE_REASONS} currentReason={auditDetails.incidence?.reason} onReason={(r: string) => updateAuditIndicator('incidence', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('incidence', f)} photo={auditDetails.incidence?.photo}
                     />
                     <QuestionCard 
                        label="3. ¿SE DEJÓ OK EL ACTIVO?" icon={CheckCircle2} 
                        value={auditDetails.activeStatus?.value} onChange={(v: boolean) => updateAuditIndicator('activeStatus', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('activeStatus', 'comment', c)} comment={auditDetails.activeStatus?.comment}
                        reasons={ACTIVE_FIX_REASONS} currentReason={auditDetails.activeStatus?.reason} onReason={(r: string) => updateAuditIndicator('activeStatus', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('activeStatus', f)} photo={auditDetails.activeStatus?.photo}
                     />
                   </>
                 )}
              </div>
            </section>

            {/* PASO 4: EJECUCIÓN POP (Materiales) - REDISEÑADO SEGÚN IMAGEN */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Sparkles size={18} className="text-[#002060]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">4. Ejecución POP</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden divide-y divide-slate-50">
                  <div className="bg-[#002060] p-4 text-white">
                    <span className="text-[10px] font-black uppercase tracking-widest">Materiales en Punto de Venta</span>
                  </div>

                  {campaigns.map((camp) => (
                    <div key={camp.name} className="p-5 space-y-4">
                      <div className="flex flex-col gap-3">
                        <div className="flex justify-between items-center">
                          <span className="text-[10px] font-black text-[#002060] uppercase leading-tight">{camp.name}</span>
                          <span className="text-[8px] font-black text-rose-500 uppercase italic">Marcar solo una opción</span>
                        </div>

                        <div className="grid grid-cols-2 gap-2">
                           <button 
                             type="button" 
                             onClick={() => updateCampaign(camp.name, { status: 'IMPLEMENTED', incidenceType: null })} 
                             className={`py-3 rounded-xl text-[10px] font-black border transition-all ${camp.status === 'IMPLEMENTED' ? 'bg-[#1e3a5f] border-[#1e3a5f] text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                           >
                             SE IMPLEMENTO
                           </button>
                           <button 
                             type="button" 
                             onClick={() => updateCampaign(camp.name, { status: 'INCIDENCE', implementationType: null })} 
                             className={`py-3 rounded-xl text-[10px] font-black border transition-all ${camp.status === 'INCIDENCE' ? 'bg-rose-600 border-rose-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                           >
                             INCIDENCIA
                           </button>
                        </div>

                        {/* SUB-OPCIONES PARA IMPLEMENTACIÓN */}
                        {camp.status === 'IMPLEMENTED' && (
                          <div className="grid grid-cols-1 gap-2 animate-in slide-in-from-left-2">
                             {[ 'PRIMERA IMPLEMENTACIÓN', 'REABASTECIMIENTO' ].map(type => (
                               <div key={type} className="flex gap-2">
                                  <button 
                                    type="button" 
                                    onClick={() => updateCampaign(camp.name, { implementationType: type as any })}
                                    className={`flex-1 text-left px-4 py-3 rounded-xl text-[10px] font-black border transition-all ${camp.implementationType === type ? 'bg-blue-50 border-blue-400 text-blue-700' : 'bg-white border-slate-100 text-slate-400'}`}
                                  >
                                    {type}
                                  </button>
                                  <button type="button" className={`px-4 rounded-xl text-[9px] font-black uppercase ${camp.implementationType === type ? 'bg-[#92d050] text-[#1e3a5f]' : 'bg-slate-100 text-slate-300'}`}>
                                    AGREGAR
                                  </button>
                               </div>
                             ))}
                          </div>
                        )}

                        {/* SUB-OPCIONES PARA INCIDENCIA */}
                        {camp.status === 'INCIDENCE' && (
                          <div className="grid grid-cols-1 gap-2 animate-in slide-in-from-right-2">
                             {[ 'NO TENGO STOCK DEL MATERIAL', 'OTRO COMENTARIO' ].map(type => (
                               <div key={type} className="flex gap-2">
                                  <button 
                                    type="button" 
                                    onClick={() => updateCampaign(camp.name, { incidenceType: type as any })}
                                    className={`flex-1 text-left px-4 py-3 rounded-xl text-[10px] font-black border transition-all ${camp.incidenceType === type ? 'bg-rose-50 border-rose-400 text-rose-700' : 'bg-white border-slate-100 text-slate-400'}`}
                                  >
                                    {type}
                                  </button>
                                  <button type="button" className={`px-4 rounded-xl text-[9px] font-black uppercase ${camp.incidenceType === type ? 'bg-[#92d050] text-[#1e3a5f]' : 'bg-slate-100 text-slate-300'}`}>
                                    AGREGAR
                                  </button>
                               </div>
                             ))}
                          </div>
                        )}

                        {/* FOTO Y COMENTARIO (SOLO SI SE MARCÓ ESTADO) */}
                        {camp.status && (
                          <div className="flex gap-3 pt-2">
                             <label className={`flex items-center justify-center gap-2 py-3 px-4 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${camp.photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-yellow-400/20 border-yellow-400 text-amber-700'}`}>
                                {camp.photo ? <CheckCircle2 size={16} /> : <Camera size={16} />}
                                <span className="text-[9px] font-black uppercase tracking-widest">{camp.photo ? 'LISTO' : 'FOTO'}</span>
                                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCampaignPhoto(camp.name, e.target.files[0])} />
                             </label>
                             <div className="relative flex-1">
                                <MessageSquare size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                                <input 
                                  type="text" 
                                  placeholder="COMENTARIO..." 
                                  className="w-full bg-slate-50 border-none rounded-2xl py-3 pl-9 pr-4 text-[10px] font-black uppercase shadow-inner" 
                                  value={camp.comment} 
                                  onChange={e => updateCampaign(camp.name, { comment: e.target.value })} 
                                />
                             </div>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
              </div>
            </section>

            {/* PASO 5: INVENTARIO */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Package size={18} className="text-[#1e3a5f]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">5. Inventario</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 space-y-4">
                  <div className="flex bg-slate-200 p-1.5 rounded-2xl shadow-inner">
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VUSE)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VUSE ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500'}`}>VUSE</button>
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VELO)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VELO ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500'}`}>VELO</button>
                  </div>
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" placeholder="FILTRAR SKU..." className="w-full pl-11 pr-4 py-4 bg-white border border-slate-100 rounded-2xl text-[11px] font-black shadow-inner uppercase" value={stockSearch} onChange={e => setStockSearch(e.target.value)} />
                  </div>
                </div>
                <div className="divide-y divide-slate-50 max-h-[350px] overflow-y-auto no-scrollbar">
                  {filteredStockSkus.map(sku => {
                    const data = stockCounts.find(i => i.skuName === sku);
                    return (
                      <div key={sku} className={`px-4 py-4 flex items-center justify-between gap-4 ${data && data.quantity > 0 ? 'bg-blue-50/20' : ''}`}>
                          <span className="text-[10px] font-black text-slate-700 leading-tight flex-1 uppercase">{sku}</span>
                          <div className="flex items-center gap-3">
                             <span className="text-[9px] font-black text-slate-400 uppercase">CANT:</span>
                             <input type="number" placeholder="0" className="w-16 text-center py-2 bg-white border border-slate-200 rounded-xl text-[11px] font-black focus:ring-2 focus:ring-blue-500 outline-none" value={data?.quantity || ''} onChange={e => updateStockItem(sku, parseInt(e.target.value) || 0)} />
                          </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </section>

            {/* PASO FINAL: CIERRE */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><CheckCircle2 size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">Cierre de Visita</h2></div>
              <div className="space-y-4">
                <QuestionCard 
                  label="¿SE DEJARON LIMPIOS Y ORDENADOS LOS ACTIVOS?"
                  icon={CheckCircle2}
                  value={finalAudit.assetsCleaned}
                  onChange={(v: boolean) => setFinalAudit(prev => ({ ...prev, assetsCleaned: v }))}
                  onComment={(c: string) => setFinalAudit(prev => ({ ...prev, comment: c }))}
                  comment={finalAudit.comment}
                  isRequired
                />

                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-blue-50 text-blue-600 rounded-xl"><ImageIcon size={18} /></div>
                    <span className="text-[11px] font-black text-slate-700 uppercase leading-tight">FOTO PANORÁMICA FINAL *</span>
                  </div>
                  <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-2xl border-2 border-dashed transition-all cursor-pointer ${finalAudit.panoramicPhoto ? 'bg-emerald-50 border-emerald-300' : 'bg-yellow-400/20 border-yellow-400 text-amber-700 hover:bg-yellow-400/30'}`}>
                    {finalAudit.panoramicPhoto ? <img src={finalAudit.panoramicPhoto} className="w-full h-full object-cover rounded-2xl" /> : (
                      <div className="flex flex-col items-center gap-2">
                        <Camera size={28} className="text-amber-600" />
                        <span className="text-[9px] font-black uppercase tracking-widest">CAPTURAR FOTO DE CIERRE</span>
                      </div>
                    )}
                    <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleFinalPhoto(e.target.files[0])} />
                  </label>
                </div>
              </div>
            </section>
          </>
        )}

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-slate-100 z-50">
          <button type="submit" disabled={isSubmitting} className={`w-full py-4.5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all ${isStoreOpen ? 'bg-[#1e3a5f] text-white' : 'bg-orange-500 text-white'}`}>
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />} 
            {isStoreOpen ? 'FINALIZAR REPORTE' : 'FIN (LOCAL CERRADO)'}
          </button>
        </div>
      </form>
    </div>
  );
};

