                        onComment={(c: string) => updateAuditIndicator('fefo', 'comment', c)} comment={auditDetails.fefo?.comment}
                        onPhoto={(f: File) => handleAuditPhoto('fefo', f)} photo={auditDetails.fefo?.photo}
                     />
                     <QuestionCard 
                        label="2. ¿CUMPLE LAYOUT? (COMO SE ENCONTRÓ)" icon={LayoutDashboard} 
                        value={auditDetails.initialLayout?.value} onChange={(v: boolean) => updateAuditIndicator('initialLayout', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('initialLayout', 'comment', c)} comment={auditDetails.initialLayout?.comment}
                        reasons={LAYOUT_FAIL_REASONS} currentReason={auditDetails.initialLayout?.reason} onReason={(r: string) => updateAuditIndicator('initialLayout', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('initialLayout', f)} photo={auditDetails.initialLayout?.photo}
                     />
                     <QuestionCard 
                        label="3. ¿SE DEJÓ OK EL LAYOUT?" icon={CheckCircle2} 
                        value={auditDetails.finalLayout?.value} onChange={(v: boolean) => updateAuditIndicator('finalLayout', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('finalLayout', 'comment', c)} comment={auditDetails.finalLayout?.comment}
                        reasons={LAYOUT_FIX_REASONS} currentReason={auditDetails.finalLayout?.reason} onReason={(r: string) => updateAuditIndicator('finalLayout', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('finalLayout', f)} photo={auditDetails.finalLayout?.photo}
                     />
                     <QuestionCard 
                        label="4. SI NO TIENE ACTIVO VUSE, ¿DÓNDE SE GUARDA LA MERCADERÍA?" icon={Database} 
                        value={true} onChange={() => {}} 
                        onComment={(c: string) => updateAuditIndicator('vuseStorage', 'comment', c)} comment={auditDetails.vuseStorage?.comment}
                        onPhoto={(f: File) => handleAuditPhoto('vuseStorage', f)} photo={auditDetails.vuseStorage?.photo}
                     />
                     <QuestionCard 
                        label="5. ¿PRESENTA ALGUNA INCIDENCIA?" icon={Info} 
                        value={auditDetails.incidence?.value} onChange={(v: boolean) => updateAuditIndicator('incidence', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('incidence', 'comment', c)} comment={auditDetails.incidence?.comment}
                        reasons={INCIDENCE_REASONS} currentReason={auditDetails.incidence?.reason} onReason={(r: string) => updateAuditIndicator('incidence', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('incidence', f)} photo={auditDetails.incidence?.photo}
                     />
                     <QuestionCard 
                        label="6. ¿SE DEJÓ OK EL ACTIVO?" icon={CheckCircle2} 
                        value={auditDetails.activeStatus?.value} onChange={(v: boolean) => updateAuditIndicator('activeStatus', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('activeStatus', 'comment', c)} comment={auditDetails.activeStatus?.comment}
                        reasons={ACTIVE_FIX_REASONS} currentReason={auditDetails.activeStatus?.reason} onReason={(r: string) => updateAuditIndicator('activeStatus', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('activeStatus', f)} photo={auditDetails.activeStatus?.photo}
                     />
                   </>
                 )}

                 {(auditDetails.area === AuditArea.CAJONERA || auditDetails.area === AuditArea.DISPENSER) && (
                   <>
                     <QuestionCard 
                        label="1. ¿CONTAMINADO?" icon={Ban} 
                        value={auditDetails.contamination?.value} onChange={(v: boolean) => updateAuditIndicator('contamination', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('contamination', 'comment', c)} comment={auditDetails.contamination?.comment}
                        onPhoto={(f: File) => handleAuditPhoto('contamination', f)} photo={auditDetails.contamination?.photo}
                     />
                     <QuestionCard 
                        label="2. ¿SE DEJÓ SIN CONTAMINACION?" icon={CheckCircle2} 
                        value={auditDetails.finalContamination?.value} onChange={(v: boolean) => updateAuditIndicator('finalContamination', 'value', v)} 
                        onComment={(c: string) => updateAuditIndicator('finalContamination', 'comment', c)} comment={auditDetails.finalContamination?.comment}
                        reasons={ACTIVE_FIX_REASONS} currentReason={auditDetails.finalContamination?.reason} onReason={(r: string) => updateAuditIndicator('finalContamination', 'reason', r)}
                        onPhoto={(f: File) => handleAuditPhoto('finalContamination', f)} photo={auditDetails.finalContamination?.photo}
                     />
                     {auditDetails.area === AuditArea.DISPENSER && (
                        <>
                          <QuestionCard 
                              label="3. ¿SE ENCUENTRA EXHIBIDO CORRECTAMENTE?" icon={LayoutDashboard} 
