                              onPhoto={(f: File) => handleAuditPhoto('exhibitionStatus', f)} photo={auditDetails.exhibitionStatus?.photo}
                          />
                          <QuestionCard 
                              label="4. ¿PRESENTA ALGUNA INCIDENCIA?" icon={Info} 
                              value={auditDetails.incidence?.value} onChange={(v: boolean) => updateAuditIndicator('incidence', 'value', v)} 
                              onComment={(c: string) => updateAuditIndicator('incidence', 'comment', c)} comment={auditDetails.incidence?.comment}
                              reasons={INCIDENCE_REASONS} currentReason={auditDetails.incidence?.reason} onReason={(r: string) => updateAuditIndicator('incidence', 'reason', r)}
                              onPhoto={(f: File) => handleAuditPhoto('incidence', f)} photo={auditDetails.incidence?.photo}
                          />
