              <div className="flex items-center gap-2 px-1"><Sparkles size={18} className="text-[#002060]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">4. Ejecución POP</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden divide-y divide-slate-50">
                  <div className="bg-[#002060] p-4 text-white">
                    <span className="text-[10px] font-black uppercase tracking-widest">Materiales en Punto de Venta</span>
