                        </div>

                        <div className="grid grid-cols-2 gap-2">
                           <button 
                             type="button" 
                             onClick={() => updateCampaign(camp.name, { status: 'IMPLEMENTED', incidenceType: null })} 
                             className={`py-3 rounded-xl text-[10px] font-black border transition-all ${camp.status === 'IMPLEMENTED' ? 'bg-[#1e3a5f] border-[#1e3a5f] text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                           >
                             SE IMPLEMENTO
                           </button>
                           <button 
                             type="button" 
                             onClick={() => updateCampaign(camp.name, { status: 'INCIDENCE', implementationType: null })} 
                             className={`py-3 rounded-xl text-[10px] font-black border transition-all ${camp.status === 'INCIDENCE' ? 'bg-rose-600 border-rose-600 text-white shadow-md' : 'bg-slate-50 border-slate-100 text-slate-500'}`}
                           >
                             INCIDENCIA
                           </button>
                        </div>

                        {camp.status === 'IMPLEMENTED' && (
                          <div className="grid grid-cols-1 gap-2 animate-in slide-in-from-left-2">
                             {[ 'PRIMERA IMPLEMENTACIÓN', 'REABASTECIMIENTO' ].map(type => (
                               <div key={type} className="flex gap-2">
                                  <button 
                                    type="button" 
                                    onClick={() => updateCampaign(camp.name, { implementationType: type as any })}
                                    className={`flex-1 text-left px-4 py-3 rounded-xl text-[10px] font-black border transition-all ${camp.implementationType === type ? 'bg-blue-50 border-blue-400 text-blue-700' : 'bg-white border-slate-100 text-slate-400'}`}
                                  >
                                    {type}
                                  </button>
                                  <button type="button" className={`px-4 rounded-xl text-[9px] font-black uppercase ${camp.implementationType === type ? 'bg-[#92d050] text-[#1e3a5f]' : 'bg-slate-100 text-slate-300'}`}>
                                    AGREGAR
                                  </button>
                               </div>
                             ))}
                          </div>
                        )}

                        {camp.status === 'INCIDENCE' && (
                          <div className="grid grid-cols-1 gap-2 animate-in slide-in-from-right-2">
                             {[ 'NO TENGO STOCK DEL MATERIAL', 'OTRO COMENTARIO' ].map(type => (
                               <div key={type} className="flex gap-2">
                                  <button 
                                    type="button" 
                                    onClick={() => updateCampaign(camp.name, { incidenceType: type as any })}
                                    className={`flex-1 text-left px-4 py-3 rounded-xl text-[10px] font-black border transition-all ${camp.incidenceType === type ? 'bg-rose-50 border-rose-400 text-rose-700' : 'bg-white border-slate-100 text-slate-400'}`}
                                  >
                                    {type}
                                  </button>
                                  <button type="button" className={`px-4 rounded-xl text-[9px] font-black uppercase ${camp.incidenceType === type ? 'bg-[#92d050] text-[#1e3a5f]' : 'bg-slate-100 text-slate-300'}`}>
                                    AGREGAR
                                  </button>
                               </div>
                             ))}
