                                {camp.photo ? <CheckCircle2 size={16} /> : <Camera size={16} />}
                                <span className="text-[9px] font-black uppercase tracking-widest">{camp.photo ? 'LISTO' : 'FOTO'}</span>
                                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCampaignPhoto(camp.name, e.target.files[0])} />
                             </label>
                             <div className="relative flex-1">
                                <MessageSquare size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                                <input 
                                  type="text" 
                                  placeholder="COMENTARIO..." 
                                  className="w-full bg-slate-50 border-none rounded-2xl py-3 pl-9 pr-4 text-[10px] font-black uppercase shadow-inner" 
                                  value={camp.comment} 
                                  onChange={e => updateCampaign(camp.name, { comment: e.target.value })} 
                                />
                             </div>
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
              </div>
            </section>

            {/* PASO 5: CONTEO STOCK - VUSE Y VELO (REDISEÑADO SEGÚN IMAGEN) */}
