              <div className="flex items-center gap-2 px-1"><Package size={18} className="text-[#1e3a5f]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest uppercase">5. Conteo Stock - Vuse y Velo</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-4 bg-slate-50 space-y-4 border-b">
                  <div className="flex bg-slate-200 p-1.5 rounded-2xl shadow-inner">
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VUSE)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VUSE ? 'bg-[#1e3a5f] text-white shadow-md' : 'text-slate-500'}`}>1. CONTEO STOCK - VUSE</button>
                    <button type="button" onClick={() => setActiveStockCategory(SKUCategory.VELO)} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeStockCategory === SKUCategory.VELO ? 'bg-[#1e3a5f] text-white shadow-md' : 'text-slate-500'}`}>2. CONTEO STOCK - VELO</button>
                  </div>
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" placeholder="BUSCAR POR NOMBRE O CÓDIGO (EJ: 6177)..." className="w-full pl-11 pr-4 py-4 bg-white border border-slate-100 rounded-2xl text-[11px] font-black shadow-inner uppercase" value={stockSearch} onChange={e => setStockSearch(e.target.value)} />
                  </div>
                </div>

                <div className="max-h-[500px] overflow-y-auto no-scrollbar bg-slate-50/30 p-4 space-y-3">
                  {filteredStockSkus.length === 0 ? (
                    <div className="text-center py-10 text-slate-400 italic text-[10px] uppercase font-black">No se encontraron productos</div>
                  ) : (
                    filteredStockSkus.map(sku => {
                      const data = stockCounts.find(i => i.skuName === sku);
                      const isCompleted = data && data.quantity > 0 && data.expirationDate !== '';

                      return (
                        <div key={sku} className={`p-4 bg-white rounded-2xl border transition-all ${isCompleted ? 'border-blue-500 shadow-blue-100' : 'border-slate-100 shadow-sm'}`}>
