  Camera, Save, ArrowLeft, Search, Check, Info, ShieldAlert, Store, 
  CheckCircle2, ImageIcon, Package, Sparkles, Loader2, Calendar, 
  ListTodo, LayoutDashboard, Database, HelpCircle, User, MessageSquare, Ban,
  ChevronDown, ArrowRight, Hash, Clock, List, AlertCircle, Wrench, Trophy, Plus
} from 'lucide-react';
import { 
  POSAudit, StoreStatus, SKUCategory, SKU_LISTS, User as UserType, 
  AssignedStore, CURRENT_CAMPAIGNS, CampaignRecord, AuditAccess, 
  DENIAL_REASONS, AuditArea, LAYOUT_FAIL_REASONS, POSAuditDetails,
  AuditIndicator, StockCountItem, FinalAudit, CLOSURE_REASONS,
  LAYOUT_FIX_REASONS, INCIDENCE_REASONS, ACTIVE_FIX_REASONS, EXHIBITION_REASONS,
  OOSRecord, OOS_REASONS, MaintenanceAudit, MAINTENANCE_ASSETS, MAINTENANCE_INCIDENCES,
  CompetitorActivityRecord, COMPETITOR_CATEGORIES, COMPETITOR_ACTIVITIES, MaintenanceRecord
} from '../types';

interface NewAuditFormProps {
  onSave: (audit: POSAudit) => void;
  user: UserType;
  prefillStore?: AssignedStore;
  onCancel: () => void;
}

const NewAuditForm: React.FC<NewAuditFormProps> = ({ onSave, user, prefillStore, onCancel }) => {
  const [storeName] = useState(prefillStore?.name || '');

  // Estados de Apertura
  const [storeStatus, setStoreStatus] = useState<StoreStatus>(StoreStatus.OPEN);
  const [personnelName, setPersonnelName] = useState('');
  const [openingComment, setOpeningComment] = useState('');
  const [closureReason, setClosureReason] = useState('');
  const [statusPhoto, setStatusPhoto] = useState<string | null>(null);

  // Estados de Acceso al Counter
  const [auditAccess, setAuditAccess] = useState<AuditAccess | null>(null);
  const [denialReason, setDenialReason] = useState<string>('');
  const [panoramicBefore, setPanoramicBefore] = useState<string | null>(null);

  // Indicadores PDV
  const [auditDetails, setAuditDetails] = useState<POSAuditDetails>({
    area: AuditArea.CIGARRERA,
    fefo: { value: null, comment: '' },
    initialLayout: { value: null, comment: '' },
    finalLayout: { value: null, comment: '' },
    vuseStorage: { value: null, comment: '' },
    incidence: { value: null, comment: '' },
    activeStatus: { value: null, comment: '' },
    contamination: { value: null, comment: '' },
    finalContamination: { value: null, comment: '' },
    exhibitionStatus: { value: null, comment: '' }
  });

  // Stock e Inventario
  const [stockCounts, setStockCounts] = useState<StockCountItem[]>([]);
  const [stockSearch, setStockSearch] = useState('');
  const [activeStockCategory, setActiveStockCategory] = useState<SKUCategory>(SKUCategory.VUSE);

  // Quiebres (OOS)
  const [oosRecords, setOosRecords] = useState<OOSRecord[]>([]);
  const [oosSearch, setOosSearch] = useState('');
  const [activeOosCategory, setActiveOosCategory] = useState<SKUCategory>(SKUCategory.CIGARRILLOS);

  // Mantenimientos
  const [maintenance, setMaintenance] = useState<MaintenanceAudit>({
    items: MAINTENANCE_ASSETS.map(asset => ({ asset, status: null })),
    generalComment: ''
  });

  // Competencia
  const [competitorActivities, setCompetitorActivities] = useState<CompetitorActivityRecord[]>([]);

  // Campañas
  const [campaigns, setCampaigns] = useState<CampaignRecord[]>(
    CURRENT_CAMPAIGNS.map(name => ({ name, status: null, comment: '' }))
  );

  // Auditoría Final
  const [finalAudit, setFinalAudit] = useState<FinalAudit>({
    assetsCleaned: null,
    comment: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);

  // Visibilidad
  const isStoreOpen = storeStatus === StoreStatus.OPEN;
  const showAuditFlow = isStoreOpen && auditAccess !== null;

  // Filtros
  const filteredStockSkus = useMemo(() => {
    const list = SKU_LISTS[activeStockCategory];
    return stockSearch ? list.filter(sku => sku.toLowerCase().includes(stockSearch.toLowerCase())) : list;
  }, [activeStockCategory, stockSearch]);

  const filteredOosSkus = useMemo(() => {
    const list = SKU_LISTS[activeOosCategory];
    return oosSearch ? list.filter(sku => sku.toLowerCase().includes(oosSearch.toLowerCase())) : list;
  }, [activeOosCategory, oosSearch]);

  // Handlers
  const handleStatusPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setStatusPhoto(reader.result as string);
    reader.readAsDataURL(file);
  };

  const handlePanoramicBefore = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setPanoramicBefore(reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateAuditIndicator = (key: keyof POSAuditDetails, field: keyof AuditIndicator, value: any) => {
    setAuditDetails(prev => ({ ...prev, [key]: { ...(prev[key] || { value: null, comment: '' }), [field]: value } }));
  };

  const handleAuditPhoto = (key: keyof POSAuditDetails, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateAuditIndicator(key, 'photo', reader.result as string);
    reader.readAsDataURL(file);
  };

  const updateStockItem = (skuName: string, field: keyof StockCountItem, value: any) => {
    setStockCounts(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      return existing 
        ? prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i)
        : [...prev, { skuName, quantity: field === 'quantity' ? value : 0, expirationDate: field === 'expirationDate' ? value : '' }];
    });
  };

  const updateOosRecord = (skuName: string, field: keyof OOSRecord, value: any) => {
    setOosRecords(prev => {
      const existing = prev.find(i => i.skuName === skuName);
      return existing 
        ? prev.map(i => i.skuName === skuName ? { ...i, [field]: value } : i)
        : [...prev, { skuName, meetsMinStock: field === 'meetsMinStock' ? value : null, comment: field === 'comment' ? value : '' }];
    });
  };

  // Fixed spread types error by properly typing updates as Partial<MaintenanceRecord>
  const updateMaintenanceItem = (asset: string, updates: Partial<MaintenanceRecord>) => {
    setMaintenance(prev => ({ ...prev, items: prev.items.map(i => i.asset === asset ? { ...i, ...updates } : i) }));
  };

  const addCompetitorActivity = (category: string, activity: string) => {
    setCompetitorActivities(prev => [...prev, { category, activity, observations: '' }]);
  };

  const updateCompetitorActivity = (idx: number, updates: Partial<CompetitorActivityRecord>) => {
    setCompetitorActivities(prev => prev.map((item, i) => i === idx ? { ...item, ...updates } : item));
  };

  const handleCompPhoto = (idx: number, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => updateCompetitorActivity(idx, { photo: reader.result as string });
    reader.readAsDataURL(file);
  };

  const handleFinalPhoto = (file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setFinalAudit(prev => ({ ...prev, panoramicPhoto: reader.result as string }));
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!statusPhoto) { alert('La FOTO de fachada es obligatoria.'); return; }
    setIsSubmitting(true);
    const finalize = (coords?: {lat: number, lng: number}) => {
      const audit: POSAudit = {
        id: crypto.randomUUID(), timestamp: Date.now(), storeId: prefillStore?.id, storeName, address: prefillStore?.address || '',
        auditorId: user.id, auditorName: user.name, storeStatus, statusPhotoBase64: statusPhoto || undefined,
        personnelName: isStoreOpen ? personnelName : undefined, openingComment: isStoreOpen ? openingComment : undefined,
        closureReason: !isStoreOpen ? closureReason : undefined, panoramicPhotoBefore: panoramicBefore || undefined,
        auditAccess: auditAccess || undefined, details: showAuditFlow ? auditDetails : undefined,
        stockCounts: showAuditFlow ? stockCounts : undefined, campaigns: showAuditFlow ? campaigns : undefined,
        oosRecords: showAuditFlow ? oosRecords : undefined, maintenance: showAuditFlow ? maintenance : undefined,
        competitorActivities: showAuditFlow ? competitorActivities : undefined, finalAudit: showAuditFlow ? finalAudit : undefined,
        items: [], oosItems: [], checklist: [], location: coords
      };
      onSave(audit);
    };
    navigator.geolocation.getCurrentPosition(pos => finalize({ lat: pos.coords.latitude, lng: pos.coords.longitude }), () => finalize());
  };

  // UI Helpers
  const QuestionCard = ({ label, icon: Icon, value, onChange, photo, onPhoto, comment, onComment, reasons, currentReason, onReason, isRequired, options }: any) => (
    <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-4 animate-in fade-in slide-in-from-bottom-2">
      <div className="flex justify-between items-start gap-3">
        <div className="flex gap-3">
          <div className={`p-2 rounded-xl shrink-0 ${value === null ? 'bg-slate-50 text-slate-400' : 'bg-blue-50 text-blue-600'}`}><Icon size={18} /></div>
          <span className="text-[11px] font-black text-slate-700 uppercase leading-tight mt-1">{label} {isRequired && <span className="text-rose-500">*</span>}</span>
        </div>
        {!options && (
          <div className="flex bg-slate-100 p-1 rounded-xl shadow-inner shrink-0">
            <button type="button" onClick={() => onChange(true)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === true ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400'}`}>SI</button>
            <button type="button" onClick={() => onChange(false)} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${value === false ? 'bg-white text-rose-600 shadow-sm' : 'text-slate-400'}`}>NO</button>
          </div>
        )}
      </div>
      {options && (
        <div className="grid gap-2">{options.map((opt: string) => (<button key={opt} type="button" onClick={() => onChange(opt)} className={`w-full text-left px-4 py-3 rounded-2xl text-[10px] font-black border transition-all ${value === opt ? 'bg-blue-600 border-blue-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{opt}</button>))}</div>
      )}
      {reasons && value === false && (
        <div className="flex flex-wrap gap-2 pt-1">{reasons.map((r: string) => (<button key={r} type="button" onClick={() => onReason(r)} className={`px-3 py-1.5 rounded-xl text-[9px] font-bold border transition-all ${currentReason === r ? 'bg-[#1e3a5f] border-[#1e3a5f] text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>))}</div>
      )}
      <div className="space-y-3">
        {onComment && (<div className="relative"><MessageSquare size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" /><input type="text" placeholder="COMENTARIO..." className="w-full bg-slate-50 border-none rounded-2xl py-2.5 pl-9 pr-4 text-[10px] font-black shadow-inner uppercase outline-none focus:ring-2 focus:ring-blue-100" value={comment || ''} onChange={e => onComment(e.target.value)} /></div>)}
        {onPhoto && value !== null && (
          <label className={`flex items-center justify-center gap-2 py-3.5 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${photo ? 'bg-emerald-50 border-emerald-200 text-emerald-600' : 'bg-yellow-400/20 border-yellow-400 text-amber-700'}`}>
            {photo ? <CheckCircle2 size={18} /> : <Camera size={18} />}<span className="text-[10px] font-black uppercase tracking-widest">{photo ? 'LISTO' : 'FOTO'}</span>
            <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && onPhoto(e.target.files[0])} />
          </label>
        )}
      </div>
    </div>
  );

  return (
    <div className="animate-in slide-in-from-bottom-4 duration-500 pb-32">
      <div className="bg-[#1e3a5f] text-white p-4 flex items-center justify-between -mx-4 -mt-8 mb-6 sticky top-0 z-50 shadow-lg">
        <div className="flex items-center gap-4"><button type="button" onClick={onCancel} className="p-1 active:scale-90 transition-transform"><ArrowLeft size={24} /></button><div><h1 className="text-lg font-black uppercase truncate max-w-[200px]">{storeName || 'Nueva Visita'}</h1><p className="text-[10px] text-blue-300 font-bold uppercase mt-1 tracking-widest">Auditoría Trade Marketing</p></div></div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-8">
        {/* PASO 1-4: APERTURA E INDICADORES (YA IMPLEMENTADOS) */}
        <section className="space-y-4">
          <div className="flex items-center gap-2 px-1"><Store size={18} className="text-blue-600" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">1. Apertura</h2></div>
          <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm space-y-6">
            <div className="flex justify-between items-center bg-[#002060] p-4 rounded-2xl text-white">
              <span className="text-[11px] font-black uppercase tracking-widest">LOCAL ABIERTO</span>
              <div className="flex bg-white/10 p-1 rounded-xl border border-white/20">
                <button type="button" onClick={() => setStoreStatus(StoreStatus.OPEN)} className={`px-5 py-2 rounded-lg text-[10px] font-black transition-all ${isStoreOpen ? 'bg-white text-[#002060]' : 'text-white/60'}`}>SI</button>
                <button type="button" onClick={() => setStoreStatus(StoreStatus.CLOSED)} className={`px-5 py-2 rounded-lg text-[10px] font-black transition-all ${!isStoreOpen ? 'bg-white text-rose-600' : 'text-white/60'}`}>NO</button>
              </div>
            </div>
            {isStoreOpen ? (
              <div className="space-y-4"><input type="text" placeholder="NOMBRE PERSONAL..." className="w-full p-4 bg-slate-50 rounded-2xl text-xs font-black uppercase shadow-inner outline-none" value={personnelName} onChange={e => setPersonnelName(e.target.value)} /><input type="text" placeholder="COMENTARIO APERTURA..." className="w-full p-4 bg-slate-50 rounded-2xl text-xs font-black uppercase shadow-inner outline-none" value={openingComment} onChange={e => setOpeningComment(e.target.value)} /></div>
            ) : (
              <div className="grid gap-2">{CLOSURE_REASONS.map(r => (<button key={r} type="button" onClick={() => setClosureReason(r)} className={`w-full text-left p-4 rounded-2xl text-[10px] font-black border transition-all ${closureReason === r ? 'bg-rose-600 border-rose-600 text-white' : 'bg-slate-50 border-slate-100 text-slate-500'}`}>{r}</button>))}</div>
            )}
            <label className={`relative block aspect-video w-full rounded-2xl border-2 border-dashed overflow-hidden cursor-pointer transition-all ${statusPhoto ? 'bg-emerald-50 border-emerald-300' : 'bg-yellow-400/20 border-yellow-400'}`}>
              {statusPhoto ? <img src={statusPhoto} className="w-full h-full object-cover" /> : (<div className="w-full h-full flex flex-col items-center justify-center gap-2 text-red-600"><Camera size={32} /><span className="text-[10px] font-black uppercase">FOTO OBLIGATORIA</span></div>)}
              <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleStatusPhoto(e.target.files[0])} />
            </label>
          </div>
        </section>

        {showAuditFlow && (
          <>
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><ImageIcon size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">2. Registro Inicial</h2></div>
              <label className={`relative flex flex-col items-center justify-center w-full aspect-video rounded-3xl border-2 border-dashed transition-all cursor-pointer shadow-sm ${panoramicBefore ? 'bg-blue-50 border-blue-300' : 'bg-white border-slate-200 text-slate-400'}`}>
                {panoramicBefore ? <img src={panoramicBefore} className="w-full h-full object-cover rounded-3xl" /> : <div className="flex flex-col items-center gap-3"><Camera size={28} /><span className="text-[10px] font-black uppercase tracking-widest">FOTO PANORÁMICA PREVIA *</span></div>}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handlePanoramicBefore(e.target.files[0])} />
              </label>
            </section>

            {/* PASO 5: CONTEO STOCK (VISTA RESUMIDA) */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Package size={18} className="text-[#1e3a5f]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">5. Conteo Stock e Inventario</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-3 bg-slate-50 flex gap-2 overflow-x-auto no-scrollbar border-b">
                  {Object.values(SKUCategory).map(cat => (<button key={cat} type="button" onClick={() => setActiveStockCategory(cat)} className={`flex-1 py-2 px-4 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${activeStockCategory === cat ? 'bg-[#1e3a5f] text-white' : 'text-slate-500 bg-white'}`}>{cat}</button>))}
                </div>
                <div className="divide-y divide-slate-100 max-h-[400px] overflow-y-auto no-scrollbar">
                  <div className="grid grid-cols-[1fr,60px,110px] gap-2 px-4 py-2 bg-slate-100 text-[8px] font-black text-slate-400 uppercase"><span>PRODUCTO</span><span className="text-center">CANT.</span><span className="text-center">VENC.</span></div>
                  {filteredStockSkus.map(sku => {
                    const data = stockCounts.find(i => i.skuName === sku);
                    return (
                      <div key={sku} className={`grid grid-cols-[1fr,60px,110px] gap-2 px-4 py-3 items-center ${data?.quantity ? 'bg-blue-50/30' : ''}`}>
                        <span className="text-[9px] font-black text-slate-700 uppercase truncate leading-tight">{sku}</span>
                        <input type="number" placeholder="0" className="w-full py-2 bg-white border border-slate-200 rounded-lg text-center text-[10px] font-black outline-none focus:ring-2 focus:ring-blue-500" value={data?.quantity || ''} onChange={e => updateStockItem(sku, 'quantity', parseInt(e.target.value) || 0)} />
                        <input type="date" className="w-full py-2 bg-white border border-slate-200 rounded-lg text-center text-[9px] font-black outline-none focus:ring-2 focus:ring-blue-500" value={data?.expirationDate || ''} onChange={e => updateStockItem(sku, 'expirationDate', e.target.value)} />
                      </div>
                    );
                  })}
                </div>
              </div>
            </section>

            {/* PASO 6: QUIEBRES (STOCK MINIMO) */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><AlertCircle size={18} className="text-rose-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">6. ¿Cumple Stock Mínimo? (Quiebres)</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden">
                <div className="p-3 bg-slate-50 flex gap-2 overflow-x-auto no-scrollbar border-b">
                  {Object.values(SKUCategory).map(cat => (<button key={cat} type="button" onClick={() => setActiveOosCategory(cat)} className={`flex-1 py-2 px-4 rounded-xl text-[9px] font-black uppercase transition-all whitespace-nowrap ${activeOosCategory === cat ? 'bg-rose-600 text-white' : 'text-slate-500 bg-white'}`}>{cat}</button>))}
                </div>
                <div className="divide-y divide-slate-100 max-h-[400px] overflow-y-auto no-scrollbar">
                   <div className="grid grid-cols-[1fr,80px,120px] gap-2 px-4 py-2 bg-slate-100 text-[8px] font-black text-slate-400 uppercase"><span>PRODUCTO</span><span className="text-center">CUMPLE?</span><span>MOTIVO (SI NO CUMPLE)</span></div>
                   {filteredOosSkus.map(sku => {
                     const data = oosRecords.find(i => i.skuName === sku);
                     return (
                       <div key={sku} className={`grid grid-cols-[1fr,80px,120px] gap-2 px-4 py-3 items-center ${data?.meetsMinStock === false ? 'bg-rose-50/40' : ''}`}>
                         <span className="text-[9px] font-black text-slate-700 uppercase truncate">{sku}</span>
                         <div className="flex gap-1">
                           <button type="button" onClick={() => updateOosRecord(sku, 'meetsMinStock', true)} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black ${data?.meetsMinStock === true ? 'bg-emerald-500 text-white shadow-sm' : 'bg-slate-100 text-slate-400'}`}>SI</button>
                           <button type="button" onClick={() => updateOosRecord(sku, 'meetsMinStock', false)} className={`flex-1 py-1.5 rounded-lg text-[8px] font-black ${data?.meetsMinStock === false ? 'bg-rose-600 text-white shadow-sm' : 'bg-slate-100 text-slate-400'}`}>NO</button>
                         </div>
                         <select className={`w-full py-2 bg-white border border-slate-200 rounded-lg text-[9px] font-black outline-none ${data?.meetsMinStock === false ? 'border-rose-300' : 'opacity-30'}`} disabled={data?.meetsMinStock !== false} value={data?.comment || ''} onChange={e => updateOosRecord(sku, 'comment', e.target.value)}>
                            <option value="">...</option>
                            {OOS_REASONS.map(r => <option key={r} value={r}>{r}</option>)}
                         </select>
                       </div>
                     );
                   })}
                </div>
              </div>
            </section>

            {/* PASO 7: MANTENIMIENTOS */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Wrench size={18} className="text-[#92d050]" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">7. Mantenimientos de Activos</h2></div>
              <div className="bg-[#92d050] text-[#1e3a5f] p-4 rounded-3xl space-y-4 shadow-sm border border-[#7eb244]">
                <div className="space-y-3">
                  {maintenance.items.map(item => (
                    <div key={item.asset} className="bg-white/90 backdrop-blur p-4 rounded-2xl space-y-3">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black uppercase text-[#1e3a5f]">{item.asset}</span>
                        <div className="flex gap-1.5 p-1 bg-slate-100 rounded-xl">
                          <button type="button" onClick={() => updateMaintenanceItem(item.asset, { status: 'BUEN ESTADO' })} className={`px-3 py-1.5 rounded-lg text-[8px] font-black transition-all ${item.status === 'BUEN ESTADO' ? 'bg-[#1e3a5f] text-white shadow-md' : 'text-slate-400'}`}>BUENO</button>
                          <button type="button" onClick={() => updateMaintenanceItem(item.asset, { status: 'MAL ESTADO' })} className={`px-3 py-1.5 rounded-lg text-[8px] font-black transition-all ${item.status === 'MAL ESTADO' ? 'bg-rose-600 text-white shadow-md' : 'text-slate-400'}`}>MALO</button>
                        </div>
                      </div>
                      {item.status === 'MAL ESTADO' && (
                        <div className="animate-in slide-in-from-top-2">
                           <label className="text-[8px] font-black text-slate-400 uppercase block mb-1">INCIDENCIA ESPECÍFICA</label>
                           <select className="w-full p-2.5 bg-white border border-slate-200 rounded-xl text-[9px] font-black outline-none" value={item.incidenceType || ''} onChange={e => updateMaintenanceItem(item.asset, { incidenceType: e.target.value })}>
                              <option value="">SELECCIONAR...</option>
                              {MAINTENANCE_INCIDENCES.map(inc => <option key={inc} value={inc}>{inc}</option>)}
                           </select>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
                <div className="space-y-3 pt-2">
                   <textarea placeholder="COMENTARIO GENERAL PARA MANTENIMIENTO..." className="w-full p-4 bg-white/95 rounded-2xl text-[10px] font-black uppercase outline-none shadow-inner min-h-[80px]" value={maintenance.generalComment} onChange={e => setMaintenance(prev => ({ ...prev, generalComment: e.target.value }))} />
                   <label className={`flex items-center justify-center gap-3 py-4 rounded-2xl border-2 border-dashed transition-all cursor-pointer ${maintenance.photo ? 'bg-emerald-500 border-white text-white' : 'bg-[#1e3a5f] border-white/20 text-white hover:bg-[#152946]'}`}>
                     {maintenance.photo ? <CheckCircle2 size={20} /> : <Camera size={20} />}
                     <span className="text-[10px] font-black uppercase tracking-[0.2em]">{maintenance.photo ? 'FOTO CAPTURADA' : 'FOTO MANTENIMIENTOS'}</span>
                     <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => {
                       const reader = new FileReader();
                       reader.onloadend = () => setMaintenance(prev => ({ ...prev, photo: reader.result as string }));
                       if (e.target.files?.[0]) reader.readAsDataURL(e.target.files[0]);
                     }} />
                   </label>
                </div>
              </div>
            </section>

            {/* PASO 8: ACTIVIDADES DE LA COMPETENCIA */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><Trophy size={18} className="text-blue-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">8. Actividades de la Competencia</h2></div>
              <div className="bg-white rounded-3xl border border-slate-100 shadow-sm overflow-hidden divide-y divide-slate-50">
                 <div className="p-5 bg-slate-50 space-y-4">
                   <div className="flex gap-2">
                      {COMPETITOR_CATEGORIES.map(cat => (
                        <div key={cat} className="flex-1 space-y-2">
                           <span className="text-[9px] font-black text-slate-400 uppercase px-1">{cat}</span>
                           <div className="flex flex-col gap-1.5">
                              {COMPETITOR_ACTIVITIES.map(act => (
                                <button key={act} type="button" onClick={() => addCompetitorActivity(cat, act)} className="text-left px-3 py-2 bg-white border border-slate-100 rounded-xl text-[9px] font-black hover:border-blue-500 hover:text-blue-600 transition-all flex justify-between items-center group">
                                  {act} <Plus size={12} className="text-slate-300 group-hover:text-blue-500" />
                                </button>
                              ))}
                           </div>
                        </div>
                      ))}
                   </div>
                 </div>

                 <div className="p-5 space-y-4 bg-white">
                   {competitorActivities.length === 0 ? (
                     <div className="text-center py-6 text-slate-400 text-[9px] font-black uppercase italic">No se han registrado hallazgos</div>
                   ) : (
                     <div className="space-y-4">
                       {competitorActivities.map((hallazgo, idx) => (
                         <div key={idx} className="bg-slate-50 p-4 rounded-2xl border border-slate-100 space-y-3 animate-in slide-in-from-right-4">
                            <div className="flex justify-between items-center">
                              <div className="flex flex-col">
                                <span className="text-[8px] font-black text-blue-600 uppercase tracking-widest">{hallazgo.category}</span>
                                <span className="text-[10px] font-black text-slate-700 uppercase">{hallazgo.activity}</span>
                              </div>
                              <button type="button" onClick={() => setCompetitorActivities(prev => prev.filter((_, i) => i !== idx))} className="p-1.5 text-rose-500 hover:bg-rose-50 rounded-lg"><Ban size={14} /></button>
                            </div>
                            <div className="flex gap-3">
                               <label className={`w-20 h-20 rounded-xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all overflow-hidden ${hallazgo.photo ? 'border-emerald-500' : 'border-slate-200'}`}>
                                  {hallazgo.photo ? <img src={hallazgo.photo} className="w-full h-full object-cover" /> : <Camera size={20} className="text-slate-300" />}
                                  <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleCompPhoto(idx, e.target.files[0])} />
                               </label>
                               <textarea placeholder="OBSERVACIONES..." className="flex-1 p-3 bg-white border border-slate-100 rounded-xl text-[9px] font-black uppercase outline-none focus:ring-2 focus:ring-blue-500 min-h-[80px]" value={hallazgo.observations} onChange={e => updateCompetitorActivity(idx, { observations: e.target.value })} />
                            </div>
                         </div>
                       ))}
                     </div>
                   )}
                 </div>
              </div>
            </section>

            {/* PASO FINAL: CIERRE */}
            <section className="space-y-4">
              <div className="flex items-center gap-2 px-1"><CheckCircle2 size={18} className="text-amber-500" /><h2 className="text-xs font-black text-slate-400 uppercase tracking-widest">9. Finalizar Visita</h2></div>
              <QuestionCard label="¿ACTIVOS LIMPIOS Y ORDENADOS?" icon={Sparkles} value={finalAudit.assetsCleaned} onChange={(v: boolean) => setFinalAudit(prev => ({ ...prev, assetsCleaned: v }))} isRequired onComment={(c: string) => setFinalAudit(prev => ({ ...prev, comment: c }))} comment={finalAudit.comment} />
              <label className={`relative block aspect-video w-full rounded-3xl border-2 border-dashed overflow-hidden cursor-pointer transition-all ${finalAudit.panoramicPhoto ? 'bg-emerald-50 border-emerald-300 shadow-inner' : 'bg-[#1e3a5f] border-white/20 text-white'}`}>
                {finalAudit.panoramicPhoto ? <img src={finalAudit.panoramicPhoto} className="w-full h-full object-cover" /> : <div className="w-full h-full flex flex-col items-center justify-center gap-2"><Camera size={32} /><span className="text-[10px] font-black uppercase tracking-widest">FOTO PANORÁMICA FINAL *</span></div>}
                <input type="file" accept="image/*" capture="environment" className="hidden" onChange={e => e.target.files?.[0] && handleFinalPhoto(e.target.files[0])} />
              </label>
            </section>
          </>
        )}

        <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 backdrop-blur-md border-t border-slate-100 z-[49]">
          <button type="submit" disabled={isSubmitting} className={`w-full py-4.5 rounded-2xl font-black uppercase tracking-[0.2em] shadow-2xl flex items-center justify-center gap-3 active:scale-95 transition-all ${isStoreOpen ? 'bg-[#1e3a5f] text-white shadow-blue-900/40' : 'bg-orange-500 text-white'}`}>
            {isSubmitting ? <Loader2 className="animate-spin" /> : <Save size={20} />} 
            {isStoreOpen ? 'FINALIZAR REPORTE' : 'FIN (LOCAL CERRADO)'}
          </button>
        </div>
      </form>
    </div>
  );
};

