              {auditAccess === AuditAccess.DENIED && (
                <div className="p-4 bg-blue-50 border border-blue-200 rounded-2xl flex items-start gap-3 animate-in fade-in slide-in-from-top-2">
                   <Info className="text-blue-600 shrink-0" size={18} />
                   <p className="text-[11px] font-black text-blue-800 uppercase leading-relaxed italic">
                     ¡Asi no te permita tomar información igual puedes trabajar por la parte fuera del counter! ¡Implementar materiales!
