import React from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend } from 'recharts';
import { TrendingUp, Package, AlertCircle, CheckCircle, Ban, Users, Map as MapIcon } from 'lucide-react';
import { POSAudit, DashboardStats, StoreStatus } from '../types';

interface DashboardProps {
  audits: POSAudit[];
}

const Dashboard: React.FC<DashboardProps> = ({ audits }) => {
  const stats: DashboardStats = {
    totalAudits: audits.length,
    totalMaterials: audits.reduce((acc, curr) => acc + (curr.items?.reduce((a, c) => a + c.quantity, 0) || 0), 0),
    complianceRate: audits.length > 0 
      ? Math.round((audits.reduce((acc, curr) => {
          const items = curr.items || [];
          const perfect = items.filter(i => i.condition === 'Perfecto Estado').length;
          return acc + (perfect / Math.max(1, items.length));
        }, 0) / audits.length) * 100)
      : 0,
    pendingActions: audits.reduce((acc, curr) => 
      acc + (curr.items?.filter(i => i.condition === 'Faltante' || i.condition === 'Dañado / Sucio').length || 0), 0
    ),
    totalOOS: audits.reduce((acc, curr) => acc + (curr.oosRecords?.filter(r => r.meetsMinStock === false).length || 0), 0),
  };

  // Avance por Promotor
  const auditorStatsMap = audits.reduce((acc, audit) => {
    acc[audit.auditorName] = (acc[audit.auditorName] || 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  const auditorData = Object.entries(auditorStatsMap).map(([name, count]) => ({ name, count }));

  // Tiendas con más quiebres
  const storeOosMap = audits.reduce((acc, audit) => {
    const oosCount = audit.oosRecords?.filter(r => r.meetsMinStock === false).length || 0;
    if (oosCount > 0) {
      acc[audit.storeName] = (acc[audit.storeName] || 0) + oosCount;
    }
    return acc;
  }, {} as Record<string, number>);

  const oosByStoreData = Object.entries(storeOosMap)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 5);

  const conditionData = [
    { name: 'Perfecto', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Perfecto Estado').length || 0), 0), color: '#10b981' },
    { name: 'Dañado', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Dañado / Sucio').length || 0), 0), color: '#f59e0b' },
    { name: 'Faltante', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Faltante').length || 0), 0), color: '#ef4444' },
    { name: 'Antiguo', value: audits.reduce((acc, a) => acc + (a.items?.filter(i => i.condition === 'Desactualizado').length || 0), 0), color: '#6366f1' },
  ].filter(d => d.value > 0);

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <header>
        <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">Panel de Control</h1>
        <p className="text-slate-500 mt-1">Análisis ejecutivo de ejecución trade marketing y quiebres.</p>
      </header>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
        {[
          { label: 'Auditorías', value: stats.totalAudits, icon: TrendingUp, color: 'blue' },
