      <div className={`p-4 rounded-2xl border flex gap-3 animate-in slide-in-from-top-2 ${isSuccess ? 'bg-emerald-50 border-emerald-100 text-emerald-800' : 'bg-rose-50 border-rose-100 text-rose-800'}`}>
