            {allowAi && photo && (
              <button type="button" onClick={() => aiAction && aiAction(photo)} className="px-4 bg-blue-600 text-white rounded-2xl shadow-lg flex items-center justify-center active:scale-90 transition-all">
                <Sparkle size={18} />
